DateTime? _trackerParseServerInstant(dynamic value) {
  final raw = '${value ?? ''}'.trim();
  if (raw.isEmpty || raw == 'null') return null;
  final normalized = raw.replaceFirst(' ', 'T');
  final hasZone = RegExp(r'(Z|[+-]\d{2}:?\d{2})$', caseSensitive: false)
      .hasMatch(normalized);
  if (hasZone) return DateTime.tryParse(normalized)?.toUtc();

  final naive = DateTime.tryParse(normalized);
  if (naive == null) return null;
  // Серверные MySQL-строки без timezone считаем UTC.
  return DateTime.utc(
    naive.year,
    naive.month,
    naive.day,
    naive.hour,
    naive.minute,
    naive.second,
    naive.millisecond,
    naive.microsecond,
  );
}

DateTime? _trackerMoscowDateTime(dynamic value) {
  final instant = _trackerParseServerInstant(value);
  if (instant == null) return null;
  final moscow = instant.add(const Duration(hours: 3));
  // Возвращаем wall-clock Moscow без зависимости от timezone устройства.
  return DateTime(
    moscow.year,
    moscow.month,
    moscow.day,
    moscow.hour,
    moscow.minute,
    moscow.second,
    moscow.millisecond,
    moscow.microsecond,
  );
}

DateTime _trackerMoscowFromEpochMs(int millisecondsSinceEpoch) {
  final moscow = DateTime.fromMillisecondsSinceEpoch(
    millisecondsSinceEpoch,
    isUtc: true,
  ).add(const Duration(hours: 3));
  return DateTime(
    moscow.year,
    moscow.month,
    moscow.day,
    moscow.hour,
    moscow.minute,
    moscow.second,
    moscow.millisecond,
    moscow.microsecond,
  );
}

enum TrackerLiveSourceMode {
  trackerExperimental,
  heartRateOnly,
}

enum TrackerTrainingActivity {
  footballField,
  outdoorRun,
  indoorStrength,
}

enum _LiveSessionExitAction { stay, pause, exitWithoutSaving, stopAndSave }

enum _LiveMobileSheetTab { team, players, field, operator }

extension TrackerTrainingActivityUi on TrackerTrainingActivity {
  String get code {
    switch (this) {
      case TrackerTrainingActivity.footballField:
        return 'football_field';
      case TrackerTrainingActivity.outdoorRun:
        return 'outdoor_run';
      case TrackerTrainingActivity.indoorStrength:
        return 'indoor_strength';
    }
  }

  String get title {
    switch (this) {
      case TrackerTrainingActivity.footballField:
        return 'Футбол / поле';
      case TrackerTrainingActivity.outdoorRun:
        return 'Кросс / улица';
      case TrackerTrainingActivity.indoorStrength:
        return 'Зал / силовая';
    }
  }

  String get shortTitle {
    switch (this) {
      case TrackerTrainingActivity.footballField:
        return 'Поле';
      case TrackerTrainingActivity.outdoorRun:
        return 'Кросс';
      case TrackerTrainingActivity.indoorStrength:
        return 'Зал';
    }
  }

  String get subtitle {
    switch (this) {
      case TrackerTrainingActivity.footballField:
        return 'карта поля, тепловая карта, зоны и координаты';
      case TrackerTrainingActivity.outdoorRun:
        return 'маршрут, дистанция, темп, скорость без калибровки поля';
      case TrackerTrainingActivity.indoorStrength:
        return 'таймер, нагрузка и заметки; GPS в помещении не обязателен';
    }
  }

  bool get requiresField => this == TrackerTrainingActivity.footballField;

  IconData get icon {
    switch (this) {
      case TrackerTrainingActivity.footballField:
        return Icons.sports_soccer_rounded;
      case TrackerTrainingActivity.outdoorRun:
        return Icons.directions_run_rounded;
      case TrackerTrainingActivity.indoorStrength:
        return Icons.fitness_center_rounded;
    }
  }
}

class TrackerLivePanel extends StatefulWidget {
  const TrackerLivePanel({
    super.key,
    required this.clubId,
    this.userId = 0,
    required this.teamId,
    required this.teamName,
    required this.players,
    required this.selectedPlayer,
    required this.selectedField,
    required this.ble,
    this.savedDevices = const [],
    this.heartRateByPlayerId = const <int, HeartRateSample>{},
    this.heartRateConnectedCount = 0,
    this.batteryPercent,
    this.scanningBluetooth = false,
    this.onScanBluetooth,
    this.onManageTrackers,
    this.onManagePlayerDevices,
    this.onResetTeamGps,
    this.onSelectPlayer,
    this.onLiveRunningChanged,
    this.onLiveSessionIdChanged,
    this.onStartTeamLive,
    this.onStopTeamLive,
    this.localTeamSessionsProvider,
    this.teamTrackerCount = 0,
    this.connectedTeamPlayerIds = const <int>{},
    this.initialLiveRunning = false,
    this.initialLiveSessionId,
    this.startRequestSignal = 0,
    this.pauseRequestSignal = 0,
    this.stopRequestSignal = 0,
    this.exitWithoutSaveRequestSignal = 0,
    this.externalRefreshSignal = 0,
    this.workspaceFullscreen = true,
    this.onWorkspaceFullscreenChanged,
  });

  final int clubId;
  final int userId;
  final int teamId;
  final String teamName;
  final List<TrackerPlayerOption> players;
  final TrackerPlayerOption? selectedPlayer;
  final TrackerFieldModel? selectedField;
  final ActionTrackerBleService ble;
  final List<TrackerDeviceModel> savedDevices;
  final Map<int, HeartRateSample> heartRateByPlayerId;
  final int heartRateConnectedCount;
  final int? batteryPercent;
  final bool scanningBluetooth;
  final VoidCallback? onScanBluetooth;
  final VoidCallback? onManageTrackers;
  final ValueChanged<TrackerPlayerOption>? onManagePlayerDevices;
  final VoidCallback? onResetTeamGps;
  final ValueChanged<TrackerPlayerOption>? onSelectPlayer;
  final ValueChanged<bool>? onLiveRunningChanged;
  final ValueChanged<int?>? onLiveSessionIdChanged;
  final Future<int?> Function()? onStartTeamLive;
  final Future<void> Function(bool createFinalSession)? onStopTeamLive;
  /// Текущие BLE-метрики командного Live из родительского координатора.
  /// Вызывается локально и поэтому работает даже при зависшем/недоступном API.
  final List<TrackerLiveSessionModel> Function()? localTeamSessionsProvider;
  final int teamTrackerCount;
  final Set<int> connectedTeamPlayerIds;
  /// Локальное состояние Team Live из родительского координатора. Оно не
  /// зависит от HTTP и позволяет панели не «терять» сессию при пересоздании
  /// виджета во время отсутствия интернета.
  final bool initialLiveRunning;
  final int? initialLiveSessionId;
  final int startRequestSignal;
  final int pauseRequestSignal;
  final int stopRequestSignal;
  final int exitWithoutSaveRequestSignal;
  /// Увеличивается родителем после offline recovery/finalize, чтобы уже
  /// открытая Live-панель перечитала серверную траекторию и сводку.
  final int externalRefreshSignal;

  /// V201: desktop/tablet Live открывается сразу как отдельный полноэкранный
  /// workspace. Родительский Tracker скрывает внешнюю rail-навигацию, а
  /// крестик сверху и возврат внизу левого меню ведут к выбору сессии,
  /// не пересоздавая BLE/GPS/Polar-сессию.
  final bool workspaceFullscreen;
  final ValueChanged<bool>? onWorkspaceFullscreenChanged;

  @override
  State<TrackerLivePanel> createState() => _TrackerLivePanelState();
}

