  @override
  bool get wantKeepAlive => true;

  bool get _isTeamMultiLive =>
      widget.onStartTeamLive != null && widget.onStopTeamLive != null;

  bool get _teamTrackerReady =>
      widget.teamTrackerCount > 0 || widget.ble.commandChannelReady;

  String _monitorPersistenceKeyFor(int clubId, int teamId) => '$clubId:$teamId';

  String get _monitorPersistenceKey =>
      _monitorPersistenceKeyFor(widget.clubId, widget.teamId);

  void _restorePersistedMonitorSelection() {
    final saved = _persistedMonitorPlayerIds[_monitorPersistenceKey];
    _monitorPlayerIds
      ..clear()
      ..addAll(saved ?? const <int>{});
    _monitorManualSelectionTouched =
        _persistedMonitorManualTouched[_monitorPersistenceKey] ?? false;
  }

  void _persistMonitorSelection({int? clubId, int? teamId}) {
    final key = _monitorPersistenceKeyFor(
      clubId ?? widget.clubId,
      teamId ?? widget.teamId,
    );
    _persistedMonitorPlayerIds[key] = Set<int>.from(_monitorPlayerIds);
    _persistedMonitorManualTouched[key] = _monitorManualSelectionTouched;
  }

  void _pulseRuntimeMotion() {
    if (!mounted) return;
    _runtimeMotionController.forward(from: 0);
  }

  bool get _runtimeMotionEnabled =>
      _running &&
      !_liveTacticalReviewMode &&
      _liveReviewTeamTimeMs == null &&
      _liveReviewTimeMs == null;

  @override
  void initState() {
    super.initState();
    _runtimeMotionController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 820),
    );
    _running = widget.initialLiveRunning;
    _myLiveSessionId = widget.initialLiveSessionId;
    if (_running) {
      _startedAt ??= DateTime.now();
      _lastProblem =
          'Командный Live восстановлен локально · интернет для BLE-просмотра не требуется';
    }
    _liveTacticalReviewController = TgAnalyticsOverlayController(
      sessionKey: _liveTacticalReviewSessionKey(),
      onMutation: _queueLiveTacticalReviewSave,
    );
    if ((_myLiveSessionId ?? 0) > 0) {
      unawaited(
        _loadLiveTacticalReviewForKey(_liveTacticalReviewSessionKey()),
      );
    }
    _restorePersistedMonitorSelection();
    WidgetsBinding.instance.addObserver(this);
    _captureHeartRateSamples();
    _listenBle();
    _startPolling();
    if (widget.startRequestSignal > 0) {
      _handledStartRequestSignal = widget.startRequestSignal;
      Future.microtask(_handleExternalStartLiveRequest);
    }
  }

  @override
  void dispose() {
    _runtimeMotionController.dispose();
    _persistMonitorSelection();
    _liveTacticalReviewSaveTimer?.cancel();
    unawaited(_flushLiveTacticalReviewSave());
    _liveTacticalReviewController.dispose();
    final liveId = _myLiveSessionId;
    if (_isTeamMultiLive) {
      // Командный Live принадлежит координатору экрана, а не жизненному циклу панели.
      // Перестроение/смена игрока/размера окна не имеет права сбрасывать состояние команды.
      if (_running) widget.onLiveRunningChanged?.call(true);
      if (liveId != null) widget.onLiveSessionIdChanged?.call(liveId);
    } else if (_running && liveId != null) {
      // v81: dispose больше не останавливает Live автоматически.
      // Виджет может пересоздаться из-за смены вкладки/размера окна/ключа, и раньше это
      // закрывало тренировку примерно через 30 минут или при перестроении экрана.
      // Закрытие/сохранение теперь делается только явной кнопкой Стоп или диалогом выхода.
      unawaited(_api
          .heartbeatLiveSession(
              liveSessionId: liveId, statusText: 'widget_dispose_keep_alive')
          .catchError((_) => <String, dynamic>{}));
      unawaited(_saveMetricSnapshot(manual: false));
      widget.onLiveRunningChanged?.call(true);
      widget.onLiveSessionIdChanged?.call(liveId);
    } else {
      widget.onLiveRunningChanged?.call(false);
      widget.onLiveSessionIdChanged?.call(null);
    }
    WidgetsBinding.instance.removeObserver(this);
    _pollTimer?.cancel();
    _phoneTimer?.cancel();
    _trackerTimer?.cancel();
    _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
    _bleSub?.cancel();
    _bleLogSub?.cancel();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    final liveId = _myLiveSessionId;
    if (!_running || liveId == null) return;

    if (state == AppLifecycleState.resumed) {
      unawaited(ActionTrackerBleService.setTrackerKeepScreenOn(true));
      _log('APP resumed: защита экрана Live включена повторно');
      return;
    }

    // v80: страховка от случайного выхода/сворачивания приложения.
    // На pause/inactive не останавливаем Live, чтобы запись могла продолжиться,
    // но отправляем heartbeat и локальный snapshot метрик на сервер.
    if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden) {
      unawaited(_api
          .heartbeatLiveSession(
              liveSessionId: liveId, statusText: 'app_${state.name}_autosave')
          .catchError((_) {}));
      unawaited(_saveMetricSnapshot(manual: false));
      _log(
          'APP ${state.name}: Live #$liveId не остановлен, отправлен heartbeat/snapshot');
      return;
    }

    // Если приложение реально уничтожают, успеваем best-effort сохранить финальную сессию.
    if (state == AppLifecycleState.detached) {
      unawaited(_autoSaveLiveAfterParentDecision());
    }
  }

  @override
  void didUpdateWidget(covariant TrackerLivePanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    _captureHeartRateSamples();

    // Team Live живёт в координаторе экрана. Если сама панель пересоздалась
    // при смене вкладки/размера окна или сеть в этот момент недоступна,
    // восстанавливаем running/session id из локального источника, не из HTTP.
    if (_isTeamMultiLive && widget.initialLiveRunning && !_running) {
      _running = true;
      _startedAt ??= DateTime.now();
      _lastProblem =
          'Командный Live продолжается локально · ожидание сервера';
    }
    if (_isTeamMultiLive &&
        widget.initialLiveSessionId != null &&
        _myLiveSessionId == null) {
      _myLiveSessionId = widget.initialLiveSessionId;
      unawaited(_syncLiveTacticalReviewSession());
    }

    if (oldWidget.externalRefreshSignal != widget.externalRefreshSignal) {
      Future.microtask(() => _loadLiveState(restoreRunning: false));
    }

    if (oldWidget.startRequestSignal != widget.startRequestSignal &&
        widget.startRequestSignal != _handledStartRequestSignal) {
      _handledStartRequestSignal = widget.startRequestSignal;
      Future.microtask(_handleExternalStartLiveRequest);
    }

    if (oldWidget.pauseRequestSignal != widget.pauseRequestSignal &&
        widget.pauseRequestSignal != _handledPauseRequestSignal) {
      _handledPauseRequestSignal = widget.pauseRequestSignal;
      Future.microtask(_pauseLiveCollection);
    }
    if (oldWidget.stopRequestSignal != widget.stopRequestSignal &&
        widget.stopRequestSignal != _handledStopRequestSignal) {
      _handledStopRequestSignal = widget.stopRequestSignal;
      Future.microtask(_autoSaveLiveAfterParentDecision);
    }
    if (oldWidget.exitWithoutSaveRequestSignal !=
            widget.exitWithoutSaveRequestSignal &&
        widget.exitWithoutSaveRequestSignal !=
            _handledExitWithoutSaveRequestSignal) {
      _handledExitWithoutSaveRequestSignal =
          widget.exitWithoutSaveRequestSignal;
      Future.microtask(_autoSaveLiveAfterParentDecision);
    }

    if (oldWidget.teamId != widget.teamId ||
        oldWidget.clubId != widget.clubId) {
      _persistMonitorSelection(clubId: oldWidget.clubId, teamId: oldWidget.teamId);
      _restorePersistedMonitorSelection();
      _phoneTimer?.cancel();
      _trackerTimer?.cancel();
      _heartbeatTimer?.cancel();
      _liveMapReplayTimer?.cancel();
      _liveTacticalReviewSaveTimer?.cancel();
      unawaited(_flushLiveTacticalReviewSave());
      _setLiveRunning(false);
      _paused = false;

      setState(() {
        _sessions = <TrackerLiveSessionModel>[];
        _tracks.clear();
        _teamLoadHistory.clear();
        _myLiveSessionId = null;
        _liveTacticalReviewMode = false;
        _liveTacticalFreezeTracks = <_RuntimeTrack>[];
        _liveGpsFallbackBounds = null;
        _lastProblem = 'Команда изменена: ${widget.teamName}';
        _lastRx = 'нет пакетов';
        _lastTx = 'нет команд';
        _lastGps = 'нет GPS';
        _lastSave = 'нет сохранения';
        _lastStop = 'нет остановки';
        _lastPayload = 'нет payload';
        _lastServer = 'нет ответа';
        _lastLiveState = 'не загружено';
        _lastLocalMetrics = 'нет локальных метрик';
        _lastZeroReason = 'ожидаем GPS';
      });

      _liveTacticalReviewController.switchSession(
        _liveTacticalReviewSessionKey(),
      );
      _liveTacticalReviewServerLoaded = false;

      _loadLiveState();
      _log('Команда Live изменена: ${widget.teamName} (${widget.teamId})');
      return;
    }

    if (oldWidget.selectedField?.id != widget.selectedField?.id) {
      _liveGpsFallbackBounds = null;
      _loadLiveState();
      _log('Изменено поле: ${widget.selectedField?.title ?? 'нет поля'}');
    }

    if (oldWidget.selectedPlayer?.id != widget.selectedPlayer?.id) {
      _log('Изменён игрок Live: ${widget.selectedPlayer?.name ?? 'не выбран'}');
      if (_isTeamMultiLive) {
        // В командном Live выбор карточки меняет только фокус интерфейса.
        // Сессии и BLE-каналы всех игроков продолжают работать.
        _lastProblem = _running
            ? 'Командный Live продолжается. Выбран ${widget.selectedPlayer?.name ?? 'игрок'} для просмотра.'
            : 'Выбран ${widget.selectedPlayer?.name ?? 'игрок'}.';
        // Не выключаем режим «Команда»: в нём смена фокуса нужна только для
        // правой панели нагрузки, а уже отмеченные GPS-точки остаются на поле.
      } else if (_running) {
        _lastProblem =
            'Live уже запущен. Чтобы перепривязать трекер к другому игроку, сначала остановите и сохраните текущую сессию.';
        setState(() {});
      } else {
        setState(() {
          _tracks.clear();
          _sessions = <TrackerLiveSessionModel>[];
          _teamLoadHistory.clear();
          _myLiveSessionId = null;
          _blockServerAutoRestoreAfterPlayerPick = true;
          _lastLocalMetrics = 'игрок изменён — локальный трек очищен';
          _lastProblem =
              'Выбран ${widget.selectedPlayer?.name ?? 'новый игрок'}. Live не запущен — нажмите Старт вручную.';
        });
        Future.microtask(() => _loadLiveState(restoreRunning: false));
      }
    }

    final teamConnectionsChanged = oldWidget.connectedTeamPlayerIds.length !=
            widget.connectedTeamPlayerIds.length ||
        oldWidget.connectedTeamPlayerIds
            .any((id) => !widget.connectedTeamPlayerIds.contains(id));
    if (!_monitorManualSelectionTouched && teamConnectionsChanged) {
      final connected = _livePlayerOptions()
          .where((player) =>
              widget.connectedTeamPlayerIds.contains(player.id) ||
              player.identityIds.any(widget.connectedTeamPlayerIds.contains))
          .map((player) => player.id)
          .take(_maxMonitorPlayers)
          .toList(growable: false);
      if (connected.isNotEmpty) {
        setState(() {
          _monitorPlayerIds
            ..clear()
            ..addAll(connected);
        });
        _persistMonitorSelection();
      }
    }
  }

  Future<void> _handleExternalStartLiveRequest() async {
    _blockServerAutoRestoreAfterPlayerPick = false;
    _log(
        'LIVE LINK: внешний запуск Live из аналитики / signal=${widget.startRequestSignal}');
    if (_paused) {
      _resumeLiveCollection();
      return;
    }
    if (_running || _starting) {
      _lastProblem = 'Live уже активен: аналитика подключена к текущей сессии.';
      if (mounted) setState(() {});
      return;
    }
    await _startLive();
  }

  void _setLiveRunning(bool value) {
    if (_running == value) return;
    _running = value;
    unawaited(ActionTrackerBleService.setTrackerKeepScreenOn(value));
    if (value) {
      _startedAt ??= DateTime.now();
    } else {
      _startedAt = null;
      _paused = false;
    }
    widget.onLiveRunningChanged?.call(value);
  }

  String _liveTacticalReviewSessionKey() {
    var startMs = _startedAt?.millisecondsSinceEpoch ?? 0;
    for (final track in _tracks.values) {
      if (track.points.isEmpty) continue;
      final value = track.points.first.timeMs;
      if (value > 0 && (startMs <= 0 || value < startMs)) startMs = value;
    }
    if (startMs > 0) {
      // Командный Live создаёт отдельный live_session_id каждому игроку.
      // Пятиминутное окно старта даёт всей тренировке один общий ключ, поэтому
      // рисунок откроется в аналитике независимо от выбранного игрока.
      return 'tracker:${widget.teamId}:live-window:${startMs ~/ 300000}';
    }
    final liveId = _myLiveSessionId ?? 0;
    return 'tracker:${widget.teamId}:live:$liveId';
  }

  int get _persistentLiveTacticalSessionId {
    final id = _myLiveSessionId ?? 0;
    // 700M+ is the local/offline placeholder range used by the team
    // coordinator. It must never be written as a server foreign key.
    return id > 0 && id < 700000000 ? id : 0;
  }

  int _liveTacticalReviewStartMs() {
    var startMs = _startedAt?.millisecondsSinceEpoch ?? 0;
    final source = _liveTacticalFreezeTracks.isNotEmpty
        ? _liveTacticalFreezeTracks
        : _rawSidePanelTracks();
    for (final track in source) {
      if (track.points.isEmpty) continue;
      final value = track.points.first.timeMs;
      if (value > 0 && (startMs <= 0 || value < startMs)) startMs = value;
    }
    return startMs;
  }

  int _liveTacticalReviewEndMs() {
    var endMs = _liveReviewTeamTimeMs ?? 0;
    final source = _liveTacticalFreezeTracks.isNotEmpty
        ? _liveTacticalFreezeTracks
        : _rawSidePanelTracks();
    for (final track in source) {
      if (track.points.isEmpty) continue;
      endMs = math.max(endMs, track.points.last.timeMs).toInt();
    }
    return endMs;
  }

  void _queueLiveTacticalReviewSave(
    String scopeKey,
    List<Map<String, dynamic>> annotations,
  ) {
    final revision = (_liveTacticalReviewRevisionByKey[scopeKey] ?? 0) + 1;
    _liveTacticalReviewRevisionByKey[scopeKey] = revision;
    _liveTacticalReviewDirtyKeys.add(scopeKey);
    _liveTacticalReviewPendingSave = _LiveTacticalReviewPendingSave(
      scopeKey: scopeKey,
      clubId: widget.clubId,
      teamId: widget.teamId,
      sessionId: _persistentLiveTacticalSessionId,
      createdBy: widget.userId,
      startMs: _liveTacticalReviewStartMs(),
      endMs: _liveTacticalReviewEndMs(),
      title: '${widget.teamName} · Live-разбор',
      annotations: annotations
          .map((item) => Map<String, dynamic>.from(item))
          .toList(growable: false),
      revision: revision,
    );
    _liveTacticalReviewSaveTimer?.cancel();
    _liveTacticalReviewSaveTimer = Timer(
      const Duration(milliseconds: 850),
      () => unawaited(_flushLiveTacticalReviewSave()),
    );
  }

  Future<void> _flushLiveTacticalReviewSave() async {
    _liveTacticalReviewSaveTimer?.cancel();
    _liveTacticalReviewSaveTimer = null;
    final pending = _liveTacticalReviewPendingSave;
    if (pending == null) return;
    _liveTacticalReviewPendingSave = null;

    // В offline Live рисунки остаются в session cache контроллера. После
    // появления реального server live id следующая мутация сохранит документ.
    if (pending.sessionId <= 0) return;

    _liveTacticalReviewSaving = true;
    try {
      await _liveTacticalReviewApi.save(
        scopeKey: pending.scopeKey,
        clubId: pending.clubId,
        teamId: pending.teamId,
        sessionId: pending.sessionId,
        createdBy: pending.createdBy,
        startMs: pending.startMs,
        endMs: pending.endMs,
        title: pending.title,
        annotations: pending.annotations,
      );
      if (_liveTacticalReviewRevisionByKey[pending.scopeKey] ==
          pending.revision) {
        _liveTacticalReviewDirtyKeys.remove(pending.scopeKey);
      }
    } catch (error) {
      _log('LIVE TACTICAL REVIEW save fallback: $error');
    } finally {
      _liveTacticalReviewSaving = false;
    }
  }

  Future<void> _loadLiveTacticalReviewForKey(String scopeKey) async {
    if ((_myLiveSessionId ?? 0) <= 0) return;
    final token = ++_liveTacticalReviewLoadToken;
    try {
      final document =
          await _liveTacticalReviewApi.load(scopeKey: scopeKey);
      if (!mounted || token != _liveTacticalReviewLoadToken) return;
      if (_liveTacticalReviewController.sessionKey != scopeKey) return;
      if (_liveTacticalReviewDirtyKeys.contains(scopeKey)) return;
      if (document != null) {
        _liveTacticalReviewController.replaceFromJson(document.annotations);
      }
      _liveTacticalReviewServerLoaded = true;
    } catch (error) {
      _log('LIVE TACTICAL REVIEW load fallback: $error');
    }
  }

  Future<void> _syncLiveTacticalReviewSession() async {
    final key = _liveTacticalReviewSessionKey();
    if (_liveTacticalReviewController.sessionKey == key) return;
    await _flushLiveTacticalReviewSave();
    if (!mounted) return;
    _liveTacticalReviewController.switchSession(key);
    _liveTacticalReviewServerLoaded = false;
    await _loadLiveTacticalReviewForKey(key);
  }

  _RuntimeTrack _freezeLiveTrack(_RuntimeTrack source) {
    final snapshot = _RuntimeTrack(
      key: source.key,
      playerName: source.playerName,
      deviceName: source.deviceName,
      avatar: source.avatar,
    );
    snapshot.points.addAll(source.points);
    snapshot.speedKmh = source.speedKmh;
    snapshot.rawSpeedKmh = source.rawSpeedKmh;
    snapshot.totalDistanceM = source.totalDistanceM;
    snapshot.maxSpeedKmh = source.maxSpeedKmh;
    snapshot.lastDeltaM = source.lastDeltaM;
    snapshot.sprintCount = source.sprintCount;
    return snapshot;
  }

  void _toggleLiveTacticalReview() {
    if (_liveTacticalReviewMode) {
      setState(() {
        _liveTacticalReviewMode = false;
        _liveTacticalFreezeTracks = <_RuntimeTrack>[];
        _liveReviewTeamTimeMs = null;
        _selectedLiveEventId = null;
      });
      unawaited(_flushLiveTacticalReviewSave());
      return;
    }

    _stopLiveMapReplay();
    final liveTracks = _sidePanelTracks();
    final frozen = liveTracks
        .where((track) => track.points.isNotEmpty)
        .map(_freezeLiveTrack)
        .toList(growable: false);
    var freezeTimeMs = _liveReviewTeamTimeMs ?? 0;
    for (final track in frozen) {
      freezeTimeMs = math.max(freezeTimeMs, track.points.last.timeMs).toInt();
    }
    if (freezeTimeMs <= 0) {
      freezeTimeMs = DateTime.now().millisecondsSinceEpoch;
    }
    setState(() {
      _liveTacticalReviewMode = true;
      _liveTacticalFreezeTracks = frozen;
      _liveReviewTeamTimeMs = freezeTimeMs;
      _selectedLiveEventId = null;
      _liveMapProReplayPlaying = false;
      _liveTacticalReviewController.setTool(TgAnalyticsTool.select);
    });
    unawaited(_syncLiveTacticalReviewSession());
  }


  // Never reuse telemetry from a previous Live session in the Live UI.
  // Device bindings, BLE readiness and monitor selections stay intact; only
  // runtime session data is reset after a new Live session is created.
  void _resetRuntimeTelemetryForNewLive() {
    _runtimeMotionCache.clear();
    _tracks.clear();
    _sessions = <TrackerLiveSessionModel>[];
    _liveEvents.clear();
    _liveEventSummaryByPlayer.clear();
    _lastLiveEventPointId = 0;
    _selectedLiveEventId = null;
    _liveReviewPlayerId = null;
    _liveReviewTimeMs = null;
    _liveReviewTeamTimeMs = null;
    _liveTacticalReviewMode = false;
    _liveTacticalFreezeTracks = <_RuntimeTrack>[];
    _liveGpsFallbackBounds = null;
    _teamLoadHistory.clear();
    _periods.clear();
    _startedAt = null;
    _lastGpsAt = null;
    _lastGps = 'нет GPS';
    _lastSave = 'нет сохранения';
    _lastPayload = 'нет payload';
    _lastLocalMetrics = 'новая Live-сессия — ожидаем данные';
    _lastZeroReason = 'ожидаем первый пакет текущей Live-сессии';
  }

  bool get _liveTelemetryActive => _running;

  void _listenBle() {
    _bleLogSub?.cancel();
    _bleLogSub = widget.ble.logStream.listen((line) {
      _log('BLE $line');
      if (mounted) setState(() {});
    });

    _bleSub = widget.ble.dataStream.listen((event) async {
      final typeHex = '0x${event.packetType.toRadixString(16).toUpperCase()}';
      _lastRx = '${event.rawHex} · $typeHex';

      final rxNow = DateTime.now();
      final shouldRemoteRx = _running &&
          (_lastRemoteLiveRxLogAt == null ||
              rxNow.difference(_lastRemoteLiveRxLogAt!).inSeconds >= 5);
      if (shouldRemoteRx) {
        _lastRemoteLiveRxLogAt = rxNow;
        unawaited(_serverLog(
          'Live RX: $_lastRx · running=$_running paused=$_paused mode=${_mode.name}',
          source: 'live_rx',
          rawHex: event.rawHex,
        ));
      }

      if (_mode == TrackerLiveSourceMode.trackerExperimental) {
        _log('RX $_lastRx');
      }

      if (event.records.isNotEmpty) {
        _offlineRecorderStatus = _formatRecorderStatus(event.records);
        _log('Записи на трекере: $_offlineRecorderStatus');
      }

      if (event.transferFinished || event.gpsChunk?.finished == true) {
        _offlineRecorderStatus = 'загрузка офлайн-записи завершена';
        _log(_offlineRecorderStatus);
      }

      if (!_running || _mode != TrackerLiveSourceMode.trackerExperimental) {
        if (mounted) setState(() {});
        return;
      }

      if (event.battery != null) {
        _log(
          'Батарея/GPS: ${event.battery!.voltage.toStringAsFixed(2)} В · '
          'GPS ${event.battery!.gpsReady ? 'готов' : 'не готов'} · это не координата',
        );
      }

      final chunk = event.gpsChunk;
      if (chunk == null || chunk.points.isEmpty) {
        final zeroGps = event.rawHex.contains('3B 00 00 00 00 00 00 00 00') ||
            event.rawHex.contains('44 00 00 00 00 00 00 00');
        _lastProblem = zeroGps
            ? 'Трекер отвечает нулевой GPS-точкой 0,0. Это не ошибка UI: нет актуальной координаты. Выйдите на улицу, дождитесь спутников или включите запись на трекере.'
            : 'Пакет $typeHex получен, но координат в нём нет';
        _lastGps =
            zeroGps ? '0.000000, 0.000000 · $typeHex · нет фиксации' : _lastGps;
        await _serverLog(
          _lastProblem,
          level: zeroGps ? 'warning' : 'info',
          source: zeroGps ? 'live_rx_zero_gps' : 'live_rx_no_points',
          rawHex: event.rawHex,
        );
        if (mounted) setState(() {});
        return;
      }

      final point = chunk.points.last;
      final nowMs = DateTime.now().millisecondsSinceEpoch;

      _lastGpsAt = DateTime.now();
      _lastGps =
          '${point.latitude.toStringAsFixed(6)}, ${point.longitude.toStringAsFixed(6)} · $typeHex';
      _gpsMissesForCandidate = 0;
      _lastGpsProbeAt = null;
      _lastGpsCandidateWithFix = _candidateCommandIndex;

      _log(
          'GPS трекера: $_lastGps · working_command_index=${_candidateCommandIndex + 1}');

      await _handleGpsPoint(
        latitude: point.latitude,
        longitude: point.longitude,
        timeMs: nowMs,
        packetType: typeHex,
        rawHex: event.rawHex,
      );
    });
  }

  void _startPolling() {
    _log('Live открыт. Команда Live GPS: 3A → ответ 3B/44.');
    _loadLiveState();
    _pollTimer?.cancel();
    _pollTimer = Timer.periodic(
      const Duration(seconds: 3),
      (_) => _loadLiveState(
          restoreRunning: !_blockServerAutoRestoreAfterPlayerPick),
    );
  }

  Future<void> _loadLiveState({bool restoreRunning = true}) async {
// Не запускаем новый HTTP-запрос, пока предыдущий ещё выполняется.
// Раньше polling каждые 3 секунды создавал несколько параллельных запросов,
// а зависший PHP отвечал TimeoutException спустя 20 секунд.
    final localSessions = _localTeamSessions();
    if (_liveStateRequestInFlight) {
      _applyLocalTeamSessions(localSessions, restoreRunning: restoreRunning);
      return;
    }
    _applyLocalTeamSessions(localSessions, restoreRunning: restoreRunning);
    _liveStateRequestInFlight = true;
    try {
      final loaded = await _api.loadTeamLiveState(
        teamId: widget.teamId,
        fieldId: _activity.requiresField ? widget.selectedField?.id : null,
      );
      final data = _isTeamMultiLive
          ? loaded
              .where((session) => !session.belongsToPersonalOrPhoneLive)
              .toList(growable: false)
          : loaded;
      if (!mounted) return;

      final activeCount = data
          .where((s) =>
              s.status == 'active' ||
              s.status == 'online' ||
              s.status == 'live')
          .length;
      _lastLiveState = data.isEmpty
          ? 'sessions=0 active=0 · сервер ничего не вернул'
          : 'sessions=${data.length} active=$activeCount · ${_debugSessionLine(data.first)}';

      final nextSessions = _mergeLiveSessionsKeepRunning(
        <TrackerLiveSessionModel>[...data, ...localSessions],
      );
      if (restoreRunning && !_blockServerAutoRestoreAfterPlayerPick) {
        _restoreRunningLiveIfNeeded(nextSessions);
      }
      _pulseRuntimeMotion();
      setState(() {
        _sessions = nextSessions;
        _recordTeamLoadSnapshot();
      });
      _liveStateTimeouts = 0;
      unawaited(_loadLiveEvents());
      await _loadLivePeriods();
    } on TimeoutException catch (e) {
      _liveStateTimeouts += 1;
      _lastLiveState = 'таймаут сервера ($_liveStateTimeouts)';
      // Не затираем рабочий Live и не показываем это как фатальную ошибку.
      // Следующий polling сам попробует снова. BLE/локальные метрики не зависят
      // от этого HTTP polling.
      if (_running || widget.initialLiveRunning) {
        _lastProblem =
            'Интернет недоступен · Live и подключённые GPS продолжаются локально';
      }
      if (_liveStateTimeouts == 1 || _liveStateTimeouts % 5 == 0) {
        _log('Live API временно не ответил: $e');
      }
      _applyLocalTeamSessions(_localTeamSessions(),
          restoreRunning: restoreRunning);
      if (mounted) setState(() {});
    } catch (e) {
      _lastLiveState = 'ОШИБКА load_state: $e';
      if (_running || widget.initialLiveRunning) {
        _lastProblem =
            'Интернет недоступен · Live и подключённые GPS продолжаются локально';
        _log('Live API недоступен, локальный Live сохранён: $e');
      } else {
        _lastProblem = 'Ошибка загрузки Live: $e';
        _log(_lastProblem);
      }
      _applyLocalTeamSessions(_localTeamSessions(),
          restoreRunning: restoreRunning);
      if (mounted) setState(() {});
    } finally {
      _liveStateRequestInFlight = false;
    }
  }

  List<TrackerLiveSessionModel> _localTeamSessions() {
    if (!_isTeamMultiLive) return const <TrackerLiveSessionModel>[];
    try {
      return widget.localTeamSessionsProvider?.call() ??
          const <TrackerLiveSessionModel>[];
    } catch (_) {
      return const <TrackerLiveSessionModel>[];
    }
  }

  void _applyLocalTeamSessions(
    List<TrackerLiveSessionModel> local, {
    required bool restoreRunning,
  }) {
    if (!mounted || local.isEmpty) return;
    if (_running && _isTeamMultiLive) {
      TrackerLiveSessionModel preferred = local.first;
      final selectedId = widget.selectedPlayer?.id;
      if (selectedId != null) {
        for (final session in local) {
          if (session.playerId == selectedId ||
              _resolvedPlayerIdForSession(session) == selectedId) {
            preferred = session;
            break;
          }
        }
      }
      if (preferred.id > 0 && preferred.id != _myLiveSessionId) {
        _myLiveSessionId = preferred.id;
        widget.onLiveSessionIdChanged?.call(preferred.id);
        unawaited(_syncLiveTacticalReviewSession());
      }
    }
    final next = _mergeLiveSessionsKeepRunning(local);
    if (restoreRunning && !_blockServerAutoRestoreAfterPlayerPick) {
      _restoreRunningLiveIfNeeded(next);
    }
    _pulseRuntimeMotion();
    setState(() {
      _sessions = next;
      _recordTeamLoadSnapshot();
    });
  }

  Future<void> _loadLiveEvents() async {
    if (_liveEventsRequestInFlight || widget.teamId <= 0) return;
    _liveEventsRequestInFlight = true;
    try {
      final page = await _api.loadTeamLiveEvents(
        teamId: widget.teamId,
        afterPointId: _lastLiveEventPointId,
        limit: _lastLiveEventPointId <= 0 ? 900 : 500,
      );
      if (!mounted) return;

      final byId = <String, TrackerLiveEventModel>{
        for (final item in _liveEvents) item.id: item,
      };
      for (final item in page.events) {
        byId[item.id] = item;
      }
      final merged = byId.values.toList(growable: false)
        ..sort((a, b) => b.timeMs.compareTo(a.timeMs));

      setState(() {
        _liveEvents
          ..clear()
          ..addAll(merged.take(320));
        _liveEventSummaryByPlayer
          ..clear()
          ..addAll(page.playerSummary);
        _lastLiveEventPointId = math.max(
          _lastLiveEventPointId,
          page.lastPointId,
        );
      });
    } catch (e) {
      // Моменты — дополнительный Live-слой. Ошибка этого endpoint не должна
      // останавливать GPS, карточки или основную командную сессию.
      _log('Live moments: $e');
    } finally {
      _liveEventsRequestInFlight = false;
    }
  }

  List<TrackerLiveEventModel> _monitorLiveEvents() {
    final ids = _monitorPlayersForGrid().map((p) => p.id).toSet();
    final events = _liveEvents
        .where((event) => event.playerId == null || ids.contains(event.playerId))
        .toList(growable: false)
      ..sort((a, b) => b.timeMs.compareTo(a.timeMs));
    return events;
  }

  List<TrackerLiveEventModel> _liveEventsForPlayer(int playerId) => _liveEvents
      .where((event) => event.playerId == playerId)
      .toList(growable: false);

  int _redLiveEventCountForPlayer(int playerId) => _liveEventsForPlayer(playerId)
      .where((event) => event.isRed)
      .length;

  void _focusLiveEvent(TrackerLiveEventModel event) {
    TrackerPlayerOption? player;
    final playerId = event.playerId;
    if (playerId != null && playerId > 0) {
      for (final candidate in _monitorCandidatePlayers()) {
        if (candidate.id == playerId || candidate.identityIds.contains(playerId)) {
          player = candidate;
          break;
        }
      }
    }

    final openedInsideCards = _monitorPlayersExpanded;
    setState(() {
      _selectedLiveEventId = event.id;
      _liveReviewTeamTimeMs = null;
      _showLoadHotPoints = true;
      _teamFieldPanelExpanded = true;
      _liveSidePanelMode = 'map';
      _showTeamOnFocusedField = false;
      if (player != null) {
        _monitorMapPlayerIds
          ..clear()
          ..add(player!.id);

        // Выбранный момент становится точкой просмотра на Live-таймлайне.
        // Командный Live при этом НЕ останавливается и продолжает принимать
        // новые GPS/Polar данные в фоне.
        _liveReviewPlayerId = player!.id;
        _liveReviewTimeMs = event.timeMs > 0 ? event.timeMs : null;

        // В полноэкранном окне «Все карточки» момент открывает подробный экран
        // этого игрока. Назад возвращает в карточки, «В LIVE» возвращает поле
        // к самой свежей точке без остановки сессии.
        if (_monitorPlayersExpanded) {
          _expandedMonitorDetailPlayerId = player!.id;
        }
      }
    });

    // В полноэкранных карточках это чисто локальная навигация: не заставляем
    // родительский экран пересобирать BLE-координатор из-за клика по событию.
    if (player != null && !openedInsideCards) {
      widget.onSelectPlayer?.call(player!);
    }
  }

  TrackerLiveEventModel? _selectedLiveEvent() {
    final id = _selectedLiveEventId;
    if (id == null || id.isEmpty) return null;
    for (final event in _liveEvents) {
      if (event.id == id) return event;
    }
    return null;
  }

  bool _isReviewingPlayer(int playerId) =>
      _liveReviewPlayerId == playerId && (_liveReviewTimeMs ?? 0) > 0;

  void _returnPlayerToLive(TrackerPlayerOption player) {
    if (!_isReviewingPlayer(player.id) && _selectedLiveEventId == null) return;
    setState(() {
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _liveReviewTeamTimeMs = null;
      _selectedLiveEventId = null;
      _showLoadHotPoints = true;
    });
    _pulseRuntimeMotion();
  }

  String _liveClockLabel(int timeMs) {
    if (timeMs <= 0) return '--:--:--';
    final value = _trackerMoscowFromEpochMs(timeMs);
    String two(int v) => v.toString().padLeft(2, '0');
    return '${two(value.hour)}:${two(value.minute)}:${two(value.second)}';
  }

  _RuntimeTrack? _reviewTrackSnapshot(
    TrackerPlayerOption player,
    _RuntimeTrack? liveTrack,
  ) {
    if (!_isReviewingPlayer(player.id)) return liveTrack;
    final cutoff = _liveReviewTimeMs ?? 0;
    if (cutoff <= 0) return liveTrack;

    final selectedEvent = _selectedLiveEvent();
    final snapshot = _RuntimeTrack(
      key: '${liveTrack?.key ?? 'REVIEW'}-REVIEW-${player.id}-$cutoff',
      playerName: player.name,
      deviceName: liveTrack?.deviceName ?? 'Live history',
      avatar: player.avatar ?? liveTrack?.avatar,
    );

    if (liveTrack != null) {
      for (final point in liveTrack.points) {
        if (point.timeMs <= cutoff) snapshot.points.add(point);
      }
    }

    // У удалённого игрока локально может быть только последняя server-live
    // координата. Координата события приходит из PHP, поэтому даже в таком
    // случае переносим аватар на реальное место выбранного момента.
    if (selectedEvent != null &&
        selectedEvent.playerId == player.id &&
        selectedEvent.latitude != null &&
        selectedEvent.longitude != null) {
      final eventPoint = _RuntimePoint(
        lat: selectedEvent.latitude!,
        lon: selectedEvent.longitude!,
        timeMs: selectedEvent.timeMs > 0 ? selectedEvent.timeMs : cutoff,
        speedKmh: _safeLiveSpeed(selectedEvent.speedKmh),
        rawSpeedKmh: _safeLiveSpeed(selectedEvent.speedKmh),
        distanceDeltaM: 0,
        packetType: 'live-event-review',
      );
      if (snapshot.points.isEmpty ||
          snapshot.points.last.timeMs != eventPoint.timeMs) {
        snapshot.points.add(eventPoint);
      }
    }

    if (snapshot.points.isEmpty) return liveTrack;

    var distance = 0.0;
    var maxSpeed = 0.0;
    for (final point in snapshot.points) {
      distance += math.max(0.0, point.distanceDeltaM);
      maxSpeed = math.max(maxSpeed, _safeLiveSpeed(point.speedKmh));
    }
    snapshot.totalDistanceM = distance;
    snapshot.speedKmh = _safeLiveSpeed(snapshot.points.last.speedKmh);
    snapshot.rawSpeedKmh = snapshot.speedKmh;
    snapshot.maxSpeedKmh = maxSpeed;
    snapshot.lastDeltaM = snapshot.points.last.distanceDeltaM;
    return snapshot;
  }

  _RuntimeTrack? _teamReviewTrackSnapshot(
    _RuntimeTrack liveTrack,
    int cutoff,
  ) {
    if (cutoff <= 0) return liveTrack;
    final snapshot = _RuntimeTrack(
      key: '${liveTrack.key}-TEAM-REVIEW-$cutoff',
      playerName: liveTrack.playerName,
      deviceName: liveTrack.deviceName,
      avatar: liveTrack.avatar,
    );
    for (final point in liveTrack.points) {
      if (point.timeMs <= cutoff) snapshot.points.add(point);
    }

    final selectedEvent = _selectedLiveEvent();
    final player = _phonePlayerForTrack(liveTrack);
    final eventPlayerId = selectedEvent?.playerId;
    final belongsToTrack = selectedEvent != null &&
        player != null &&
        eventPlayerId != null &&
        (player.id == eventPlayerId || player.identityIds.contains(eventPlayerId));
    if (belongsToTrack &&
        selectedEvent!.latitude != null &&
        selectedEvent.longitude != null &&
        selectedEvent.timeMs <= cutoff) {
      final eventPoint = _RuntimePoint(
        lat: selectedEvent.latitude!,
        lon: selectedEvent.longitude!,
        timeMs: selectedEvent.timeMs,
        speedKmh: _safeLiveSpeed(selectedEvent.speedKmh),
        rawSpeedKmh: _safeLiveSpeed(selectedEvent.speedKmh),
        distanceDeltaM: 0,
        packetType: 'team-live-event-review',
      );
      if (snapshot.points.isEmpty ||
          snapshot.points.last.timeMs != eventPoint.timeMs) {
        snapshot.points.add(eventPoint);
      }
    }

    if (snapshot.points.isEmpty) return null;
    var distance = 0.0;
    var maxSpeed = 0.0;
    var sprintCount = 0;
    for (var i = 0; i < snapshot.points.length; i++) {
      final point = snapshot.points[i];
      distance += math.max(0.0, point.distanceDeltaM);
      maxSpeed = math.max(maxSpeed, _safeLiveSpeed(point.speedKmh));
      if (i > 0 &&
          point.speedKmh >= 18.0 &&
          snapshot.points[i - 1].speedKmh < 18.0) {
        sprintCount++;
      }
    }
    snapshot.totalDistanceM = distance;
    snapshot.speedKmh = _safeLiveSpeed(snapshot.points.last.speedKmh);
    snapshot.rawSpeedKmh = snapshot.speedKmh;
    snapshot.maxSpeedKmh = maxSpeed;
    snapshot.lastDeltaM = snapshot.points.last.distanceDeltaM;
    snapshot.sprintCount = sprintCount;
    return snapshot;
  }

  bool get _isReviewingTeamLive => (_liveReviewTeamTimeMs ?? 0) > 0;

  ({int startMs, int endMs}) _teamLiveTimelineRange() {
    final candidates = <int>[];
    for (final track in _rawSidePanelTracks()) {
      if (track.points.isNotEmpty) {
        candidates.add(track.points.first.timeMs);
        candidates.add(track.points.last.timeMs);
      }
    }
    for (final event in _monitorLiveEvents()) {
      if (event.timeMs > 0) candidates.add(event.timeMs);
    }
    if (_startedAt != null) candidates.add(_startedAt!.millisecondsSinceEpoch);
    if (_running) candidates.add(DateTime.now().millisecondsSinceEpoch);
    if (candidates.isEmpty) {
      final now = DateTime.now().millisecondsSinceEpoch;
      return (startMs: now - 60000, endMs: now);
    }
    var startMs = candidates.first;
    var endMs = candidates.first;
    for (final value in candidates.skip(1)) {
      if (value < startMs) startMs = value;
      if (value > endMs) endMs = value;
    }
    if (endMs <= startMs) endMs = startMs + 60000;
    return (startMs: startMs, endMs: endMs);
  }

  void _focusTeamLiveEvent(TrackerLiveEventModel event) {
    if (event.timeMs <= 0) return;
    _stopLiveMapReplay();
    setState(() {
      _liveReviewTeamTimeMs = event.timeMs;
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _selectedLiveEventId = event.id;
      _showLoadHotPoints = true;
      _liveSidePanelMode = 'map';
      _teamFieldPanelExpanded = true;
    });
  }

  void _reviewTeamTimelineAt(double fraction) {
    if (_liveTacticalReviewMode) {
      _toast('Стоп-кадр зафиксирован. Завершите разбор, чтобы менять время.');
      return;
    }
    _stopLiveMapReplay();
    final range = _teamLiveTimelineRange();
    final safe = fraction.clamp(0.0, 1.0).toDouble();
    if (safe >= .985) {
      _returnTeamToLive();
      return;
    }
    final target = range.startMs +
        ((range.endMs - range.startMs) * safe).round();
    setState(() {
      _liveReviewTeamTimeMs = target;
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _selectedLiveEventId = null;
      _showLoadHotPoints = true;
    });
  }

  void _returnTeamToLive() {
    _stopLiveMapReplay();
    if (!_isReviewingTeamLive && _selectedLiveEventId == null) return;
    setState(() {
      _liveReviewTeamTimeMs = null;
      _selectedLiveEventId = null;
    });
    _pulseRuntimeMotion();
  }

  ({int startMs, int endMs}) _playerLiveTimelineRange(
    TrackerPlayerOption player,
  ) {
    final candidates = <int>[];
    final track = _displayTrackForPlayer(player);
    if (track != null && track.points.isNotEmpty) {
      candidates.add(track.points.first.timeMs);
      candidates.add(track.points.last.timeMs);
    }
    for (final event in _liveEventsForPlayer(player.id)) {
      if (event.timeMs > 0) candidates.add(event.timeMs);
    }
    if (_startedAt != null) {
      candidates.add(_startedAt!.millisecondsSinceEpoch);
    }
    if (_running) candidates.add(DateTime.now().millisecondsSinceEpoch);

    if (candidates.isEmpty) {
      final now = DateTime.now().millisecondsSinceEpoch;
      return (startMs: now - 60000, endMs: now);
    }
    var startMs = candidates.first;
    var endMs = candidates.first;
    for (final value in candidates.skip(1)) {
      if (value < startMs) startMs = value;
      if (value > endMs) endMs = value;
    }
    if (endMs <= startMs) endMs = startMs + 60000;
    return (startMs: startMs, endMs: endMs);
  }

  void _reviewPlayerTimelineAt(
    TrackerPlayerOption player,
    double fraction,
  ) {
    final range = _playerLiveTimelineRange(player);
    final safe = fraction.clamp(0.0, 1.0).toDouble();
    if (safe >= .985) {
      _returnPlayerToLive(player);
      return;
    }
    final target = range.startMs +
        ((range.endMs - range.startMs) * safe).round();

    // Для удалённого игрока Flutter обычно знает только его последнюю server-live
    // координату. В таком случае щелчок по истории привязываем к ближайшему
    // сохранённому событию, у которого PHP уже вернул точные координаты.
    final liveTrack = _displayTrackForPlayer(player);
    if (liveTrack == null || liveTrack.points.length <= 1) {
      final candidates = _liveEventsForPlayer(player.id)
          .where((event) => event.timeMs > 0)
          .toList(growable: false);
      if (candidates.isNotEmpty) {
        var nearest = candidates.first;
        var bestDelta = (nearest.timeMs - target).abs();
        for (final event in candidates.skip(1)) {
          final delta = (event.timeMs - target).abs();
          if (delta < bestDelta) {
            nearest = event;
            bestDelta = delta;
          }
        }
        _focusLiveEvent(nearest);
        return;
      }
    }

    setState(() {
      _expandedMonitorDetailPlayerId = player.id;
      _liveReviewPlayerId = player.id;
      _liveReviewTimeMs = target;
      _selectedLiveEventId = null;
      _showLoadHotPoints = true;
    });
  }

  List<TrackerLiveEventModel> _fieldLiveEvents({int? playerId}) {
    final events = playerId == null
        ? _monitorLiveEvents()
        : _liveEventsForPlayer(playerId);
    return events
        .where((event) => event.latitude != null && event.longitude != null)
        .take(120)
        .toList(growable: false);
  }

  _PlayerLiveMetrics _liveMetricsForPlayer(TrackerPlayerOption player) {
    final local = _localTrackForPlayer(player.id);
    final session = _sessionForPlayer(player.id);
    final heartRate = _liveTelemetryActive ? _heartRateForPlayerId(player.id) : null;

    final localDistance = _safeLiveDistance(
      local?.totalDistanceM ?? 0,
      durationSec: local?.durationSec,
    );
    final serverDistance = _safeLiveDistance(
      session?.totalDistanceM ?? 0,
      durationSec: session?.durationSec,
    );
    final distance = _liveTelemetryActive
        ? math.max(localDistance, serverDistance)
        : 0.0;
    final speed = _liveTelemetryActive
        ? _currentLiveSpeed(
            local: local,
            serverSpeed: session?.speedKmh ?? 0.0,
          )
        : 0.0;
    final maxSpeed = _liveTelemetryActive
        ? math.max(
            _safeLiveSpeed(local?.maxSpeedKmh ?? 0),
            _safeLiveSpeed(session?.maxSpeedKmh ?? 0),
          )
        : 0.0;
    final sprintCount = _liveTelemetryActive
        ? math.max(local?.sprintCount ?? 0, session?.sprintCount ?? 0)
        : 0;
    final accelCount = _liveTelemetryActive
        ? math.max(local?.accelCount ?? 0, session?.accelCount ?? 0)
        : 0;
    final decelCount = _liveTelemetryActive
        ? math.max(local?.decelCount ?? 0, session?.decelCount ?? 0)
        : 0;
    final turnCount = _liveTelemetryActive
        ? math.max(
            local?.changeOfDirectionCount ?? 0,
            session?.changeOfDirectionCount ?? 0,
          )
        : 0;
    final hirDistanceM = _liveTelemetryActive
        ? math.max(
            local?.hirDistanceM ?? 0.0,
            session?.hirDistanceM ?? 0.0,
          )
        : 0.0;
    final durationSec = _liveTelemetryActive
        ? math.max(local?.durationSec ?? 0, session?.durationSec ?? 0)
        : 0;
    final localLoad = local?.loadScore ?? 0.0;
    final load = _liveTelemetryActive
        ? math.max(localLoad, session?.loadScore ?? 0.0)
        : 0.0;
    final explosiveActions = accelCount + decelCount + sprintCount;
    final warnings = _liveEventsForPlayer(player.id);

    return _PlayerLiveMetrics(
      distanceM: distance,
      currentSpeedKmh: speed,
      maxSpeedKmh: maxSpeed,
      sprintCount: sprintCount,
      accelCount: accelCount,
      decelCount: decelCount,
      turnCount: turnCount,
      hirDistanceM: hirDistanceM,
      durationSec: durationSec,
      loadScore: load,
      explosiveActions: explosiveActions,
      heartRateBpm: heartRate?.bpm,
      warningsCount: warnings.length,
      redWarningsCount: warnings.where((event) => event.isRed).length,
    );
  }

  bool _isActiveLiveStatus(String status) {
    final normalized = status.trim().toLowerCase();
    return normalized == 'active' ||
        normalized == 'online' ||
        normalized == 'live';
  }

  String _liveSessionMergeKey(TrackerLiveSessionModel session) {
    if (session.id > 0) return 'id:${session.id}';
    final playerId = _resolvedPlayerIdForSession(session) ?? session.playerId;
    if (playerId != null && playerId > 0) return 'player:$playerId';
    final uuid = session.deviceUuid.trim().toLowerCase();
    if (uuid.isNotEmpty) return 'device:$uuid';
    return 'row:${session.deviceName.trim().toLowerCase()}';
  }

  double _liveSessionDataScore(TrackerLiveSessionModel session) {
    return session.totalDistanceM +
        session.maxSpeedKmh * 10 +
        session.speedKmh * 5 +
        session.loadScore +
        session.durationSec / 10 +
        session.sprintDistanceM +
        session.hirDistanceM +
        session.vhirDistanceM;
  }

  TrackerLiveSessionModel _bestLiveSessionSnapshot(
      TrackerLiveSessionModel current, TrackerLiveSessionModel incoming) {
    final incomingActive = _isActiveLiveStatus(incoming.status);
    final currentActive = _isActiveLiveStatus(current.status);
    if (!incomingActive && currentActive && _running) return current;

    final incomingScore = _liveSessionDataScore(incoming);
    final currentScore = _liveSessionDataScore(current);
    if (incomingScore <= 0 && currentScore > 0 && _running) return current;
    if (incoming.durationSec <= 0 && current.durationSec > 0 && _running)
      return current;
    return incomingScore >= currentScore || incoming.isOnline
        ? incoming
        : current;
  }

  List<TrackerLiveSessionModel> _mergeLiveSessionsKeepRunning(
      List<TrackerLiveSessionModel> incoming) {
    if (!_running || _sessions.isEmpty) return incoming;
    if (incoming.isEmpty) {
      _lastLiveState =
          'server returned 0, keep ${_sessions.length} active live rows until Stop';
      return List<TrackerLiveSessionModel>.from(_sessions);
    }

    final merged = <String, TrackerLiveSessionModel>{};
    for (final session in _sessions) {
      if (_isActiveLiveStatus(session.status))
        merged[_liveSessionMergeKey(session)] = session;
    }
    for (final session in incoming) {
      final key = _liveSessionMergeKey(session);
      final current = merged[key];
      merged[key] = current == null
          ? session
          : _bestLiveSessionSnapshot(current, session);
    }

    final ordered = merged.values.toList(growable: false);
    ordered.sort((a, b) {
      final aOnline = a.isOnline ? 1 : 0;
      final bOnline = b.isOnline ? 1 : 0;
      if (aOnline != bOnline) return bOnline.compareTo(aOnline);
      return _liveSessionDataScore(b).compareTo(_liveSessionDataScore(a));
    });
    return ordered;
  }

  void _restoreRunningLiveIfNeeded(List<TrackerLiveSessionModel> sessions) {
    if (_blockServerAutoRestoreAfterPlayerPick) return;
    if (_running || _starting || _myLiveSessionId != null) return;
    final selectedId = widget.selectedPlayer?.id;
    if (selectedId == null || selectedId <= 0) return;

    TrackerLiveSessionModel? active;
    for (final session in sessions) {
      if (!_isActiveLiveStatus(session.status)) continue;
      if (!session.isOnline) continue;
      final playerId = _resolvedPlayerIdForSession(session) ?? session.playerId;
      if (playerId == selectedId) {
        active = session;
        break;
      }
    }
    if (active == null || active.id <= 0) return;

    _myLiveSessionId = active.id;
    _startedAt = DateTime.now()
        .subtract(Duration(seconds: math.max(0, active.durationSec)));
    unawaited(_syncLiveTacticalReviewSession());
    widget.onLiveSessionIdChanged?.call(active.id);
    _setLiveRunning(true);
    _lastProblem =
        'Live-сессия #${active.id} восстановлена: запись продолжается до явной кнопки Стоп.';
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_running || _myLiveSessionId != active?.id) return;
      if (_isTeamMultiLive) {
        // Командный coordinator уже опрашивает каждый BLE UUID своим каналом.
        // Одиночный widget.ble здесь не запускаем: именно он создавал в логах
        // бесконечные fallback #1..#29 и `нет connectedInfo/lastKnownInfo`.
        _startPolling();
        return;
      }
      if (_effectiveStartMode() == TrackerLiveSourceMode.heartRateOnly) {
        _startHeartRateOnlyLoop();
      } else {
        _startTrackerLoop();
      }
    });
  }

  Future<void> _loadLivePeriods() async {
    final id = _myLiveSessionId;
    if (id == null || id <= 0) return;
    try {
      final serverPeriods = await _api.loadLivePeriods(liveSessionId: id);
      if (!mounted || serverPeriods.isEmpty) return;
      setState(() {
        _periods
          ..clear()
          ..addAll(serverPeriods.map(_LivePeriod.fromJson));
      });
    } catch (e) {
      _log('Periods load skipped: $e');
    }
  }

  String _liveSourceTitle(TrackerLiveSourceMode mode) {
    switch (mode) {
      case TrackerLiveSourceMode.trackerExperimental:
        return 'GPS-трекер';
      case TrackerLiveSourceMode.heartRateOnly:
        return 'Polar H10 команда';
    }
  }

  IconData _liveSourceIcon(TrackerLiveSourceMode mode) {
    switch (mode) {
      case TrackerLiveSourceMode.trackerExperimental:
        return Icons.sensors_rounded;
      case TrackerLiveSourceMode.heartRateOnly:
        return Icons.monitor_heart_rounded;
    }
  }

  bool get _hasTeamHeartRateOnline => widget.heartRateByPlayerId.values.any(
      (sample) => DateTime.now().difference(sample.measuredAt).inSeconds <= 25);

  TrackerLiveSourceMode _effectiveStartMode() {
    if (_mode != TrackerLiveSourceMode.trackerExperimental) return _mode;
    final hasTracker = _teamTrackerReady || widget.ble.connectedInfo != null;
    if (!hasTracker &&
        (widget.heartRateByPlayerId.isNotEmpty ||
            widget.heartRateConnectedCount > 0))
      return TrackerLiveSourceMode.heartRateOnly;
    return _mode;
  }

  Future<void> _startLive() async {
    _blockServerAutoRestoreAfterPlayerPick = false;
    if (_running && _paused) {
      _resumeLiveCollection();
      return;
    }

    if (widget.onStartTeamLive != null) {
      if (_starting) return;
      setState(() {
        _starting = true;
        _lastProblem =
            'Запускаю командный Live для ${widget.teamTrackerCount} GPS-трекеров...';
      });
      try {
        final id = await widget.onStartTeamLive!.call();
        if (id == null || id <= 0) {
          throw StateError(
            'Сервер не вернул Live-сессию для подключённых GPS',
          );
        }
        _myLiveSessionId = id;
        widget.onLiveSessionIdChanged?.call(id);
        _resetRuntimeTelemetryForNewLive();
        _setLiveRunning(true);
        unawaited(_syncLiveTacticalReviewSession());
        _paused = false;
        _lastProblem =
            'Командный Live активен · GPS ${widget.teamTrackerCount}';
        _log(
            'TEAM MULTI LIVE START: count=${widget.teamTrackerCount} firstSession=$id');
        _startPolling();
      } catch (e) {
        _lastProblem = 'Ошибка запуска командного Live: $e';
        _log(_lastProblem);
        unawaited(_serverLog(
          _lastProblem,
          level: 'error',
          source: 'team_live_ui_start_error',
        ));
        _toast(_lastProblem);
      } finally {
        if (mounted) setState(() => _starting = false);
      }
      return;
    }

    final field = widget.selectedField;
    final beforeDevice = widget.ble.connectedInfo;
    final beforeLastKnown = widget.ble.lastKnownInfo;
    final beforeChannel = widget.ble.commandChannelReady;
    int? startedSessionId;

    _log(
        'START CHECK #1: running=$_running paused=$_paused starting=$_starting mode=${_mode.name} activity=${_activity.code} '
        'field=${field?.id}/${field?.hasCalibration} channel=$beforeChannel '
        'device=${beforeDevice?.name}/${beforeDevice?.id} lastKnown=${beforeLastKnown?.name}/${beforeLastKnown?.id}');
    unawaited(_serverLog(
      'START CHECK #1: running=$_running paused=$_paused starting=$_starting mode=${_mode.name} activity=${_activity.code} '
      'field=${field?.id}/${field?.hasCalibration} channel=$beforeChannel '
      'device=${beforeDevice?.name}/${beforeDevice?.id} lastKnown=${beforeLastKnown?.name}/${beforeLastKnown?.id}',
      source: 'live_start_check_1',
    ));

    final fieldMissing =
        _activity.requiresField && (field == null || !field.hasCalibration);
    final effectiveField = fieldMissing ? null : field;
    if (fieldMissing) {
      _toast(
          'Поле не откалибровано. Live запущу без проекции на карту: GPS/скорость/нагрузка будут сохраняться, поле можно откалибровать позже.');
      _lastProblem =
          'START WARNING: нет калибровки поля для режима «${_activity.title}». Стартую без field_id, чтобы не терять тренировку.';
      _log(_lastProblem);
      unawaited(_serverLog(_lastProblem,
          level: 'warning', source: 'live_start_no_field_fallback'));
      if (mounted) setState(() {});
    }

    setState(() {
      _starting = true;
      _lastProblem = 'Проверяю BLE TX/RX перед стартом Live...';
    });

    var device = widget.ble.connectedInfo;
    final startMode = _effectiveStartMode();
    try {
      if (startMode == TrackerLiveSourceMode.heartRateOnly) {
        _lastProblem =
            'Старт Live без GPS-трекера: активен командный Polar H10.';
        _log(_lastProblem);
        unawaited(_serverLog(_lastProblem,
            level: 'info', source: 'live_start_polar_only'));
      }
      if (startMode == TrackerLiveSourceMode.trackerExperimental) {
        _log('START CHECK #2: вызываю ensureCommandChannel()');
        unawaited(_serverLog(
          'START CHECK #2: ensureCommandChannel begin · command_channel_before=${widget.ble.commandChannelReady} · connected=${widget.ble.connectedInfo?.id} · lastKnown=${widget.ble.lastKnownInfo?.id}',
          source: 'live_start_ble_ensure_begin',
        ));

        final ready = await widget.ble.ensureCommandChannel();
        device = widget.ble.connectedInfo;

        _log(
            'START CHECK #3: ensureCommandChannel result=$ready channel=${widget.ble.commandChannelReady} device=${device?.name}/${device?.id} lastKnown=${widget.ble.lastKnownInfo?.name}/${widget.ble.lastKnownInfo?.id}');
        await _serverLog(
          'START CHECK #3: ensure result=$ready · command_channel_after=${widget.ble.commandChannelReady} · device=${device?.name}/${device?.id} · lastKnown=${widget.ble.lastKnownInfo?.name}/${widget.ble.lastKnownInfo?.id}',
          level: ready ? 'info' : 'error',
          source: 'live_start_ble_ensure_result',
        );

        if (!ready || device == null) {
          _toast(
              'Трекер выбран, но TX/RX канал не подключён. Нажмите «Поиск Bluetooth» и подключите датчик заново.');
          _lastProblem =
              'START BLOCKED: BLE TX/RX не готов. Live-сессию на сервере не создаю.';
          _log(_lastProblem);
          unawaited(_serverLog(_lastProblem,
              level: 'error', source: 'live_start_blocked_no_ble_channel'));
          return;
        }
      }

      final deviceUuid = startMode == TrackerLiveSourceMode.heartRateOnly
          ? 'POLAR-H10-TEAM-${widget.teamId}'
          : device!.id;

      final deviceName = startMode == TrackerLiveSourceMode.heartRateOnly
          ? 'Polar H10 команда'
          : device!.name;

      final livePlayerId = startMode == TrackerLiveSourceMode.heartRateOnly
          ? null
          : widget.selectedPlayer?.id;

      _lastProblem = 'Создаю Live-сессию на сервере...';
      setState(() {});

      _log(
          'START CHECK #4: API startLiveSession player=$livePlayerId field=${_activity.requiresField ? effectiveField?.id : null} device=$deviceName/$deviceUuid');
      await _serverLog(
        'START CHECK #4: API startLiveSession · player=$livePlayerId · field=${_activity.requiresField ? effectiveField?.id : null} · device=$deviceName/$deviceUuid · activity=${_activity.code}',
        source: 'live_start_api_begin',
      );

      final id = await _api.startLiveSession(
        clubId: widget.clubId,
        teamId: widget.teamId,
        playerId: livePlayerId,
        fieldId: _activity.requiresField ? effectiveField?.id : null,
        deviceUuid: deviceUuid,
        deviceName: deviceName,
        source: startMode == TrackerLiveSourceMode.heartRateOnly
            ? 'heart_rate'
            : 'tracker',
        batteryPercent: widget.batteryPercent,
        activityType: _activity.code,
        fieldRequired: _activity.requiresField && effectiveField != null,
      );
      startedSessionId = id;

      _log('START CHECK #5: API returned live_session_id=$id');
      await _serverLog(
        'START CHECK #5: API returned live_session_id=$id',
        level: id > 0 ? 'info' : 'error',
        source: 'live_start_api_result',
      );

      if (id <= 0) throw Exception('сервер не вернул live_session_id');

      _myLiveSessionId = id;
      widget.onLiveSessionIdChanged?.call(id);
      _resetRuntimeTelemetryForNewLive();
      _setLiveRunning(true);
      unawaited(_syncLiveTacticalReviewSession());
      _lastProblem =
          'Live запущен. Таймлайн готов: добавляйте периоды тренировки.';
      await _syncLocalPeriodsToServer();

      _myLiveSessionId = id;
      widget.onLiveSessionIdChanged?.call(id);
      _setLiveRunning(true);
      _blockServerAutoRestoreAfterPlayerPick = false;
      _teamLoadHistory.clear();
      _recordTeamLoadSnapshot(force: true);
      _lastProblem = 'Live активен · режим: ${_activity.title}';
      // Не отправляем battery keep-alive первым пакетом: первым должен уйти именно GPS-запрос.
      _lastBatteryKeepAliveAt = DateTime.now();
      _lastTrackerTxAt = null;
      _lastGpsProbeAt = null;
      _bleOfflineSince = null;
      _nextBleReconnectAttemptAt = null;
      _lastBleOfflineLogAt = null;
      _offlineRecorderStatus = 'проверяю запись на трекере';

      _trackForCurrentDevice();

      if (startMode == TrackerLiveSourceMode.trackerExperimental) {
        unawaited(_syncTrackerRecorderStateAfterReconnect(
            source: 'live_start_record_probe'));
        _candidateCommandIndex = _lastGpsCandidateWithFix ?? 0;
        _gpsMissesForCandidate = 0;
        _lastGpsProbeAt = null;
      }

      _log(
          'START CHECK #6: запускаю loop=${startMode == TrackerLiveSourceMode.heartRateOnly ? 'heartRateOnly' : 'trackerGps'} session=$id');
      unawaited(_serverLog(
        'START CHECK #6: loop started · mode=${startMode.name} · session=$id · command_channel=${widget.ble.commandChannelReady}',
        source: 'live_start_loop_begin',
      ));

      if (startMode == TrackerLiveSourceMode.heartRateOnly) {
        _startHeartRateOnlyLoop();
      } else {
        _startTrackerLoop();
      }

      _log('Live стартовал: session=$id');
      _serverLog('Live стартовал: session=$id', source: 'live_start');
      await _loadLiveState();
    } catch (e) {
      final idToClose = startedSessionId ?? _myLiveSessionId;
      _lastProblem = 'Ошибка старта Live: $e';
      _log(_lastProblem);
      if (idToClose != null && idToClose > 0) {
        unawaited(_api
            .stopLiveSession(
                liveSessionId: idToClose, createFinalSession: false)
            .catchError((_) => <String, dynamic>{}));
      }
      _phoneTimer?.cancel();
      _trackerTimer?.cancel();
      _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
      _myLiveSessionId = null;
      widget.onLiveSessionIdChanged?.call(null);
      _setLiveRunning(false);
      unawaited(_serverLog(_lastProblem,
          level: 'error', source: 'live_start_exception'));
      _toast('Live: $e');
    } finally {
      if (mounted) setState(() => _starting = false);
    }
  }

  void _startHeartRateOnlyLoop() {
    _phoneTimer?.cancel();
    _trackerTimer?.cancel();
    _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();

    Future<void> tick() async {
      final id = _myLiveSessionId;
      if (!_running || id == null) return;
      try {
        await _api.heartbeatLiveSession(
            liveSessionId: id, statusText: 'heart_rate_only');
        await _loadLiveState();
        _lastProblem = widget.heartRateByPlayerId.isEmpty
            ? 'Live идёт без GPS: ожидаю online bpm от Polar H10.'
            : 'Live идёт по Polar H10: ${widget.heartRateByPlayerId.length} игрок(ов) с ЧСС online. GPS-трекер не обязателен.';
        if (mounted) setState(() {});
      } catch (e) {
        _log('Polar-only heartbeat: $e');
      }
    }

    tick();
    _heartbeatTimer = Timer.periodic(const Duration(seconds: 5), (_) => tick());
  }

  String _formatRecorderStatus(List<ActionTrackerRecord> records) {
    if (records.isEmpty) return 'на датчике нет записей';
    final recording = records
        .where((r) => r.state == ActionTrackerRecordState.recording)
        .toList();
    if (recording.isNotEmpty) {
      final r = recording.first;
      return 'идёт запись на трекере · file ${r.fileId} · ${r.length} байт';
    }
    final finished = records
        .where(
            (r) => r.state == ActionTrackerRecordState.finished || r.length > 0)
        .toList()
      ..sort((a, b) {
        final byEnd = b.endTimeMs.compareTo(a.endTimeMs);
        if (byEnd != 0) return byEnd;
        return b.fileId.compareTo(a.fileId);
      });
    if (finished.isNotEmpty) {
      final r = finished.first;
      return 'есть готовая запись · file ${r.fileId} · ${r.length} байт';
    }
    return 'запись на трекере не идёт';
  }

  Future<void> _syncTrackerRecorderStateAfterReconnect(
      {String source = 'live_record_probe'}) async {
    final now = DateTime.now();
    if (_lastPostReconnectSyncAt != null &&
        now.difference(_lastPostReconnectSyncAt!).inSeconds < 10) return;
    if (!widget.ble.commandChannelReady) return;
    _lastPostReconnectSyncAt = now;
    try {
      _offlineRecorderStatus = 'запрашиваю состояние записи на трекере';
      if (mounted) setState(() {});
      await widget.ble.requestBatteryAndGpsState();
      await Future<void>.delayed(const Duration(milliseconds: 450));
      await widget.ble.requestRecordList();
      await _serverLog('Запрошен список записей после восстановления BLE',
          source: source);
    } catch (e) {
      _offlineRecorderStatus = 'не удалось проверить запись на трекере: $e';
      _log(_offlineRecorderStatus);
      unawaited(_serverLog(_offlineRecorderStatus,
          level: 'warning', source: '${source}_error'));
    } finally {
      if (mounted) setState(() {});
    }
  }

  void _startTrackerLoop() {
    _trackerTimer?.cancel();
    _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
    if (_isTeamMultiLive) {
      _log(
          'TEAM LIVE: одиночный BLE GPS loop пропущен, работает coordinator пула');
      return;
    }

    Future<void> tick() async {
      if (!_running || _paused || _trackerTxInFlight) return;
      final now = DateTime.now();
      if (_lastTrackerTxAt != null &&
          now.difference(_lastTrackerTxAt!).inMilliseconds < 2200) return;

      final commands = ActionTrackerBleProfile.commandCurrentGpsCandidates
          .toList(growable: false);
      if (commands.isEmpty) return;

      // Критично: раньше смена GPS-команды почти никогда не срабатывала, потому что
      // _lastTrackerTxAt обновлялся при каждом TX и условие "6 секунд без TX" не наступало.
      // Поэтому Live фактически снова слал только первый кандидат 3A, а сессия жила
      // только heartbeat-ом: duration рос, но save_tracker_live_point.php не получал точек.
      final gpsFresh =
          _lastGpsAt != null && now.difference(_lastGpsAt!).inSeconds <= 4;
      var commandIndex =
          _candidateCommandIndex.clamp(0, commands.length - 1).toInt();
      var command = commands[commandIndex];
      var txReason = 'GPS candidate ${commandIndex + 1}/${commands.length}';
      // Keep-alive раз в 25 секунд: не подменяем им первый GPS-запрос и не считаем его
      // неудачной GPS-попыткой. Это только удержание BLE/GPS готовности.
      if (_lastBatteryKeepAliveAt != null &&
          now.difference(_lastBatteryKeepAliveAt!).inSeconds >= 25) {
        command = ActionTrackerBleProfile.commandReadBatteryAndGps;
        txReason = 'battery/GPS keep-alive';
        _lastBatteryKeepAliveAt = now;
      } else if (!gpsFresh) {
        final probeGapOk = _lastGpsProbeAt == null ||
            now.difference(_lastGpsProbeAt!).inMilliseconds >= 1800;
        if (probeGapOk) {
          _gpsMissesForCandidate++;
          _lastGpsProbeAt = now;
          if (_gpsMissesForCandidate >= 3) {
            _candidateCommandIndex =
                (_candidateCommandIndex + 1) % commands.length;
            _gpsMissesForCandidate = 0;
            commandIndex =
                _candidateCommandIndex.clamp(0, commands.length - 1).toInt();
            command = commands[commandIndex];
            txReason = 'GPS candidate ${commandIndex + 1}/${commands.length}';
            _lastProblem =
                'GPS не пришёл — переключаю Live-команду на #${commandIndex + 1}/${commands.length}';
            _log(_lastProblem);
            unawaited(_serverLog(_lastProblem,
                level: 'warning', source: 'live_gps_command_fallback'));
          } else {
            _lastProblem =
                'GPS пока не пришёл, повторяю Live-команду #${commandIndex + 1} · попытка $_gpsMissesForCandidate/3';
            _log(_lastProblem);
          }
        }
      } else {
        _gpsMissesForCandidate = 0;
      }

      final cmd = command
          .map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase())
          .join(' ');

      // v80: если за время Live датчик уснул/отвалился, не бросаем сессию — пробуем
      // восстановить TX/RX перед следующей командой. Серверная сессия при этом остаётся active.
      if (!widget.ble.commandChannelReady) {
        _bleOfflineSince ??= now;
        final waitActive = _nextBleReconnectAttemptAt != null &&
            now.isBefore(_nextBleReconnectAttemptAt!);
        if (waitActive) {
          final shouldLog = _lastBleOfflineLogAt == null ||
              now.difference(_lastBleOfflineLogAt!).inSeconds >= 15;
          _lastProblem =
              'Трекер вне зоны BLE. Live-сессия #${_myLiveSessionId ?? 0} продолжается на сервере, запись на самом трекере не трогаю.';
          if (shouldLog) {
            _lastBleOfflineLogAt = now;
            _log(_lastProblem);
            unawaited(_serverLog(_lastProblem,
                level: 'warning', source: 'live_ble_out_of_range_wait'));
          }
          if (mounted) setState(() {});
          return;
        }

        _nextBleReconnectAttemptAt = now.add(const Duration(seconds: 8));
        _lastProblem = 'Проверяю возврат трекера в зону BLE...';
        if (mounted) setState(() {});
        final ready = await widget.ble.ensureCommandChannel();
        if (!ready) {
          final offlineSec = _bleOfflineSince == null
              ? 0
              : DateTime.now().difference(_bleOfflineSince!).inSeconds;
          _lastProblem =
              'Трекер пока вне зоны BLE · ${offlineSec}s. Серверная Live-сессия продолжается, после возврата запрошу записи с датчика.';
          _log(_lastProblem);
          unawaited(_serverLog(_lastProblem,
              level: 'warning', source: 'live_ble_reconnect_wait'));
          if (mounted) setState(() {});
          return;
        }

        final offlineSec = _bleOfflineSince == null
            ? 0
            : DateTime.now().difference(_bleOfflineSince!).inSeconds;
        _bleOfflineSince = null;
        _nextBleReconnectAttemptAt = null;
        _lastBleOfflineLogAt = null;
        _lastProblem =
            'BLE восстановлен после ${offlineSec}s. Запрашиваю батарею и список записей, затем продолжу Live.';
        _log(_lastProblem);
        await _serverLog(_lastProblem,
            level: 'info', source: 'live_ble_reconnected_sync');
        await _syncTrackerRecorderStateAfterReconnect(source: 'live_reconnect');
        _lastTrackerTxAt = DateTime.now();
        if (mounted) setState(() {});
        return;
      }

      _trackerTxInFlight = true;
      try {
        _lastTx = cmd;
        _lastTrackerTxAt = DateTime.now();
        _log('TX $txReason: $cmd');
        await widget.ble.sendRawCommand(command);
      } catch (e) {
        _lastProblem =
            'TX GPS: $e · Live не остановлен, пробую восстановить BLE';
        _log(_lastProblem);
        unawaited(_serverLog(_lastProblem,
            level: 'error', source: 'live_tx_error_keep_session'));
      } finally {
        _trackerTxInFlight = false;
      }
    }

    tick();
    _trackerTimer = Timer.periodic(const Duration(seconds: 1), (_) => tick());

    _heartbeatTimer = Timer.periodic(const Duration(seconds: 5), (_) async {
      final id = _myLiveSessionId;
      if (!_running || id == null) return;
      try {
        await _api.heartbeatLiveSession(liveSessionId: id);
        await _loadLiveState();
      } catch (e) {
        _log('Heartbeat: $e');
      }
    });
  }

  Future<void> _handleGpsPoint({
    required double latitude,
    required double longitude,
    required int timeMs,
    required String packetType,
    String? rawHex,
  }) async {
    final track = _trackForCurrentDevice();
    final stat = track.addPoint(
      latitude: latitude,
      longitude: longitude,
      timeMs: timeMs > 0 ? timeMs : DateTime.now().millisecondsSinceEpoch,
      packetType: packetType,
    );

    _lastGpsAt = DateTime.now();
    _lastGps =
        '${latitude.toStringAsFixed(6)}, ${longitude.toStringAsFixed(6)} · $packetType';

    _lastLocalMetrics = _debugTrackLine(track);
    _lastZeroReason = _debugZeroReason(track, stat);
    _recordTeamLoadSnapshot();

    if (!stat.acceptedForMetrics) {
      _lastProblem = stat.rejectReason ??
          'GPS-шум отфильтрован. Скорость и дистанция не засчитаны.';
    } else if (stat.distanceDeltaM <= 0.25 && track.points.length > 1) {
      _lastProblem =
          'GPS приходит, но смещение меньше 25 см. Скорость будет около 0.';
    } else {
      _lastProblem = 'GPS принят, скорость считается локально';
    }

    _log('LOCAL ${_lastLocalMetrics}; reason=$_lastZeroReason');
    if (stat.acceptedForMetrics && stat.distanceDeltaM > 0.01) {
      _pulseRuntimeMotion();
    }
    if (mounted) setState(() {});

    await _savePoint(
      latitude: stat.lat,
      longitude: stat.lon,
      rawLatitude: latitude,
      rawLongitude: longitude,
      acceptedForMetrics: stat.acceptedForMetrics,
      rejectReason: stat.rejectReason,
      timeMs: timeMs,
      packetType: packetType,
      rawHex: rawHex,
    );

    if (_myLiveSessionId != null &&
        track.points.length >= 10 &&
        track.points.length % 30 == 0) {
      await _saveMetricSnapshot(manual: false);
    }
  }

  Future<void> _savePoint({
    required double latitude,
    required double longitude,
    required double rawLatitude,
    required double rawLongitude,
    required bool acceptedForMetrics,
    String? rejectReason,
    required int timeMs,
    required String packetType,
    String? rawHex,
  }) async {
    final id = _myLiveSessionId;
    if (id == null || _savingPoint) return;

    final device = widget.ble.connectedInfo;
    final deviceUuid = device?.id ?? 'TRACKER';

    final track = _trackForCurrentDevice();
    final analysis = _trackAnalysisWithHeartRate(track);

    final payload = TrackerLivePointPayload(
      liveSessionId: id,
      clubId: widget.clubId,
      teamId: widget.teamId,
      playerId: widget.selectedPlayer?.id,
      deviceUuid: deviceUuid,
      latitude: latitude,
      longitude: longitude,
      rawLatitude: rawLatitude,
      rawLongitude: rawLongitude,
      acceptedForMetrics: acceptedForMetrics,
      rejectReason: rejectReason,
      timeMs: timeMs,
      batteryPercent: widget.batteryPercent,
      speedKmh: track.speedKmh,
      rawSpeedKmh: track.rawSpeedKmh,
      distanceDeltaM: track.lastDeltaM,
      totalDistanceM: track.totalDistanceM,
      maxSpeedKmh: track.maxSpeedKmh,
      avgSpeedKmh: track.avgSpeedKmh,
      meteragePerMin: track.metersPerMinute,
      loadScore: track.loadScore,
      loadPerMin: track.loadPerMinute,
      fatigueIndex: track.fatigueIndex,
      speedDropPercent: track.speedDropPercent,
      hsrDistanceM: track.hsrDistanceM,
      hirDistanceM: track.hirDistanceM,
      vhirDistanceM: track.vhirDistanceM,
      sprintDistanceM: track.sprintDistanceM,
      sprintCount: track.sprintCount,
      accelCount: track.accelCount,
      decelCount: track.decelCount,
      changeOfDirectionCount: track.changeOfDirectionCount,
      footballMovementScore: track.footballMovementScore,
      metabolicPowerProxy: track.metabolicPowerProxy,
      durationSec: track.durationSec,
      analysisJson: analysis,
      rawHex: rawHex,
    );

    final payloadJson = payload.toJson();
    _lastPayload = _debugPayloadLine(payloadJson);
    _lastLocalMetrics = _debugTrackLine(track);

    setState(() => _savingPoint = true);

    try {
      _log('PAYLOAD $_lastPayload');

      final result = await _api.saveLivePoint(payload);

      _lastServer = _debugServerLine(result);
      _lastSaveAt = DateTime.now();
      final speed = result['speed_kmh'] ?? 0;
      final delta = result['distance_delta_m'] ?? 0;
      final field = result['field'];
      final fieldWarning = field is Map ? field['field_warning'] : null;

      if (fieldWarning != null) {
        _lastProblem =
            'Сервер сохранил GPS, но координата поля вне диапазона. Проверьте калибровку.';
      } else {
        _lastProblem = 'Точка сохранена на сервере';
      }

      _lastSave = 'OK · $speed км/ч · +$delta м';
      _log('SERVER $_lastServer');
      _log('Точка сохранена: $_lastSave');
      await _serverLog(
        'point saved: $_lastSave · payload=$_lastPayload · server=$_lastServer · $packetType',
        source: 'save_point',
        rawHex: rawHex,
      );
      await _loadLiveState();
    } catch (e) {
      _lastSave = 'ОШИБКА: $e';
      _lastServer = 'ОШИБКА: $e';
      _lastProblem = 'Сервер не сохранил точку: $e';
      _log('Сохранение точки: $e');
      await _serverLog(
        'save point error: $e · payload=$_lastPayload',
        level: 'error',
        source: 'save_point',
        rawHex: rawHex,
      );
    } finally {
      if (mounted) setState(() => _savingPoint = false);
    }
  }

  Future<void> _saveMetricSnapshot({required bool manual}) async {
    final track = _mainTrack;
    final liveId = _myLiveSessionId;
    if (track == null || track.points.length < 2 || liveId == null) {
      if (manual) _toast('Недостаточно данных для сохранения метрик');
      return;
    }

    final device = widget.ble.connectedInfo;
    try {
      await _api.saveLiveMetricSnapshot({
        'club_id': widget.clubId,
        'team_id': widget.teamId,
        'player_id': widget.selectedPlayer?.id,
        'live_session_id': liveId,
        'device_uuid': device?.id ?? 'TRACKER',
        'device_name': device?.name ?? 'Источник Live',
        'snapshot_date': DateTime.now().toIso8601String().substring(0, 10),
        'snapshot_time': DateTime.now().toIso8601String(),
        'activity_type': _activity.code,
        'activity_title': _activity.title,
        'field_required': _activity.requiresField ? 1 : 0,
        'duration_sec': track.durationSec,
        'speed_kmh': track.speedKmh,
        'max_speed_kmh': track.maxSpeedKmh,
        'avg_speed_kmh': track.avgSpeedKmh,
        'distance_m': track.totalDistanceM,
        'meterage_per_min': track.metersPerMinute,
        'pace_min_km': track.paceMinKm,
        'load_score': track.loadScore,
        'load_per_min': track.loadPerMinute,
        'fatigue_index': track.fatigueIndex,
        'speed_drop_percent': track.speedDropPercent,
        'hsr_distance_m': track.hsrDistanceM,
        'hir_distance_m': track.hirDistanceM,
        'vhir_distance_m': track.vhirDistanceM,
        'sprint_distance_m': track.sprintDistanceM,
        'sprint_count': track.sprintCount,
        'accel_count': track.accelCount,
        'decel_count': track.decelCount,
        'change_of_direction_count': track.changeOfDirectionCount,
        'football_movement_score': track.footballMovementScore,
        'metabolic_power_proxy': track.metabolicPowerProxy,
        'work_rest_ratio': track.workRestRatio,
        'recommendation': track.recommendation,
        if (_selectedHeartRateSample != null)
          'heart_rate_bpm': _selectedHeartRateSample!.bpm,
        if (_selectedHeartRateSample?.batteryPercent != null)
          'heart_rate_battery_percent':
              _selectedHeartRateSample!.batteryPercent,
        if (_selectedHeartRateSample != null)
          'heart_rate_device_uuid': _selectedHeartRateSample!.deviceId,
        if (_selectedHeartRateSample != null)
          'heart_rate_device_name': _selectedHeartRateSample!.deviceName,
        'analysis_json': _trackAnalysisWithHeartRate(track),
      });
      _log(
          'Metric snapshot сохранён: load=${track.loadScore.toStringAsFixed(0)}, fatigue=${track.fatigueIndex.toStringAsFixed(0)}%');
      if (manual) _toast('Метрики Live сохранены по дате');
    } catch (e) {
      _log('Metric snapshot error: $e');
      if (manual) _toast('Ошибка сохранения метрик: $e');
    }
  }

  Future<void> _stopLive() async {
    await _flushLiveTacticalReviewSave();
    if (widget.onStopTeamLive != null) {
      _setLiveRunning(false);
      _paused = false;
      _phoneTimer?.cancel();
      _trackerTimer?.cancel();
      _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
      try {
        await widget.onStopTeamLive!.call(true);
        _lastProblem = 'Командный Live остановлен и сохранён';
      } catch (e) {
        _lastProblem = 'Ошибка остановки командного Live: $e';
      }
      _myLiveSessionId = null;
      _liveTacticalReviewMode = false;
      _liveTacticalFreezeTracks = <_RuntimeTrack>[];
      widget.onLiveSessionIdChanged?.call(null);
      await _loadLiveState(restoreRunning: false);
      if (mounted) setState(() {});
      return;
    }
    _setLiveRunning(false);
    _paused = false;
    _phoneTimer?.cancel();
    _trackerTimer?.cancel();
    _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();

    final id = _myLiveSessionId;
    if (id != null) {
      try {
        final result = await _api.stopLiveSession(
          liveSessionId: id,
          createFinalSession: true,
        );
        _lastStop = _shortJson(result, max: 1200);
        final finalId = result['final_session_id'] ??
            result['session_id'] ??
            result['tracker_session_id'];
        final copied = result['copied_session_points'] ??
            result['points_count'] ??
            result['copied_points'];
        _lastProblem = finalId == null
            ? 'Live остановлен. Сервер ответил без final_session_id — проверь stop_tracker_live_session.php'
            : 'Live остановлен и сохранён как сессия #$finalId · точек=$copied';
        _log('Live остановлен: session=$id · stop=$_lastStop');
        unawaited(_serverLog(
          'Live STOP SAVE: session=$id · final_session=${finalId ?? 'нет'} · copied_points=${copied ?? 'нет'} · status=${finalId == null ? 'проверь stop_tracker_live_session.php' : 'ok'}',
          level: finalId == null ? 'warning' : 'info',
          source: 'live_stop_save_result',
        ));
        // Сохраняем финальный локальный snapshot метрик даже если серверная финализация вернула только live id.
        unawaited(_saveMetricSnapshot(manual: false));
      } catch (e) {
        _lastStop = 'ОШИБКА: $e';
        _lastProblem = 'Ошибка остановки Live: $e';
        _log(_lastProblem);
      }
    }

    _myLiveSessionId = null;
    _liveTacticalReviewMode = false;
    _liveTacticalFreezeTracks = <_RuntimeTrack>[];
    _blockServerAutoRestoreAfterPlayerPick = true;
    widget.onLiveSessionIdChanged?.call(null);
    await _loadLiveState(restoreRunning: false);
    if (mounted) setState(() {});
  }

  Future<void> _autoSaveLiveAfterParentDecision() async {
    if (!_running && _myLiveSessionId == null) return;
    await _flushLiveTacticalReviewSave();
    if (_isTeamMultiLive) {
      _phoneTimer?.cancel();
      _trackerTimer?.cancel();
      _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
      _paused = false;
      try {
        await widget.onStopTeamLive!.call(true);
        _lastProblem = 'Командный Live остановлен и сохранён';
      } catch (e) {
        _lastProblem = 'Ошибка остановки командного Live: $e';
      }
      _myLiveSessionId = null;
      _liveTacticalReviewMode = false;
      _liveTacticalFreezeTracks = <_RuntimeTrack>[];
      _setLiveRunning(false);
      widget.onLiveSessionIdChanged?.call(null);
      if (mounted) setState(() {});
      return;
    }
    _phoneTimer?.cancel();
    _trackerTimer?.cancel();
    _heartbeatTimer?.cancel();
    _liveMapReplayTimer?.cancel();
    _paused = false;
    final id = _myLiveSessionId;
    _setLiveRunning(false);
    if (id != null) {
      try {
        final result = await _api.stopLiveSession(
            liveSessionId: id, createFinalSession: true);
        _lastStop = _shortJson(result, max: 1200);
        final finalId = result['final_session_id'] ??
            result['session_id'] ??
            result['tracker_session_id'];
        _lastProblem = finalId == null
            ? 'Live закрыт, сервер не вернул final_session_id. Проверьте stop_tracker_live_session.php.'
            : 'Live автоматически сохранён при выходе как сессия #$finalId';
        _log(
            "Live auto-save при закрытии: live=$id · final=${finalId ?? 'нет'}");
        unawaited(_serverLog(
            "Live auto-save on close: live=$id · final=${finalId ?? 'нет'} · result=$_lastStop",
            source: 'live_auto_save_on_close'));
      } catch (e) {
        _lastStop = 'ОШИБКА autosave: $e';
        _lastProblem = 'Ошибка автосохранения Live при выходе: $e';
        _log(_lastProblem);
      }
    }
    _myLiveSessionId = null;
    _liveTacticalReviewMode = false;
    _liveTacticalFreezeTracks = <_RuntimeTrack>[];
    _blockServerAutoRestoreAfterPlayerPick = true;
    widget.onLiveSessionIdChanged?.call(null);
    await _loadLiveState(restoreRunning: false);
    if (mounted) setState(() {});
  }

  void _pauseLiveCollection() {
    if (!_running) return;
    if (_paused) return;
    _phoneTimer?.cancel();
    _trackerTimer?.cancel();
    _paused = true;
    _lastProblem =
        'Live приостановлен. Сессия не завершена, данные уже отправленные на сервер сохранены. Нажмите «Продолжить», чтобы снова писать точки.';
    _log('Live приостановлен пользователем');
    if (mounted) setState(() {});
  }

  void _resumeLiveCollection() {
    if (!_running || !_paused) return;
    _paused = false;
    _lastProblem = 'Live продолжен. Запись точек снова активна.';
    if (_effectiveStartMode() == TrackerLiveSourceMode.heartRateOnly) {
      _startHeartRateOnlyLoop();
    } else {
      _startTrackerLoop();
    }
    _log('Live продолжен после паузы');
    if (mounted) setState(() {});
  }

  Future<void> _exitLiveWithoutSaving() async {
// По требованию: даже случайный выход/закрытие сохраняет тренировку.
// Кнопка старого «без сохранения» теперь работает как безопасное автосохранение.
    await _autoSaveLiveAfterParentDecision();
  }

  Future<void> _addDebugLocalPoint() async {
    final startLat = 55.973505;
    final startLon = 37.399388;
    final track = _trackForCurrentDevice();

    final index = track.points.length;
    final lat = startLat + index * 0.000006;
    final lon = startLon + index * 0.000010;

    await _handleGpsPoint(
      latitude: lat,
      longitude: lon,
      timeMs: DateTime.now().millisecondsSinceEpoch,
      packetType: 'LOCAL-TEST',
      rawHex: null,
    );

    _lastProblem =
        'Добавлена тестовая точка на устройстве. Если она двигается — UI работает, проблема в GPS/сервере.';
    if (mounted) setState(() {});
  }

  Future<void> _addDebugIntensitySequence() async {
// Диагностический тест: искусственно создаёт HIR/VHIR/SPR/ACC/DEC/COD.
// Нужен, чтобы быстро понять: UI/Flutter/сервер умеют показывать метрики или нет.
    final now = DateTime.now().millisecondsSinceEpoch;
    final last =
        _mainTrack?.points.isNotEmpty == true ? _mainTrack!.points.last : null;
    double lat = last?.lat ?? 55.973505;
    double lon = last?.lon ?? 37.399388;
    int t = last?.timeMs ?? now;

    final steps = <_DebugStep>[
      const _DebugStep(northM: 0, eastM: 0, dtMs: 1000, label: 'DEBUG-START'),
      const _DebugStep(northM: 4.2, eastM: 0, dtMs: 1000, label: 'DEBUG-HIR'),
      const _DebugStep(northM: 5.8, eastM: 0, dtMs: 1000, label: 'DEBUG-VHIR'),
      const _DebugStep(northM: 7.4, eastM: 0, dtMs: 1000, label: 'DEBUG-SPR'),
      const _DebugStep(northM: 0.5, eastM: 0, dtMs: 1000, label: 'DEBUG-DEC'),
      const _DebugStep(northM: 0, eastM: 5.5, dtMs: 1000, label: 'DEBUG-COD'),
      const _DebugStep(northM: 0, eastM: 7.2, dtMs: 1000, label: 'DEBUG-SPR2'),
    ];

    _log('--- DEBUG intensity sequence start ---');
    for (final step in steps) {
      t += step.dtMs;
      lat += _latOffsetByMeters(step.northM);
      lon += _lonOffsetByMeters(step.eastM, lat);
      await _handleGpsPoint(
        latitude: lat,
        longitude: lon,
        timeMs: t,
        packetType: step.label,
        rawHex: null,
      );
      await Future<void>.delayed(const Duration(milliseconds: 120));
    }
    _lastProblem =
        'Отладочный тест HIR/VHIR/SPR выполнен. Если метрики появились локально, но не появились в SQL — проблема PHP/API.';
    _log(
        '--- DEBUG intensity sequence done: ${_debugTrackLine(_mainTrack)} ---');
    if (mounted) setState(() {});
  }

  Future<void> _testGpsCommands() async {
    if (_testingCommands) return;

    final device = widget.ble.connectedInfo;
    if (device == null) {
      _toast('Сначала подключите BLE-трекер');
      return;
    }

    setState(() => _testingCommands = true);

    try {
      _log('--- Проверка команд GPS ---');
      final commands = ActionTrackerBleProfile.commandCurrentGpsCandidates;

      for (var i = 0; i < commands.length; i++) {
        if (!mounted) break;

        final cmd = commands[i]
            .map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase())
            .join(' ');

        setState(() => _candidateCommandIndex = i);
        _log('TEST TX ${i + 1}/${commands.length}: $cmd');

        try {
          await widget.ble.sendRawCommand(commands[i]);
        } catch (e) {
          _log('TEST ERROR: $e');
        }

        await Future<void>.delayed(const Duration(milliseconds: 700));
      }

      _candidateCommandIndex = _lastGpsCandidateWithFix ?? 0;
      _gpsMissesForCandidate = 0;
      _log(
          '--- Проверка завершена. Рабочая команда: кандидат ${_candidateCommandIndex + 1} ---');
    } finally {
      if (mounted) setState(() => _testingCommands = false);
    }
  }

  String _runtimeTrackKey(ActionTrackerDevice? device) {
    final playerPart = 'P${widget.selectedPlayer?.id ?? 0}';
    return '${device?.id ?? 'TRACKER'}-$playerPart';
  }

  _RuntimeTrack _trackForCurrentDevice() {
    final device = widget.ble.connectedInfo;
    final key = _runtimeTrackKey(device);

    final playerName = widget.selectedPlayer?.name ?? 'Игрок';
    final deviceName = device?.name ?? 'Трекер';

    return _tracks.putIfAbsent(
      key,
      () => _RuntimeTrack(
        key: key,
        playerName: playerName,
        deviceName: deviceName,
        avatar: widget.selectedPlayer?.avatar,
      ),
    );
  }

  Future<void> _serverLog(
    String message, {
    String level = 'info',
    String source = 'live',
    String? rawHex,
  }) async {
    try {
      await _api.sendDebugLog(
        teamId: widget.teamId,
        playerId: widget.selectedPlayer?.id,
        liveSessionId: _myLiveSessionId,
        level: level,
        source: source,
        message: message,
        rawHex: rawHex,
      );
      _lastRemoteDebug = 'OK · $source · ${DateTime.now().toIso8601String()}';
    } catch (e) {
      // Удалённый debug не должен останавливать BLE/GPS-поток.
      // Если PHP-файл не загружен или таблица не создана, Live всё равно продолжает принимать GPS.
      _lastRemoteDebug = 'ОШИБКА debug endpoint: $e';
      _log('REMOTE DEBUG ERROR: $e');
    }
  }

  void _log(String text) {
    final line = '[${DateTime.now().toIso8601String()}] $text';
// ignore: avoid_print
    print('[TRACKER_LIVE] $line');

    if (!mounted) return;
    setState(() {
      _logs.insert(0, line);
      if (_logs.length > 220) _logs.removeLast();
    });
  }

  void _toast(String text) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(text,
            style: const TextStyle(
                color: _OF.text, fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w500)),
        backgroundColor: Colors.white,
        behavior: SnackBarBehavior.floating,
        elevation: 0,
        margin: const EdgeInsets.all(9),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(15)),
        duration: const Duration(seconds: 4),
      ),
    );
  }

  _RuntimeTrack? get _mainTrack {
    if (_tracks.isEmpty) return null;
    final key = _runtimeTrackKey(widget.ble.connectedInfo);
    if (_tracks.containsKey(key)) return _tracks[key];
    final selectedSuffix = '-P${widget.selectedPlayer?.id ?? 0}';
    for (final entry in _tracks.entries) {
      if (entry.key.endsWith(selectedSuffix)) return entry.value;
    }
    return widget.selectedPlayer == null ? _tracks.values.first : null;
  }

  static const double _uiMaxValidSpeedKmh = 36.0;
  static const double _uiStationarySpeedDeadbandKmh = 1.5;

  double _safeLiveSpeed(double value, {double limit = _uiMaxValidSpeedKmh}) {
    // Неверную скорость нельзя обрезать до потолка: иначе GPS-скачок
    // превращается в ложный рекорд. Полностью исключаем такое значение.
    if (!value.isFinite || value < 0 || value > limit) return 0;
    // Значения ниже очень медленной ходьбы — GPS-дрейф стоящего игрока. В Live
    // показываем 0.0, даже если старый server state ещё хранит 0.5–1.4.
    if (value < _uiStationarySpeedDeadbandKmh) return 0;
    return value;
  }

  double _currentLiveSpeed({
    required _RuntimeTrack? local,
    required double serverSpeed,
  }) {
    if (!_liveTelemetryActive) return 0.0;
    // Локальная GPS-точка свежее периодически обновляемого состояния сервера.
    // Если игрок уже остановился, не подменяем локальный 0 старой скоростью API.
    if (local != null && local.points.isNotEmpty) {
      return _safeLiveSpeed(local.speedKmh);
    }
    return _safeLiveSpeed(serverSpeed);
  }

  double _safeLiveDistance(
    double value, {
    int? durationSec,
    double maxAverageSpeedKmh = 24.0,
  }) {
    if (!value.isFinite || value < 0) return 0;

    // Проверяем дистанцию относительно длительности. Нереальную серверную
    // дистанцию не показываем и не используем в рейтингах.
    if (durationSec != null && durationSec > 0) {
      final maxPlausibleM = (durationSec * (maxAverageSpeedKmh / 3.6)) + 250.0;
      if (value > maxPlausibleM) return 0;
    }

    // Абсолютная страховка от повреждённых значений.
    if (value > 100000.0) return 0;
    return value;
  }

  double get _displaySpeedKmh {
    final local = _mainTrack;
    return _currentLiveSpeed(
      local: local,
      serverSpeed: _sessions.isEmpty ? 0.0 : _sessions.first.speedKmh,
    );
  }

  double get _displayDistanceM {
    if (!_liveTelemetryActive) return 0.0;
    final localTrack = _mainTrack;
    final local = _safeLiveDistance(
      localTrack?.totalDistanceM ?? 0,
      durationSec: localTrack?.durationSec,
    );
    if (local > 0) return local;

    if (_sessions.isEmpty) return 0;
    final session = _sessions.first;
    return _safeLiveDistance(
      session.totalDistanceM,
      durationSec: session.durationSec,
    );
  }

  int get _displayPoints => _liveTelemetryActive
      ? _tracks.values.fold<int>(0, (s, t) => s + t.points.length)
      : 0;

  Widget _ofVerticalDivider() =>
      Container(width: 1, color: _OF.line.withOpacity(.78));
  Widget _ofHorizontalDivider() =>
      Container(height: 1, color: _OF.line.withOpacity(.78));

  @override
  Widget build(BuildContext context) {
    super.build(context);

    final monitoredPlayers = _monitorCandidatePlayers();
    final online =
        monitoredPlayers.where((p) => _isPlayerOnlineLive(p.id)).length;
    final active = monitoredPlayers.length;

    return DefaultTextStyle.merge(
      // Inter подключается через единый AppTypography, как во флагманских CMR-экранах.
      // Локальные размеры/насыщенность сохраняются, но семейство шрифта едино во всём Live.
      style: AppTypography.custom(
        size: AppTypography.bodySize,
        weight: FontWeight.w500,
        color: _OF.text,
        height: 1.22,
        letterSpacing: 0,
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final width = constraints.maxWidth;
          late final Widget base;

          if (width < 720) {
            base = widget.workspaceFullscreen
                ? _phoneFullscreenLiveLayout(online, active)
                : _phoneOpenFieldLayout(online, active);
          } else if (widget.workspaceFullscreen) {
            // Полноэкранный Live использует ту же композицию, что и полный
            // разбор матча: постоянное меню слева сохраняется уже с планшета.
            // Поэтому при 720–980 px больше не проваливаемся в старый
            // tablet-layout без бокового меню.
            base = _desktopOpenFieldLayout(online, active);
          } else if (width < 980) {
            base = _tabletOpenFieldLayout(online, active);
          } else {
            base = _desktopOpenFieldLayout(online, active);
          }

          final liveSidebarVisible = width >= 720 &&
              (widget.workspaceFullscreen || width >= 980);
          final allCardsOverlayLeft = liveSidebarVisible
              ? (_desktopLiveSidebarWidth(width) + 9.0)
              : 8.0;
          final content = width < 720
              ? base
              : Stack(
                  fit: StackFit.expand,
                  children: [
                    Positioned.fill(child: base),
                    if (_monitorPlayersExpanded)
                      Positioned(
                        // Окно «Все карточки» занимает всю рабочую область
                        // трекера: от правого края левого меню до правого края.
                        // Правая колонка «Лента моментов» сохраняет свой размер,
                        // а дополнительная ширина отдаётся карточкам игроков.
                        top: 8,
                        // CMR-menu остаётся доступным даже когда открыты
                        // «Все карточки»: тренер может мгновенно перейти
                        // в Поле / Игроки / Журнал без закрытия окна.
                        left: allCardsOverlayLeft,
                        right: 8,
                        bottom: 8,
                        child: Material(
                          color: Colors.white,
                          elevation: 14,
                          shadowColor: Colors.black.withOpacity(.16),
                          borderRadius: BorderRadius.circular(18),
                          clipBehavior: Clip.antiAlias,
                          child: _tabletExpandedMonitorPlayersGrid(
                            compact: width < 1120 ||
                                constraints.maxHeight < 680,
                          ),
                        ),
                      ),
                  ],
                );

          return _withFloatingLiveWindow(content);
        },
      ),
    );
  }

  Widget _conceptTeamKpiStrip(int online, int active) {
    final players = _monitorCandidatePlayers();
    var totalDistance = 0.0;
    var speedSum = 0.0;
    var speedCount = 0;
    var maxSpeed = 0.0;
    var sprintCount = 0;
    var loadSum = 0.0;
    var loadCount = 0;
    var heartSum = 0;
    var heartCount = 0;

    if (_liveTelemetryActive) {
      for (final player in players) {
        final local = _localTrackForPlayer(player.id);
        final session = _sessionForPlayer(player.id);
        totalDistance += math.max(
          _safeLiveDistance(session?.totalDistanceM ?? 0.0,
              durationSec: session?.durationSec),
          _safeLiveDistance(local?.totalDistanceM ?? 0.0,
              durationSec: local?.durationSec),
        );
        final speed = _currentLiveSpeed(
          local: local,
          serverSpeed: session?.speedKmh ?? 0.0,
        );
        if (speed > 0) {
          speedSum += speed;
          speedCount++;
        }
        maxSpeed = math.max(
          maxSpeed,
          math.max(
            _safeLiveSpeed(session?.maxSpeedKmh ?? 0.0),
            _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0),
          ),
        );
        sprintCount +=
            math.max(session?.sprintCount ?? 0, local?.sprintCount ?? 0);
        final load =
            math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0);
        if (load > 0) {
          loadSum += load;
          loadCount++;
        }
        final heart = _heartRateForPlayerId(player.id);
        if (heart != null) {
          heartSum += heart.bpm;
          heartCount++;
        }
      }
    }

    // Если привязка конкретного игрока к live-сессии ещё не успела
    // разрешиться, не оставляем командные KPI нулевыми: берём безопасный
    // fallback из локальных GPS-треков, а при их отсутствии — из live API.
    // Это особенно важно в первые секунды после старта командного Live.
    if (_liveTelemetryActive &&
        (totalDistance <= 0 ||
            speedCount == 0 ||
            maxSpeed <= 0 ||
            sprintCount == 0 ||
            loadCount == 0)) {
      var fallbackDistance = 0.0;
      var fallbackSpeedSum = 0.0;
      var fallbackSpeedCount = 0;
      var fallbackMaxSpeed = 0.0;
      var fallbackSprintCount = 0;
      var fallbackLoadSum = 0.0;
      var fallbackLoadCount = 0;

      if (_tracks.isNotEmpty) {
        for (final track in _tracks.values) {
          fallbackDistance += _safeLiveDistance(
            track.totalDistanceM,
            durationSec: track.durationSec,
          );
          final speed = _safeLiveSpeed(track.speedKmh);
          if (speed > 0) {
            fallbackSpeedSum += speed;
            fallbackSpeedCount++;
          }
          fallbackMaxSpeed =
              math.max(fallbackMaxSpeed, _safeLiveSpeed(track.maxSpeedKmh));
          fallbackSprintCount += track.sprintCount;
          if (track.loadScore > 0) {
            fallbackLoadSum += track.loadScore;
            fallbackLoadCount++;
          }
        }
      } else {
        for (final session in _sessions.where((s) => s.isOnline)) {
          fallbackDistance += _safeLiveDistance(
            session.totalDistanceM,
            durationSec: session.durationSec,
          );
          final speed = _safeLiveSpeed(session.speedKmh);
          if (speed > 0) {
            fallbackSpeedSum += speed;
            fallbackSpeedCount++;
          }
          fallbackMaxSpeed =
              math.max(fallbackMaxSpeed, _safeLiveSpeed(session.maxSpeedKmh));
          fallbackSprintCount += session.sprintCount;
          if (session.loadScore > 0) {
            fallbackLoadSum += session.loadScore;
            fallbackLoadCount++;
          }
        }
      }

      if (totalDistance <= 0) totalDistance = fallbackDistance;
      if (speedCount == 0 && fallbackSpeedCount > 0) {
        speedSum = fallbackSpeedSum;
        speedCount = fallbackSpeedCount;
      }
      if (maxSpeed <= 0) maxSpeed = fallbackMaxSpeed;
      if (sprintCount == 0) sprintCount = fallbackSprintCount;
      if (loadCount == 0 && fallbackLoadCount > 0) {
        loadSum = fallbackLoadSum;
        loadCount = fallbackLoadCount;
      }
    }

    if (_liveTelemetryActive &&
        heartCount == 0 &&
        widget.heartRateByPlayerId.isNotEmpty) {
      final now = DateTime.now();
      for (final sample in widget.heartRateByPlayerId.values) {
        if (now.difference(sample.measuredAt).inSeconds > 35) continue;
        heartSum += sample.bpm;
        heartCount++;
      }
    }

    final avgSpeed = speedCount == 0 ? 0.0 : speedSum / speedCount;
    final avgLoad = loadCount == 0 ? 0.0 : loadSum / loadCount;
    final avgHeart = heartCount == 0 ? 0 : (heartSum / heartCount).round();
    final loadLabel = avgLoad <= 0
        ? '—'
        : _loadMarkLabel(avgLoad, heartRateBpm: avgHeart > 0 ? avgHeart : null);
    final loadColor = avgLoad <= 0
        ? _OF.muted2
        : _loadMarkColor(avgLoad,
            heartRateBpm: avgHeart > 0 ? avgHeart : null);

    Widget tile(String label, String value, String unit,
        {Color? accent, IconData? icon}) {
      return Container(
        padding: const EdgeInsets.fromLTRB(5, 4, 5, 4),
        decoration: BoxDecoration(
          color: _OF.soft.withOpacity(.72),
          borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                if (icon != null) ...[
                  Icon(icon, size: 11.5, color: accent ?? _OF.green),
                  const SizedBox(width: 4),
                ],
                Expanded(
                  child: Text(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: _OF.muted2,
                      fontSize: 7.2,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ],
            ),
            const Spacer(),
            Row(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Flexible(
                  child: Text(
                    value,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: accent ?? _OF.text,
                      fontSize: AppTypography.bodySize,
                      height: 1,
                      fontWeight: FontWeight.w800,
                      letterSpacing: -.2,
                    ),
                  ),
                ),
                if (unit.isNotEmpty) ...[
                  const SizedBox(width: 3),
                  Padding(
                    padding: const EdgeInsets.only(bottom: 1),
                    child: Text(
                      unit,
                      style: const TextStyle(
                        color: _OF.muted2,
                        fontSize: 6.8,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ],
        ),
      );
    }

    final tiles = <Widget>[
      tile('Дистанция', (totalDistance / 1000).toStringAsFixed(2), 'км',
          icon: Icons.route_rounded),
      tile('Средняя скорость', avgSpeed.toStringAsFixed(1), 'км/ч',
          icon: Icons.speed_rounded),
      tile('Макс. скорость', maxSpeed.toStringAsFixed(1), 'км/ч',
          icon: Icons.bolt_rounded),
      tile('Спринты', '$sprintCount', '', icon: Icons.directions_run_rounded),
      tile('ЧСС', avgHeart <= 0 ? '—' : '$avgHeart',
          avgHeart <= 0 ? '' : 'уд/мин',
          accent: avgHeart > 0 ? _OF.red : null,
          icon: Icons.favorite_rounded),
      tile('Нагрузка', loadLabel, '', accent: loadColor,
          icon: Icons.stacked_line_chart_rounded),
    ];

    return LayoutBuilder(
      builder: (context, c) {
        if (c.maxWidth < 460) {
          return GridView.builder(
            padding: EdgeInsets.zero,
            physics: const NeverScrollableScrollPhysics(),
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 3,
              crossAxisSpacing: 4,
              mainAxisSpacing: 4,
              childAspectRatio: 2.35,
            ),
            itemCount: tiles.length,
            itemBuilder: (_, index) => tiles[index],
          );
        }
        return Row(
          children: [
            for (var i = 0; i < tiles.length; i++) ...[
              if (i > 0) const SizedBox(width: 5),
              Expanded(child: tiles[i]),
            ],
          ],
        );
      },
    );
  }

  Widget _flagshipLiveSplit({
    required bool compact,
    required int online,
    required int active,
    bool showMonitorStrip = true,
  }) {
    final player = widget.selectedPlayer;
    // Карточки выбранных игроков идут одной общей лентой над всей рабочей
    // областью — от карты до правой панели. Игрок добавляется в ленту кнопкой
    // «+» из таблицы Live и остаётся доступен независимо от выбранной панели.
    final playersHeight = compact ? 92.0 : 98.0;

    if (_liveMapProExpanded) {
      return _liveMapProWorkspace(
        compact: compact,
        online: online,
        active: active,
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (showMonitorStrip && _liveViewShowMonitorStrip) ...[
          SizedBox(
            height: playersHeight,
            child: _tabletMonitorPlayersSection(compact: compact),
          ),
          _ofHorizontalDivider(),
        ],
        Expanded(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              // Карта — главный рабочий объект Live. Скрытие вспомогательных
              // блоков отдаёт карте освободившееся место, но не влияет на сбор данных.
              Expanded(
                flex: _liveViewShowSidePanel
                    ? (widget.workspaceFullscreen ? 62 : 65)
                    : 100,
                child: Column(
                  children: [
                    Expanded(child: _flagshipMapPanel()),
                    if (_liveViewShowTimeline)
                      _teamLiveTimelineBar(compact: compact),
                    if (_liveViewShowTeamKpis)
                      SizedBox(
                        height: compact ? 48 : 50,
                        child: _conceptTeamKpiStrip(online, active),
                      ),
                  ],
                ),
              ),
              if (_liveViewShowSidePanel) ...[
                _ofVerticalDivider(),
                Expanded(
                  flex: widget.workspaceFullscreen ? 38 : 35,
                  child: player == null || !_showSelectedPlayerDetail
                      ? _wholeTeamTablePanel(compact: true)
                      : _focusedPlayerDataPanel(player, compact: compact),
                ),
              ],
            ],
          ),
        ),
      ],
    );
  }

  double _desktopLiveSidebarWidth(double width) {
    // Та же шкала, что у полноэкранного разбора «Карта/Матч».
    if (width >= 1500) return 236.0;
    if (width >= 1180) return 220.0;
    if (width >= 980) return 200.0;
    if (width >= 820) return 184.0;
    return 168.0;
  }

  Widget _desktopOpenFieldLayout(int online, int active) {
    return LayoutBuilder(
      builder: (context, c) {
        final compactHeight = c.maxHeight < 680;
        final compactWidth = c.maxWidth < 1180;
        final sidebarWidth = _desktopLiveSidebarWidth(c.maxWidth);
        final fullscreen = widget.workspaceFullscreen;
        return Container(
          color: Colors.white,
          padding: fullscreen ? EdgeInsets.zero : const EdgeInsets.all(2),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SizedBox(
                width: sidebarWidth,
                child: _desktopLiveSidebar(
                  online: online,
                  active: active,
                  compact: compactWidth || compactHeight,
                ),
              ),
              _ofVerticalDivider(),
              Expanded(
                child: Column(
                  children: [
                    if (fullscreen)
                      _fullscreenLiveControlHeader(
                        online: online,
                        active: active,
                        compact: compactWidth || compactHeight,
                      )
                    else
                      _liveControlStrip(online, active, compact: compactHeight),
                    _ofHorizontalDivider(),
                    if (fullscreen) ...[
                      SizedBox(
                        height: compactHeight ? 112 : 124,
                        child: _fullscreenLivePlayersHeader(
                          online: online,
                          active: active,
                          compact: compactWidth || compactHeight,
                        ),
                      ),
                      _ofHorizontalDivider(),
                    ],
                    Expanded(
                      child: _flagshipLiveSplit(
                        compact: compactHeight,
                        online: online,
                        active: active,
                        // В полноэкранном Live состав уже показан двумя рядами
                        // сверху, а в обычном desktop — быстрым списком слева.
                        showMonitorStrip: false,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  void _requestWorkspaceFullscreen(bool expanded) {
    if (widget.onWorkspaceFullscreenChanged == null) {
      if (expanded) _openLiveMapPro();
      return;
    }
    if (expanded) {
      setState(() {
        _monitorPlayersExpanded = false;
        _expandedMonitorDetailPlayerId = null;
        _liveViewShowSidePanel = true;
        _teamLivePanelJournal = false;
      });
    }
    widget.onWorkspaceFullscreenChanged!(expanded);
  }

