  Widget _fullscreenLivePlayerCard(
    TrackerPlayerOption player,
    int index, {
    required bool compact,
  }) {
    final online = _isPlayerOnlineLive(player.id);
    final metrics = _liveMetricsForPlayer(player);
    final gpsReady = _gpsChannelReadyForPlayer(player);
    final heart = _heartRateForPlayerId(player.id);
    final active = online || gpsReady || heart != null;
    final number = player.number ?? '${index + 1}';
    final focused = widget.selectedPlayer?.id == player.id;
    final distanceLabel = metrics.distanceM >= 1000
        ? '${(metrics.distanceM / 1000).toStringAsFixed(2)} км'
        : '${metrics.distanceM.toStringAsFixed(0)} м';
    final heartLabel = metrics.heartRateBpm == null
        ? '♥ —'
        : '♥ ${metrics.heartRateBpm}';

    return Material(
      color: Colors.transparent,
      child: _NoHoverTap(
        onTap: () => _focusMonitorPlayer(player),
        borderRadius: BorderRadius.circular(11),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 150),
          padding: EdgeInsets.symmetric(
            horizontal: compact ? 7 : 8,
            vertical: compact ? 5 : 6,
          ),
          decoration: BoxDecoration(
            color: focused ? _OF.greenSoftStrong : _OF.soft,
            borderRadius: BorderRadius.circular(11),
          ),
          child: Row(
            children: [
              Stack(
                clipBehavior: Clip.none,
                children: [
                  _playerAvatarCircle(
                    player: player,
                    radius: compact ? 14 : 15,
                    online: active,
                  ),
                  Positioned(
                    right: -4,
                    bottom: -4,
                    child: Container(
                      width: 16,
                      height: 16,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: focused ? _OF.green : Colors.white,
                        shape: BoxShape.circle,
                      ),
                      child: Text(
                        number,
                        maxLines: 1,
                        style: _OFText.body(
                          size: 7.1,
                          color: focused ? Colors.white : _OF.text,
                          weight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(width: 7),
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            _compactPlayerName(player.displayName ?? player.name),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: _OFText.title(
                              compact ? 8.8 : 9.4,
                              color: focused ? _OF.green : _OF.text,
                            ),
                          ),
                        ),
                        Container(
                          width: 6,
                          height: 6,
                          decoration: BoxDecoration(
                            color: online
                                ? _OF.green
                                : (gpsReady ? _OF.orange : _OF.muted2),
                            shape: BoxShape.circle,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 3),
                    Text(
                      'GPS · $distanceLabel · ${metrics.currentSpeedKmh.toStringAsFixed(1)}/${metrics.maxSpeedKmh.toStringAsFixed(1)} км/ч',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _OFText.body(
                        size: compact ? 7.4 : 8,
                        color: active ? _OF.muted : _OF.muted2,
                        weight: FontWeight.w500,
                      ),
                    ),
                    const SizedBox(height: 1),
                    Text(
                      '$heartLabel · S ${metrics.sprintCount} · нагрузка ${metrics.loadScore.toStringAsFixed(0)}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _OFText.body(
                        size: compact ? 7.2 : 7.8,
                        color: metrics.heartRateBpm == null
                            ? _OF.muted2
                            : _OF.text,
                        weight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _openAllLiveCardsFromSidebar() {
    if (_liveMapProExpanded) _closeLiveMapPro();
    final players = _livePlayerOptions()
        .where((player) => player.id > 0)
        .take(_maxMonitorPlayers)
        .toList(growable: false);
    setState(() {
      _monitorManualSelectionTouched = true;
      _monitorPlayerIds
        ..clear()
        ..addAll(players.map((player) => player.id));
      _monitorPlayersExpanded = true;
      _expandedMonitorDetailPlayerId = null;
      _teamLivePanelJournal = false;
      _showSelectedPlayerDetail = false;
      _liveViewShowSidePanel = true;
    });
    _persistMonitorSelection();
  }

  Widget _desktopLiveSidebar({
    required int online,
    required int active,
    required bool compact,
  }) {
    final players = _livePlayerOptions().where((player) => player.id > 0).toList();
    final journalEvents = _liveEvents.where((event) => event.timeMs > 0).length;
    final redEvents = _liveEvents
        .where((event) => event.timeMs > 0 && event.isRed)
        .length;
    final allCardsActive = _monitorPlayersExpanded;
    final journalActive = _teamLivePanelJournal && !_liveMapProExpanded;
    final hudActive = _liveMapProShowSpeed ||
        _liveMapProShowHeart ||
        _liveMapProShowLoad ||
        _liveMapProShowDistance ||
        _liveMapProShowSprints;
    final tacticalActive = _showTeamShapeConnections ||
        _liveMapProShowPassingNetwork ||
        _liveMapProShowTacticalLines ||
        _liveMapProShowOffsideGuide ||
        _liveMapProShowControlZones ||
        _liveMapProShowTeamCenter ||
        _liveMapProShowPitchZones;

    void showField() {
      if (_liveMapProExpanded) _closeLiveMapPro();
      setState(() {
        _monitorPlayersExpanded = false;
        _expandedMonitorDetailPlayerId = null;
        _teamLivePanelJournal = false;
        _showSelectedPlayerDetail = false;
        // Справа остаётся состав/оперативные данные — игроки уже доступны
        // здесь, поэтому отдельный быстрый список слева не нужен.
        _liveViewShowSidePanel = true;
      });
    }

    void showJournal() {
      if (_liveMapProExpanded) _closeLiveMapPro();
      setState(() {
        _monitorPlayersExpanded = false;
        _expandedMonitorDetailPlayerId = null;
        _teamLivePanelJournal = true;
        _showSelectedPlayerDetail = false;
        _liveViewShowSidePanel = true;
      });
    }

    void setGeoLayer(TrackerGeoBaseLayer layer) {
      setState(() {
        _liveGeoBaseLayer = layer;
        // 2D/3D — самостоятельный режим, поэтому смена подложки его не
        // сбрасывает. Tracker2GisMapLayer умеет перспективу и на геоподложке.
      });
    }

    void toggleHud() {
      setState(() {
        final next = !hudActive;
        _liveMapProShowSpeed = next;
        _liveMapProShowDistance = next;
        _liveMapProShowLoad = next;
        _liveMapProShowSprints = next;
        _liveMapProShowHeart = next && _hasTeamHeartRateOnline;
