  List<TrackerPlayerOption> _monitorCandidatePlayers() {
    final connected = _connectedPlayerOptions();
    final interestingIds = <int>{
      ...widget.connectedTeamPlayerIds,
      ..._boundTeamGpsPlayerIds(),
      ...connected.map((player) => player.id),
    };
    for (final session in _sessions) {
      if (!session.isOnline) continue;
      final playerId = _resolvedPlayerIdForSession(session);
      if (playerId != null && playerId > 0) interestingIds.add(playerId);
    }
    for (final entry in widget.heartRateByPlayerId.entries) {
      if (DateTime.now().difference(entry.value.measuredAt).inSeconds <= 35) {
        interestingIds.add(entry.key);
      }
    }
    final focusedId = widget.selectedPlayer?.id;
    final base = _livePlayerOptions()
        .where((player) =>
            _monitorPlayerIds.contains(player.id) ||
            focusedId == player.id ||
            interestingIds.contains(player.id) ||
            player.identityIds.any(interestingIds.contains))
        .toList(growable: false);
    final sorted = List<TrackerPlayerOption>.from(base);
    sorted.sort((a, b) {
      final aSelected = _monitorPlayerIds.contains(a.id) ? 1 : 0;
      final bSelected = _monitorPlayerIds.contains(b.id) ? 1 : 0;
      if (aSelected != bSelected) return bSelected.compareTo(aSelected);
      final aOnline = _isPlayerOnlineLive(a.id) ? 1 : 0;
      final bOnline = _isPlayerOnlineLive(b.id) ? 1 : 0;
      if (aOnline != bOnline) return bOnline.compareTo(aOnline);
      final loadCompare =
          _loadForPlayerId(b.id).compareTo(_loadForPlayerId(a.id));
      if (loadCompare != 0) return loadCompare;
      return (int.tryParse(a.number ?? '') ?? 9999)
          .compareTo(int.tryParse(b.number ?? '') ?? 9999);
    });
    return sorted;
  }

  Set<int> _boundTeamGpsPlayerIds() {
    final result = <int>{};
    for (final device in widget.savedDevices) {
      final playerId = device.playerId;
      if (playerId == null || playerId <= 0) continue;
      final text =
          '${device.deviceName} ${device.deviceUuid}'.trim().toLowerCase();
      final isHeart = text.contains('polar') ||
          text.contains('h10') ||
          text.contains('heart') ||
          text.contains('hrm');
      final isPhoneOrBox = text.contains('iphone') ||
          text.contains('android') ||
          text.contains('телефон') ||
          text.contains('phone') ||
          text.contains('sberbox');
      final upperName = device.deviceName.trim().toUpperCase();
      final isTracker = upperName.startsWith(r'$ATP') ||
          upperName.startsWith(r'$ACT') ||
          upperName.startsWith(r'$GPS') ||
          text.contains('gps');
      if (!isHeart && !isPhoneOrBox && isTracker) {
        final resolved = widget.players
            .where((player) =>
                player.id == playerId || player.identityIds.contains(playerId))
            .toList(growable: false);
        result.add(resolved.isEmpty ? playerId : resolved.first.id);
      }
    }
    return result;
  }

  List<TrackerPlayerOption> _monitorPlayersForGrid() {
    final candidates = _monitorCandidatePlayers();
    if (candidates.isEmpty) return const <TrackerPlayerOption>[];
    final byId = <int, TrackerPlayerOption>{
      for (final p in candidates) p.id: p
    };
    final manual = _monitorPlayerIds
        .where((id) => byId.containsKey(id))
        .map((id) => byId[id]!)
        .toList(growable: false);
    if (_monitorManualSelectionTouched)
      return manual.take(_maxMonitorPlayers).toList(growable: false);
    if (manual.isNotEmpty)
      return manual.take(_maxMonitorPlayers).toList(growable: false);
    final connected = candidates
        .where((p) =>
            _isPlayerOnlineLive(p.id) ||
            _heartRateForPlayerId(p.id) != null ||
            (_localTrackForPlayer(p.id)?.points.isNotEmpty ?? false))
        .take(_maxMonitorPlayers)
        .toList(growable: false);
    if (connected.isNotEmpty) return connected;
    final gpsReady = candidates
        .where((player) =>
            widget.connectedTeamPlayerIds.contains(player.id) ||
            player.identityIds.any(widget.connectedTeamPlayerIds.contains))
        .take(_maxMonitorPlayers)
        .toList(growable: false);
    if (gpsReady.isNotEmpty) return gpsReady;
    if (widget.selectedPlayer != null &&
        byId.containsKey(widget.selectedPlayer!.id))
      return <TrackerPlayerOption>[widget.selectedPlayer!];
    return candidates.take(_maxMonitorPlayers).toList(growable: false);
  }

  void _toggleMonitorPlayer(TrackerPlayerOption player) {
    if (player.id <= 0) return;
    final currentGridIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    setState(() {
      if (!_monitorManualSelectionTouched && currentGridIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentGridIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;
      if (_monitorPlayerIds.contains(player.id)) {
        _monitorPlayerIds.remove(player.id);
        _monitorMapPlayerIds.remove(player.id);
        return;
      }
      if (_monitorPlayerIds.length >= _maxMonitorPlayers) {
        final first = _monitorPlayerIds.first;
        _monitorPlayerIds.remove(first);
        _monitorMapPlayerIds.remove(first);
      }
      _monitorPlayerIds.add(player.id);
    });
    _persistMonitorSelection();
  }

  void _removeMonitorPlayer(TrackerPlayerOption player) {
    if (player.id <= 0) return;
    final currentGridIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    setState(() {
      if (!_monitorManualSelectionTouched && currentGridIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentGridIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;
      _monitorPlayerIds.remove(player.id);
      _monitorMapPlayerIds.remove(player.id);
    });
    _persistMonitorSelection();
  }

  void _toggleMonitorPlayerMap(TrackerPlayerOption player) {
    _openPlayerOnSidePanel(player,
        mode: _liveSidePanelMode == 'map' ? 'map' : _liveSidePanelMode);
  }

  void _clearMonitorPlayers() {
    setState(() {
      _monitorManualSelectionTouched = true;
      _monitorPlayerIds.clear();
      _monitorMapPlayerIds.clear();
    });
    _persistMonitorSelection();
  }

  bool _isPlayerInMonitorGrid(int? playerId) {
    if (playerId == null || playerId <= 0) return false;
    return _monitorPlayersForGrid().any((p) => p.id == playerId);
  }

  List<TrackerPlayerOption> _sidePanelPlayers() {
    final grid = _monitorPlayersForGrid();
    final byId = <int, TrackerPlayerOption>{
      for (final p in _monitorCandidatePlayers()) p.id: p
    };
    final selected = _monitorMapPlayerIds
        .where((id) => byId.containsKey(id))
        .map((id) => byId[id]!)
        .toList(growable: false);
    if (selected.isNotEmpty)
      return selected.take(_maxMonitorPlayers).toList(growable: false);
    return grid.take(_maxMonitorPlayers).toList(growable: false);
  }

  List<_RuntimeTrack> _rawSidePanelTracks() {
    if (!_liveTelemetryActive) return const <_RuntimeTrack>[];
    final players = _sidePanelPlayers();
    final tracks = <_RuntimeTrack>[];
    for (final player in players) {
      final track = _displayTrackForPlayer(player);
      if (track != null && track.points.isNotEmpty) tracks.add(track);
    }
    if (tracks.isNotEmpty) return tracks;
    if (_monitorMapPlayerIds.isNotEmpty) return const <_RuntimeTrack>[];
    return _tracks.values
        .where((track) => track.points.isNotEmpty)
        .toList(growable: false);
  }

  List<_RuntimeTrack> _sidePanelTracks() {
    final liveTracks = _rawSidePanelTracks();
    final cutoff = _liveReviewTeamTimeMs;
    if (cutoff == null || cutoff <= 0) return liveTracks;

    final snapshots = <_RuntimeTrack>[];
    for (final track in liveTracks) {
      final snapshot = _teamReviewTrackSnapshot(track, cutoff);
      if (snapshot != null && snapshot.points.isNotEmpty) snapshots.add(snapshot);
    }

    // Если на этом устройстве нет локальной истории нужного игрока, но PHP
    // вернул координату выбранного события, всё равно показываем этот момент.
    final event = _selectedLiveEvent();
    if (event != null &&
        event.timeMs > 0 &&
        event.latitude != null &&
        event.longitude != null) {
      final eventPlayerId = event.playerId;
      final alreadyVisible = snapshots.any((track) {
        final player = _phonePlayerForTrack(track);
        return eventPlayerId != null &&
            player != null &&
            (player.id == eventPlayerId || player.identityIds.contains(eventPlayerId));
      });
      if (!alreadyVisible && eventPlayerId != null) {
        TrackerPlayerOption? player;
        for (final candidate in _monitorCandidatePlayers()) {
          if (candidate.id == eventPlayerId ||
              candidate.identityIds.contains(eventPlayerId)) {
            player = candidate;
            break;
          }
        }
        if (player != null) {
          final synthetic = _RuntimeTrack(
            key: 'TEAM-REVIEW-${player.id}-${event.timeMs}',
            playerName: player.name,
            deviceName: 'Live event history',
            avatar: player.avatar,
          );
          synthetic.points.add(_RuntimePoint(
            lat: event.latitude!,
            lon: event.longitude!,
            timeMs: event.timeMs,
            speedKmh: _safeLiveSpeed(event.speedKmh),
            rawSpeedKmh: _safeLiveSpeed(event.speedKmh),
            distanceDeltaM: 0,
            packetType: 'team-live-event-review',
          ));
          synthetic.speedKmh = _safeLiveSpeed(event.speedKmh);
          synthetic.rawSpeedKmh = synthetic.speedKmh;
          synthetic.maxSpeedKmh = synthetic.speedKmh;
          snapshots.add(synthetic);
        }
      }
    }
    return snapshots;
  }

  String _sidePanelSelectionLabel() {
    final players = _sidePanelPlayers();
    if (_monitorMapPlayerIds.isEmpty) return 'общая команда';
    if (players.length == 1) return _compactPlayerName(players.first.name);
    return '${players.length} игрок.';
  }

  void _openPlayerOnSidePanel(TrackerPlayerOption player,
      {String mode = 'map'}) {
    if (player.id <= 0) return;
    final currentGridIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    setState(() {
      if (!_monitorManualSelectionTouched && currentGridIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentGridIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;
      if (!_monitorPlayerIds.contains(player.id)) {
        if (_monitorPlayerIds.length >= _maxMonitorPlayers) {
          final first = _monitorPlayerIds.first;
          _monitorPlayerIds.remove(first);
          _monitorMapPlayerIds.remove(first);
        }
        _monitorPlayerIds.add(player.id);
      }
      _monitorMapPlayerIds.add(player.id);
      _teamFieldPanelExpanded = true;
      _liveSidePanelMode = mode;
    });
    _persistMonitorSelection();
  }

  void _togglePlayerOnSidePanel(TrackerPlayerOption player,
      {String mode = 'map'}) {
    if (player.id <= 0) return;
    final currentGridIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    setState(() {
      if (!_monitorManualSelectionTouched && currentGridIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentGridIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;
      if (!_monitorPlayerIds.contains(player.id)) {
        if (_monitorPlayerIds.length >= _maxMonitorPlayers) {
          final first = _monitorPlayerIds.first;
          _monitorPlayerIds.remove(first);
          _monitorMapPlayerIds.remove(first);
        }
        _monitorPlayerIds.add(player.id);
      }
      if (_monitorMapPlayerIds.contains(player.id)) {
        _monitorMapPlayerIds.remove(player.id);
      } else {
        _monitorMapPlayerIds.add(player.id);
      }
      _teamFieldPanelExpanded = true;
      _liveSidePanelMode = mode;
    });
    _persistMonitorSelection();
  }

  void _captureHeartRateSamples() {
    if (widget.heartRateByPlayerId.isEmpty) return;
    for (final entry in widget.heartRateByPlayerId.entries) {
      final sample = entry.value;
      final list =
          _liveHrHistoryByPlayer.putIfAbsent(entry.key, () => <_LiveHrPoint>[]);
      final ms = sample.measuredAt.millisecondsSinceEpoch;
      if (list.isNotEmpty &&
          list.last.timeMs == ms &&
          list.last.bpm == sample.bpm) continue;
      list.add(_LiveHrPoint(timeMs: ms, bpm: sample.bpm));
      if (list.length > 360) list.removeRange(0, list.length - 360);
    }
  }

  int? _playerBleRssi(TrackerPlayerOption player) {
    final info = widget.ble.connectedInfo;
    if (info == null) return null;
    final linked = _deviceForPlayer(player.id);
    if (linked == null) return info.rssi == 0 ? null : info.rssi;
    final uuid = linked.deviceUuid.toLowerCase();
    final name = linked.deviceName.toLowerCase();
    final infoId = info.id.toLowerCase();
    final infoName = info.name.toLowerCase();
    if (uuid.isNotEmpty && infoId.contains(uuid))
      return info.rssi == 0 ? null : info.rssi;
    if (name.isNotEmpty && infoName.contains(name))
      return info.rssi == 0 ? null : info.rssi;
    return null;
  }

  TrackerDeviceModel? _deviceForPlayer(int? playerId) {
    if (playerId == null) return null;
    final player = _playerById(playerId);
    final acceptedIds = <int>{
      playerId,
      if (player != null) ...player.identityIds,
    };
    for (final d in widget.savedDevices) {
      if (d.playerId == null || !acceptedIds.contains(d.playerId)) continue;
      final text = '${d.deviceName} ${d.deviceUuid}'.trim().toLowerCase();
      final isHeart = text.contains('polar') ||
          text.contains('h10') ||
          text.contains('heart') ||
          text.contains('hrm');
      final upperName = d.deviceName.trim().toUpperCase();
      final isTeamGps = upperName.startsWith(r'$ATP') ||
          upperName.startsWith(r'$ACT') ||
          upperName.startsWith(r'$GPS') ||
          text.contains('gps');
      if (!isHeart && isTeamGps) return d;
    }
    return null;
  }

  TrackerDeviceModel? _heartDeviceForPlayer(int? playerId) {
    if (playerId == null) return null;
    final player = _playerById(playerId);
    final acceptedIds = <int>{
      playerId,
      if (player != null) ...player.identityIds,
    };
    for (final d in widget.savedDevices) {
      if (d.playerId == null || !acceptedIds.contains(d.playerId)) continue;
      final text = '${d.deviceName} ${d.deviceUuid}'.trim().toLowerCase();
      final isHeart = text.contains('polar') ||
          text.contains('h10') ||
          text.contains('heart') ||
          text.contains('hrm');
      if (isHeart) return d;
    }
    return null;
  }

  bool _gpsChannelReadyForPlayer(TrackerPlayerOption player) {
    return widget.connectedTeamPlayerIds.contains(player.id) ||
        player.identityIds.any(widget.connectedTeamPlayerIds.contains);
  }

  String _signalLabelForPlayer(TrackerPlayerOption player) {
    if (_gpsChannelReadyForPlayer(player)) return 'BLE готов';
    final rssi = _playerBleRssi(player);
    if (rssi != null) {
      if (rssi >= -65) return 'сигнал высокий';
      if (rssi >= -82) return 'сигнал норм';
      return 'слабый сигнал';
    }
    final device = _deviceForPlayer(player.id);
    if (device?.isNearby == true) return 'рядом';
    if (_isPlayerOnlineLive(player.id) ||
        _heartRateForPlayerId(player.id) != null) return 'online';
    return 'offline';
  }

  Color _signalColorForPlayer(TrackerPlayerOption player) {
    final label = _signalLabelForPlayer(player);
    if (label.contains('высок') ||
        label.contains('норм') ||
        label == 'online' ||
        label == 'рядом' ||
        label == 'BLE готов') {
      return _OF.green;
    }
    if (label.contains('слаб')) return _OF.orange;
    return _OF.muted2;
  }

  TrackerPlayerOption? _expandedMonitorDetailPlayer() {
    final playerId = _expandedMonitorDetailPlayerId;
    if (playerId == null || playerId <= 0) return null;
    for (final player in _monitorCandidatePlayers()) {
      if (player.id == playerId || player.identityIds.contains(playerId)) {
        return player;
      }
    }
    for (final player in widget.players) {
      if (player.id == playerId || player.identityIds.contains(playerId)) {
        return player;
      }
    }
    return null;
  }

  void _openExpandedMonitorPlayerDetails(TrackerPlayerOption player) {
    if (player.id <= 0) return;
    // Это только локальный фокус интерфейса. Не вызываем onSelectPlayer,
    // не пересоздаём BLE-координатор и не меняем командную Live-сессию.
    // Обычное «Подробнее» всегда открывается на текущем LIVE.
    setState(() {
      _expandedMonitorDetailPlayerId = player.id;
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _liveReviewTeamTimeMs = null;
      _selectedLiveEventId = null;
    });
  }

  void _closeExpandedMonitorPlayerDetails() {
    if (_expandedMonitorDetailPlayerId == null) return;
    setState(() {
      _expandedMonitorDetailPlayerId = null;
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _selectedLiveEventId = null;
    });
  }

