  Widget _tabletExpandedMonitorPlayersGrid({required bool compact}) {
    // «Все карточки» снова открываются как отдельное полноразмерное окно,
    // как в прежней версии. Слева остаётся сетка карточек игроков,
    // справа — постоянная Live-лента моментов/предупреждений.
    // Если нажато «Подробнее»/момент — внутри того же полноэкранного слоя
    // показываем подробный экран выбранного игрока.
    final detailPlayer = _expandedMonitorDetailPlayer();
    if (detailPlayer != null) {
      return _tabletExpandedMonitorPlayerDetails(
        detailPlayer,
        compact: compact,
      );
    }

    final players = _monitorPlayersForGrid();
    final monitoredIds = players.map((player) => player.id).toSet();
    final events = _monitorLiveEvents();
    final connectedCount = players
        .where((player) =>
            _isPlayerOnlineLive(player.id) ||
            _heartRateForPlayerId(player.id) != null ||
            (_localTrackForPlayer(player.id)?.points.isNotEmpty ?? false))
        .length;
    final redCount = events.where((event) => event.isRed).length;

    return Container(
      key: const ValueKey<String>('monitor_players_expanded_cards_moments'),
      color: Colors.white,
      padding: EdgeInsets.fromLTRB(
        compact ? 8 : 10,
        6,
        compact ? 8 : 10,
        8,
      ),
      child: Column(
        children: [
          SizedBox(
            height: 40,
            child: Row(
              children: [
                Container(
                  width: 30,
                  height: 30,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: _OF.greenSoftStrong,
                    borderRadius: BorderRadius.circular(9),
                  ),
                  child: const Icon(
                    Icons.grid_view_rounded,
                    color: _OF.green,
                    size: 16,
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'Команда Live',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: _OF.text,
                          fontSize: AppTypography.bodySize,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      Text(
                        '${players.length} выбрано · $connectedCount с Live-данными · $redCount красных моментов',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: redCount > 0 ? _OF.red : _OF.green,
                          fontSize: AppTypography.badgeSize,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ),
                ),
                _monitorCardsToggleButton(compact: true),
                const SizedBox(width: 5),
                _NoHoverTap(
                  onTap: _clearMonitorPlayers,
                  borderRadius: BorderRadius.circular(9),
                  child: Container(
                    width: 30,
                    height: 30,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: _OF.soft,
                      borderRadius: BorderRadius.circular(9),
                    ),
                    child: const Icon(
                      Icons.layers_clear_rounded,
                      color: _OF.muted2,
                      size: 16,
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 6),
          Expanded(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final sideWidth = math.min(
                  compact ? 280.0 : 340.0,
                  math.max(248.0, constraints.maxWidth * .28),
                );

                return Row(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
