  Widget _expandedLiveMomentStats(
    List<TrackerLiveEventModel> events, {
    required bool compact,
  }) {
    int countType(String type) =>
        events.where((event) => event.type == type).length;
    final red = events.where((event) => event.isRed).length;
    final stats = <({String label, int value, Color color})>[
      (label: 'Красные', value: red, color: _OF.red),
      (label: 'GPS', value: countType('gps_warning'), color: _OF.red),
      (label: 'Спринты', value: countType('sprint'), color: _OF.orange),
      (label: 'Ускор.', value: countType('acceleration'), color: _OF.orange),
      (label: 'Торм.', value: countType('deceleration'), color: _OF.orange),
      (label: '30+ км/ч', value: countType('high_speed'), color: _OF.red),
    ];

    return SizedBox(
      height: compact ? 28 : 30,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        padding: EdgeInsets.zero,
        itemCount: stats.length,
        separatorBuilder: (_, __) => const SizedBox(width: 4),
        itemBuilder: (_, index) {
          final item = stats[index];
          return Container(
            constraints: BoxConstraints(minWidth: compact ? 58 : 64),
            padding: const EdgeInsets.symmetric(horizontal: 7),
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: item.color.withOpacity(item.value > 0 ? .08 : .035),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(
                color: item.value > 0
                    ? item.color.withOpacity(.12)
                    : Colors.transparent,
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  item.label,
                  style: const TextStyle(
                    color: _OF.muted2,
                    fontSize: 7.3,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(width: 4),
                Text(
                  '${item.value}',
                  style: TextStyle(
                    color: item.value > 0 ? item.color : _OF.muted2,
                    fontSize: 8.4,
                    fontWeight: FontWeight.w900,
                    fontFeatures: const [FontFeature.tabularFigures()],
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

