  Widget _expandedLivePlayerRow(
    TrackerPlayerOption player,
    int index, {
    required bool compact,
  }) {
    final metrics = _liveMetricsForPlayer(player);
    final online = _isPlayerOnlineLive(player.id);
    final gpsReady = _gpsChannelReadyForPlayer(player);
    final focused = widget.selectedPlayer?.id == player.id;
    final loadColor = _loadMarkColor(
      metrics.loadScore,
      heartRateBpm: metrics.heartRateBpm,
    );

    return _NoHoverTap(
      onTap: () => _focusMonitorPlayer(player),
      borderRadius: BorderRadius.circular(12),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 160),
        padding: EdgeInsets.fromLTRB(
          compact ? 8 : 10,
          compact ? 7 : 8,
          compact ? 8 : 10,
          compact ? 7 : 8,
        ),
        decoration: BoxDecoration(
          color: focused ? _OF.greenSoftStrong : _OF.soft,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: focused
                ? _OF.green.withOpacity(.18)
                : Colors.transparent,
          ),
        ),
        child: Column(
          children: [
            Row(
              children: [
                _playerAvatarCircle(
                  player: player,
                  radius: compact ? 17 : 19,
                  online: online || gpsReady,
                ),
                const SizedBox(width: 8),
                Container(
                  width: 22,
                  height: 22,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: focused ? _OF.green : Colors.white,
                    shape: BoxShape.circle,
                  ),
                  child: Text(
                    player.number ?? '${index + 1}',
                    style: TextStyle(
                      color: focused ? Colors.white : _OF.graphite,
                      fontSize: AppTypography.badgeSize,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
                const SizedBox(width: 7),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        _compactPlayerName(player.displayName ?? player.name),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: focused ? _OF.green : _OF.text,
                          fontSize: compact ? 10.2 : 10.8,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      Text(
                        online
                            ? 'online · Live-данные обновляются'
                            : (gpsReady
                                ? 'GPS готов · ожидаем пакет'
                                : 'ожидает подключения'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: online || gpsReady ? _OF.green : _OF.muted2,
