  void _focusMonitorPlayer(TrackerPlayerOption player) {
    if (player.id <= 0) return;
    if (!_running) _blockServerAutoRestoreAfterPlayerPick = true;
    final currentIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    setState(() {
      if (!_monitorManualSelectionTouched && currentIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;
      if (!_monitorPlayerIds.contains(player.id)) {
        if (_monitorPlayerIds.length >= _maxMonitorPlayers) {
          final first = _monitorPlayerIds.first;
          _monitorPlayerIds.remove(first);
          _monitorMapPlayerIds.remove(first);
        }
        _monitorPlayerIds.add(player.id);
      }
      _showTeamOnFocusedField = false;
      _showSelectedPlayerDetail = true;
      _liveViewShowSidePanel = true;
    });
    _persistMonitorSelection();
    widget.onSelectPlayer?.call(player);
  }

  void _setFocusedFieldScope({required bool team}) {
    if (_showTeamOnFocusedField == team) return;
    setState(() {
      _showTeamOnFocusedField = team;
      if (team && _monitorMapPlayerIds.isEmpty) {
        final focusedId = widget.selectedPlayer?.id;
        if (focusedId != null && focusedId > 0) {
          _monitorMapPlayerIds.add(focusedId);
        }
      }
    });
  }

  void _toggleFocusedTeamPlayer(TrackerPlayerOption player) {
    if (player.id <= 0) return;
    if (!_running) _blockServerAutoRestoreAfterPlayerPick = true;

    final currentIds =
        _monitorPlayersForGrid().map((p) => p.id).toList(growable: false);
    final wasSelected = _monitorMapPlayerIds.contains(player.id);
    TrackerPlayerOption? nextFocus;

    setState(() {
      if (!_monitorManualSelectionTouched && currentIds.isNotEmpty) {
        _monitorPlayerIds
          ..clear()
          ..addAll(currentIds.take(_maxMonitorPlayers));
      }
      _monitorManualSelectionTouched = true;

      if (!_monitorPlayerIds.contains(player.id)) {
        if (_monitorPlayerIds.length >= _maxMonitorPlayers) {
          final first = _monitorPlayerIds.first;
          _monitorPlayerIds.remove(first);
          _monitorMapPlayerIds.remove(first);
        }
        _monitorPlayerIds.add(player.id);
      }

      // На поле всегда остаётся хотя бы одна отмеченная точка.
      if (wasSelected && _monitorMapPlayerIds.length > 1) {
        _monitorMapPlayerIds.remove(player.id);
        if (widget.selectedPlayer?.id == player.id) {
          final remainingId = _monitorMapPlayerIds.first;
          for (final candidate in _monitorCandidatePlayers()) {
            if (candidate.id == remainingId) {
              nextFocus = candidate;
              break;
            }
          }
        }
      } else {
        _monitorMapPlayerIds.add(player.id);
        nextFocus = player;
      }
    });
    _persistMonitorSelection();

// Фокус определяет только данные справа. Командная сессия, BLE и остальные
// отмеченные игроки не переключаются и не останавливаются.
    if (nextFocus != null) widget.onSelectPlayer?.call(nextFocus!);
  }

  Widget _tabletMonitorPlayerChip(
    TrackerPlayerOption player,
    int index, {
    required bool monitored,
    required bool focused,
    required bool compact,
    bool expandedCard = false,
  }) {
    final online = _isPlayerOnlineLive(player.id);
    final rawHeartRate = _heartRateForPlayerId(player.id);
    final local = _localTrackForPlayer(player.id);
    final metrics = _liveMetricsForPlayer(player);
    final heartRate = _liveTelemetryActive ? rawHeartRate : null;
    final hasTrack = _liveTelemetryActive && (local?.points.isNotEmpty ?? false);
    final gpsReady = _gpsChannelReadyForPlayer(player);
    final active = online || heartRate != null || hasTrack || gpsReady;
    final number = player.number ?? '${index + 1}';
    final loadColor = _loadMarkColor(
      metrics.loadScore,
      heartRateBpm: metrics.heartRateBpm,
    );
    final redWarnings = metrics.redWarningsCount;
    final teamSelected =
        _showTeamOnFocusedField && _monitorMapPlayerIds.contains(player.id);

    return Material(
      color: Colors.transparent,
      borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
      child: _NoHoverTap(
        onTap: () => _showTeamOnFocusedField
            ? _toggleFocusedTeamPlayer(player)
            : _focusMonitorPlayer(player),
        onLongPress: () => _selectPlayerForAnalytics(player),
        borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 160),
          width: expandedCard ? double.infinity : (compact ? 184 : 218),
          padding: EdgeInsets.fromLTRB(
            compact ? 7 : 9,
            expandedCard ? 9 : 7,
            compact ? 7 : 9,
            expandedCard ? 8 : 7,
          ),
          decoration: BoxDecoration(
            color: teamSelected || focused
                ? _OF.greenSoftStrong
                : (monitored ? _OF.soft : Colors.white),
            borderRadius: BorderRadius.circular(12),
            border: expandedCard && redWarnings > 0
                ? Border.all(color: _OF.red.withOpacity(.12))
                : null,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Stack(
                    clipBehavior: Clip.none,
                    children: [
                      _playerAvatarCircle(
                        player: player,
                        radius: expandedCard
                            ? (compact ? 18 : 20)
                            : (compact ? 16 : 18),
                        online: active || focused,
                      ),
                      Positioned(
                        right: -4,
                        bottom: -4,
                        child: Container(
                          width: 18,
                          height: 18,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: focused ? _OF.green : _OF.soft,
                            shape: BoxShape.circle,
                          ),
                          child: Text(
                            number,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              color: focused ? Colors.white : _OF.graphite,
                              fontSize: AppTypography.menuGroupSize,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          _compactPlayerName(player.displayName ?? player.name),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            color: teamSelected || focused
                                ? _OF.green
                                : _OF.text,
                            fontSize: expandedCard
                                ? (compact ? 10.5 : 11.2)
                                : (compact ? 9.9 : 10.6),
                            fontWeight: FontWeight.w800,
                            letterSpacing: -.08,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          _liveTelemetryActive && online
