  List<TrackerPlayerOption> _focusedTeamFieldPlayers(
    TrackerPlayerOption focusedPlayer,
  ) {
    final candidates = _monitorCandidatePlayers();
    if (_monitorMapPlayerIds.isEmpty) {
      return <TrackerPlayerOption>[focusedPlayer];
    }

    final selected = candidates
        .where((candidate) => _monitorMapPlayerIds.contains(candidate.id))
        .take(_maxMonitorPlayers)
        .toList(growable: false);
    return selected.isEmpty ? <TrackerPlayerOption>[focusedPlayer] : selected;
  }

  List<_RuntimeTrack> _focusedFieldTracks(TrackerPlayerOption player) {
    final focused =
        _reviewTrackSnapshot(player, _displayTrackForPlayer(player));
    if (!_showTeamOnFocusedField) {
      return focused == null
          ? const <_RuntimeTrack>[]
          : <_RuntimeTrack>[focused];
    }

    final result = <_RuntimeTrack>[];
    for (final candidate in _focusedTeamFieldPlayers(player)) {
      final track = _reviewTrackSnapshot(
        candidate,
        _displayTrackForPlayer(candidate),
      );
      if (track != null && track.points.isNotEmpty) result.add(track);
    }
    return result;
  }

