  List<_LiveHrPoint> _focusedHeartRateHistory(
    TrackerPlayerOption player,
    HeartRateSample? current,
  ) {
    final history = List<_LiveHrPoint>.from(
      _liveHrHistoryByPlayer[player.id] ?? const <_LiveHrPoint>[],
    );
    if (current != null) {
      final point = _LiveHrPoint(
        timeMs: current.measuredAt.millisecondsSinceEpoch,
        bpm: current.bpm,
      );
      if (history.isEmpty ||
          history.last.timeMs != point.timeMs ||
          history.last.bpm != point.bpm) {
        history.add(point);
      }
    }
    return history.length <= 180
        ? history
        : history.sublist(history.length - 180);
  }

  List<_LiveMetricPoint> _focusedLoadTimeline(_RuntimeTrack? track) {
    if (track == null || track.points.length < 2) {
      return const <_LiveMetricPoint>[];
    }
    final result = <_LiveMetricPoint>[];
    for (var i = 1; i < track.points.length; i++) {
      final point = track.points[i];
      final previous = track.points[i - 1];
      if (!point.acceptedForMetrics) continue;
      final dt = math.max(
        .75,
        (point.timeMs - previous.timeMs) / 1000.0,
      );
      final acceleration =
          (((point.speedKmh - previous.speedKmh) / 3.6) / dt).abs();
      final speedPart =
          (point.speedKmh / 24.0).clamp(0.0, 1.0).toDouble() * 55.0;
      final distancePart =
          (point.distanceDeltaM / 6.0).clamp(0.0, 1.0).toDouble() * 20.0;
      final mechanicalPart =
          (acceleration / 3.0).clamp(0.0, 1.0).toDouble() * 25.0;
      final intensity =
          (speedPart + distancePart + mechanicalPart).clamp(0.0, 100.0);
      result.add(
        _LiveMetricPoint(
          timeMs: point.timeMs,
          value: intensity.toDouble(),
        ),
      );
    }
    return result.length <= 180 ? result : result.sublist(result.length - 180);
  }

  Widget _focusedTeamDataPanel(
    TrackerPlayerOption focusedPlayer, {
    required bool compact,
  }) {
    final players = _focusedTeamFieldPlayers(focusedPlayer);
    final now = DateTime.now();
    final freshHeartByPlayer = <int, HeartRateSample>{};
    final allHeartValues = <int>[];
    final heartSeries = <_LiveMetricSeries>[];
    final speedSeries = <_LiveMetricSeries>[];
    final gpsPlayerIds = <int>{};
    final onlinePlayerIds = <int>{};
    final loadByPlayer = <int, double>{};

    var totalDistance = 0.0;
    var totalHir = 0.0;
    var totalSprint = 0.0;
    var totalAccel = 0;
    var totalDecel = 0;
    var durationSec = 0;
    final currentSpeeds = <double>[];
    final maxSpeeds = <double>[];

    for (var i = 0; i < players.length; i++) {
      final player = players[i];
      if (_isPlayerOnlineLive(player.id)) onlinePlayerIds.add(player.id);

      final heart = _heartRateForPlayerId(player.id);
      final heartAge =
          heart == null ? 999 : now.difference(heart.measuredAt).inSeconds;
      if (heart != null && heartAge >= 0 && heartAge <= 35) {
        freshHeartByPlayer[player.id] = heart;
      }
      final history = _focusedHeartRateHistory(player, heart);
      allHeartValues.addAll(
        history.map((point) => point.bpm).where((bpm) => bpm > 0),
      );
      if (history.isNotEmpty) {
        heartSeries.add(
          _LiveMetricSeries(
            label: _compactPlayerName(player.displayName ?? player.name),
            color: _chartColor(i),
            points: history
                .map(
                  (point) => _LiveMetricPoint(
                    timeMs: point.timeMs,
                    value: point.bpm.toDouble(),
                  ),
                )
                .toList(growable: false),
          ),
        );
      }

      final local = _localTrackForPlayer(player.id);
      final session = _sessionForPlayer(player.id);
      final track = _displayTrackForPlayer(player);
      if (track != null && track.points.isNotEmpty) {
        gpsPlayerIds.add(player.id);
        speedSeries.add(
          _LiveMetricSeries(
            label: _compactPlayerName(player.displayName ?? player.name),
            color: _chartColor(i),
            points: track.points
                .map(
                  (point) => _LiveMetricPoint(
                    timeMs: point.timeMs,
                    value: _safeLiveSpeed(point.speedKmh),
                  ),
                )
                .toList(growable: false),
          ),
        );
      }

      final playerDistance = _safeLiveDistance(
        math
            .max(
              session?.totalDistanceM ?? 0.0,
              local?.totalDistanceM ?? 0.0,
            )
            .toDouble(),
        durationSec: math
            .max(
              session?.durationSec ?? 0,
              local?.durationSec ?? 0,
            )
            .toInt(),
      );
      final currentSpeed = _currentLiveSpeed(
        local: local,
        serverSpeed: session?.speedKmh ?? 0.0,
      );
      final playerMaxSpeed = _safeLiveSpeed(
        math
            .max(
              session?.maxSpeedKmh ?? 0.0,
              local?.maxSpeedKmh ?? 0.0,
            )
            .toDouble(),
      );
      final load = math
          .max(
            session?.loadScore ?? 0.0,
            local?.loadScore ?? 0.0,
          )
          .toDouble();

      if (gpsPlayerIds.contains(player.id)) {
        currentSpeeds.add(currentSpeed);
        maxSpeeds.add(playerMaxSpeed);
        loadByPlayer[player.id] = load;
      }
      totalDistance += playerDistance;
      totalHir += math
          .max(
            session?.hirDistanceM ?? 0.0,
            local?.hirDistanceM ?? 0.0,
          )
          .toDouble();
      totalSprint += math
          .max(
            session?.sprintDistanceM ?? 0.0,
            local?.sprintDistanceM ?? 0.0,
          )
          .toDouble();
      totalAccel += math
          .max(
            session?.accelCount ?? 0,
            local?.accelCount ?? 0,
          )
          .toInt();
      totalDecel += math
          .max(
            session?.decelCount ?? 0,
            local?.decelCount ?? 0,
          )
          .toInt();
      durationSec = math.max(
        durationSec,
        math
            .max(
              session?.durationSec ?? 0,
              local?.durationSec ?? 0,
            )
            .toInt(),
      );
    }

    final currentHeartValues = freshHeartByPlayer.values
        .map((sample) => sample.bpm)
        .toList(growable: false);
    final currentHeartAvg = currentHeartValues.isEmpty
        ? 0
        : (currentHeartValues.fold<int>(0, (sum, bpm) => sum + bpm) /
                currentHeartValues.length)
            .round();
    final historyHeartAvg = allHeartValues.isEmpty
        ? 0
        : (allHeartValues.fold<int>(0, (sum, bpm) => sum + bpm) /
                allHeartValues.length)
            .round();
    final maxHeart =
        allHeartValues.isEmpty ? 0 : allHeartValues.reduce(math.max);
    final avgSpeed = currentSpeeds.isEmpty
        ? 0.0
        : currentSpeeds.fold<double>(0, (sum, speed) => sum + speed) /
            currentSpeeds.length;
    final maxSpeed = maxSpeeds.isEmpty
        ? 0.0
        : maxSpeeds.fold<double>(0, (value, speed) => math.max(value, speed));
    final loadValues = loadByPlayer.values.toList(growable: false);
    final avgLoad = loadValues.isEmpty
        ? 0.0
        : loadValues.fold<double>(0, (sum, load) => sum + load) /
            loadValues.length;
    final peakLoad = loadValues.isEmpty
        ? 0.0
        : loadValues.fold<double>(0, (value, load) => math.max(value, load));
    final statusColor = _focusedTeamLoadColor(
      peakLoad: peakLoad,
      maxHeart: maxHeart,
    );
    final statusLabel = _focusedTeamLoadLabel(
      averageLoad: avgLoad,
      peakLoad: peakLoad,
      averageHeart: currentHeartAvg,
      maxHeart: maxHeart,
    );

    return _ofPanel(
      title: 'Команда · пульс и нагрузка',
      subtitle:
          '${players.length} выбрано · GPS ${gpsPlayerIds.length}/${players.length} · Polar ${freshHeartByPlayer.length}/${players.length}',
      actions: [
        Container(
          height: 24,
          padding: const EdgeInsets.symmetric(horizontal: 8),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: statusColor.withOpacity(.10),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Text(
            statusLabel,
            style: _OFText.button(
              color: statusColor,
              size: 9.2,
              weight: FontWeight.w700,
            ),
          ),
        ),
      ],
      child: Padding(
        padding: EdgeInsets.all(compact ? 7 : 9),
        child: Column(
          children: [
            _focusedTeamCollectionBanner(
              selectedCount: players.length,
              onlineCount: onlinePlayerIds.length,
              gpsCount: gpsPlayerIds.length,
              polarCount: freshHeartByPlayer.length,
              dense: compact,
            ),
            SizedBox(height: compact ? 4 : 7),
            Row(
              children: [
                Expanded(
                  child: _focusedHeartMetric(
                    'ЧСС сейчас',
                    currentHeartAvg <= 0 ? '—' : '$currentHeartAvg',
                    'bpm',
                    _OF.red,
                    dense: compact,
                  ),
                ),
                const SizedBox(width: 6),
                Expanded(
                  child: _focusedHeartMetric(
                    'Средняя',
                    historyHeartAvg <= 0 ? '—' : '$historyHeartAvg',
                    'bpm',
                    _OF.orange,
                    dense: compact,
                  ),
                ),
                const SizedBox(width: 6),
                Expanded(
                  child: _focusedHeartMetric(
                    'Максимум',
                    maxHeart <= 0 ? '—' : '$maxHeart',
                    'bpm',
                    _OF.graphite,
                    dense: compact,
                  ),
                ),
              ],
            ),
            SizedBox(height: compact ? 4 : 7),
            _focusedTeamMetricSwitcher(
              averageHeart: currentHeartAvg,
              averageLoad: avgLoad,
              averageSpeed: avgSpeed,
              dense: compact,
            ),
            SizedBox(height: compact ? 4 : 7),
            Expanded(
              child: _focusedTeamMetricChart(
                players: players,
                heartSeries: heartSeries,
                speedSeries: speedSeries,
                loadByPlayer: loadByPlayer,
              ),
            ),
            SizedBox(height: compact ? 4 : 7),
            SizedBox(
              height: compact ? 58 : 98,
              child: Column(
                children: [
                  Expanded(
                    child: Row(
                      children: [
                        Expanded(
                          child: _focusedLoadMetric(
                            'Дистанция',
                            '${totalDistance.toStringAsFixed(0)} м',
                            dense: compact,
                          ),
                        ),
                        const SizedBox(width: 5),
                        Expanded(
                          child: _focusedLoadMetric(
                            'Скорость',
                            avgSpeed.toStringAsFixed(1),
                            dense: compact,
                          ),
                        ),
                        const SizedBox(width: 5),
                        Expanded(
                          child: _focusedLoadMetric(
                            'Макс.',
                            maxSpeed.toStringAsFixed(1),
                            dense: compact,
