  Widget _focusedTeamMetricChart({
    required List<TrackerPlayerOption> players,
    required List<_LiveMetricSeries> heartSeries,
    required List<_LiveMetricSeries> speedSeries,
    required Map<int, double> loadByPlayer,
  }) {
    if (_focusedTeamMetricMode == 'load') {
      return _focusedTeamLoadComparison(players, loadByPlayer);
    }

    final heartMode = _focusedTeamMetricMode == 'heart';
    final series = heartMode ? heartSeries : speedSeries;
    if (series.isEmpty) {
      return _sideEmptyState(
        heartMode ? Icons.monitor_heart_rounded : Icons.speed_rounded,
        heartMode ? 'Нет live-пульса команды' : 'Нет GPS-скорости команды',
        heartMode
            ? 'Назначьте Polar H10 отмеченным игрокам — линии появятся автоматически.'
            : 'После первых GPS-пакетов появятся отдельные линии скорости игроков.',
      );
    }

    final maxSpeedValue = speedSeries
        .expand((item) => item.points)
        .fold<double>(0, (value, point) => math.max(value, point.value));
    return LayoutBuilder(
      builder: (context, constraints) {
        final showLegend = constraints.maxHeight >= 62;
        final isPhone = (MediaQuery.maybeOf(context)?.size.width ?? 1200) < 720;
        void updateCursor(double dx) {
          if (!isPhone || constraints.maxWidth <= 0) return;
          setState(() {
            _phoneChartCursorFraction =
                (dx / constraints.maxWidth).clamp(0.0, 1.0).toDouble();
          });
        }
        return Column(
          children: [
            Expanded(
              child: ClipRRect(
                borderRadius: BorderRadius.circular(10),
                child: DecoratedBox(
                  decoration: const BoxDecoration(color: Colors.white),
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTapDown: isPhone
                        ? (details) => updateCursor(details.localPosition.dx)
                        : null,
                    onPanDown: isPhone
                        ? (details) => updateCursor(details.localPosition.dx)
                        : null,
                    onPanUpdate: isPhone
                        ? (details) => updateCursor(details.localPosition.dx)
                        : null,
                    onDoubleTap: isPhone
                        ? () => setState(() => _phoneChartCursorFraction = null)
                        : null,
                    child: CustomPaint(
                      painter: _LiveLineChartPainter(
                        series: series,
                        minY: heartMode ? 80 : 0,
                        maxY:
                            heartMode ? 205 : math.max(22.0, maxSpeedValue + 3),
                        valueSuffix: heartMode ? ' bpm' : ' км/ч',
                        thresholds: heartMode
                            ? const <_LiveChartThreshold>[
                                _LiveChartThreshold(value: 145, label: 'Z3'),
                                _LiveChartThreshold(value: 165, label: 'Z4'),
                                _LiveChartThreshold(value: 180, label: 'Z5'),
                              ]
                            : const <_LiveChartThreshold>[
                                _LiveChartThreshold(value: 14, label: 'HIR'),
                                _LiveChartThreshold(value: 18, label: 'SPR'),
                              ],
                        highlightAbove: heartMode ? null : 18,
                        cursorFraction:
                            isPhone ? _phoneChartCursorFraction : null,
                      ),
                      child: const SizedBox.expand(),
                    ),
                  ),
                ),
              ),
            ),
            if (showLegend) ...[
              const SizedBox(height: 5),
              _sideLegend(series),
            ],
          ],
        );
      },
    );
  }

  Widget _focusedTeamLoadComparison(
    List<TrackerPlayerOption> players,
    Map<int, double> loadByPlayer,
  ) {
    if (loadByPlayer.isEmpty) {
      return _sideEmptyState(
        Icons.local_fire_department_rounded,
        'Нет GPS-нагрузки команды',
        'Нагрузка появится после движения отмеченных игроков и первых GPS-пакетов.',
      );
    }
    final visiblePlayers = players
        .where((player) => loadByPlayer.containsKey(player.id))
        .toList(growable: false);
    final maxValue = math.max(
      3.0,
      loadByPlayer.values.fold<double>(
        0,
        (value, load) => math.max(value, load),
      ),
    );
    return ListView.separated(
      padding: EdgeInsets.zero,
      physics: const BouncingScrollPhysics(),
      itemCount: visiblePlayers.length,
      separatorBuilder: (_, __) => const SizedBox(height: 5),
      itemBuilder: (_, index) {
        final player = visiblePlayers[index];
        final load = loadByPlayer[player.id] ?? 0;
        final ratio = (load / maxValue).clamp(0.0, 1.0).toDouble();
        final color = load >= 2.4
            ? _OF.red
            : (load >= 1.8 ? _OF.orange : (load >= .9 ? _OF.green : _OF.cyan));
        return Container(
          height: 34,
          padding: const EdgeInsets.symmetric(horizontal: 9),
          decoration: BoxDecoration(
            color: color.withOpacity(.055),
            borderRadius: BorderRadius.circular(9),
          ),
          child: Row(
            children: [
              SizedBox(
                width: 92,
                child: Text(
                  _compactPlayerName(player.displayName ?? player.name),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: _OFText.body(
                    size: 9.2,
                    color: _OF.text,
                    weight: FontWeight.w600,
                  ),
                ),
              ),
              const SizedBox(width: 7),
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(999),
                  child: LinearProgressIndicator(
                    minHeight: 6,
                    value: ratio,
                    backgroundColor: Colors.white,
                    valueColor: AlwaysStoppedAnimation<Color>(color),
                  ),
                ),
              ),
              const SizedBox(width: 8),
              SizedBox(
                width: 30,
                child: Text(
                  load.toStringAsFixed(1),
                  textAlign: TextAlign.right,
                  style: _OFText.value(10.2, color: color),
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  String _focusedTeamLoadLabel({
    required double averageLoad,
    required double peakLoad,
    required int averageHeart,
    required int maxHeart,
  }) {
    if (peakLoad <= 0 && maxHeart <= 0) return 'ЖДЁМ ДАННЫЕ';
    if (peakLoad >= 2.4 || maxHeart >= 180) return 'ПИК';
    if (averageLoad >= 1.8 || averageHeart >= 165) return 'ВЫСОКАЯ';
    if (averageLoad >= .9 || averageHeart >= 135) return 'РАБОЧАЯ';
    return 'ЛЁГКАЯ';
  }

  Color _focusedTeamLoadColor({
    required double peakLoad,
    required int maxHeart,
  }) {
    if (peakLoad >= 2.4 || maxHeart >= 180) return _OF.red;
    if (peakLoad >= 1.8 || maxHeart >= 165) return _OF.orange;
    if (peakLoad >= .9 || maxHeart >= 135) return _OF.green;
    return _OF.cyan;
  }

  String _focusedTeamRecommendation({
    required bool running,
    required int selectedCount,
    required int gpsCount,
    required int polarCount,
    required double averageLoad,
    required double peakLoad,
    required int averageHeart,
    required int maxHeart,
  }) {
    if (!running) {
      return 'После старта Live здесь начнётся общая сводка по $selectedCount отмеченным игрокам.';
    }
    if (gpsCount == 0 && polarCount == 0) {
      return 'Игроки выбраны, но GPS и Polar ещё не передают данные.';
    }
    if (maxHeart >= 180) {
      return 'У одного из игроков ЧСС Z5. Переключитесь на «Пульс» и проверьте красную линию.';
    }
    if (peakLoad >= 2.4) {
      return 'Есть пик внешней нагрузки. Переключитесь на «Нагрузка», чтобы увидеть игрока.';
    }
    if (averageHeart >= 165 || averageLoad >= 1.8) {
      return 'Команда работает интенсивно: контролируйте длительность отрезка и восстановление.';
    }
    if (gpsCount < selectedCount || polarCount < selectedCount) {
      return 'Сводка считается по доступным данным: GPS $gpsCount/$selectedCount, Polar $polarCount/$selectedCount.';
    }
    return 'Командная нагрузка стабильна, критичных отклонений по скорости и пульсу нет.';
  }

  Widget _focusedPlayerDataPanel(
    TrackerPlayerOption player, {
    required bool compact,
  }) {
    final live = _liveTelemetryActive;
    final local = live ? _localTrackForPlayer(player.id) : null;
    final session = live ? _sessionForPlayer(player.id) : null;
    final track = live ? _displayTrackForPlayer(player) : null;
    final heartRate = live ? _heartRateForPlayerId(player.id) : null;
    final history = live
        ? _focusedHeartRateHistory(player, heartRate)
        : const <_LiveHrPoint>[];
    final loadTimeline = live
        ? _focusedLoadTimeline(track)
        : const <_LiveMetricPoint>[];
    final bpmValues = history
        .map((point) => point.bpm)
        .where((bpm) => bpm > 0)
        .toList(growable: false);
    final avgHeartRate = bpmValues.isEmpty
        ? 0
        : (bpmValues.fold<int>(0, (sum, bpm) => sum + bpm) / bpmValues.length)
            .round();
    final maxHeartRate = bpmValues.isEmpty ? 0 : bpmValues.reduce(math.max);
    final distance = _safeLiveDistance(
      math.max(session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? 0.0),
      durationSec: math.max(session?.durationSec ?? 0, local?.durationSec ?? 0),
    );
    final speed = _currentLiveSpeed(
      local: local,
      serverSpeed: session?.speedKmh ?? 0.0,
    );
    final maxSpeed = _safeLiveSpeed(
        math.max(session?.maxSpeedKmh ?? 0.0, local?.maxSpeedKmh ?? 0.0));
    final load = math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0);
    final sprint = math.max(
        session?.sprintDistanceM ?? 0.0, local?.sprintDistanceM ?? 0.0);
    final hir =
        math.max(session?.hirDistanceM ?? 0.0, local?.hirDistanceM ?? 0.0);
    final accel = math.max(session?.accelCount ?? 0, local?.accelCount ?? 0);
    final decel = math.max(session?.decelCount ?? 0, local?.decelCount ?? 0);
    final durationSec =
        math.max(session?.durationSec ?? 0, local?.durationSec ?? 0);
    final online = live && _isPlayerOnlineLive(player.id);
    final markColor = _loadMarkColor(load, heartRateBpm: heartRate?.bpm);
    final series = history.isEmpty
        ? const <_LiveMetricSeries>[]
        : <_LiveMetricSeries>[
            _LiveMetricSeries(
              label: _compactPlayerName(player.displayName ?? player.name),
              color: _OF.red,
              points: history
                  .map((point) => _LiveMetricPoint(
                        timeMs: point.timeMs,
                        value: point.bpm.toDouble(),
                      ))
                  .toList(growable: false),
            ),
          ];

    return _ofPanel(
      title: 'Пульс и нагрузка',
      subtitle: online
          ? '${_compactPlayerName(player.displayName ?? player.name)} · online'
          : '${_compactPlayerName(player.displayName ?? player.name)} · ждём данные',
      actions: [
        Container(
          height: 22,
          padding: const EdgeInsets.symmetric(horizontal: 7),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: markColor.withOpacity(.08),
            borderRadius: BorderRadius.circular(999),
          ),
          child: Text(
            _loadMarkLabel(load, heartRateBpm: heartRate?.bpm),
            style: TextStyle(
                color: markColor, fontSize: AppTypography.menuGroupSize, fontWeight: FontWeight.w900),
          ),
        ),
      ],
      child: Padding(
        padding: EdgeInsets.all(compact ? 7 : 9),
        child: Column(
          children: [
            _NoHoverTap(
              onTap: () {
                if (_monitorPlayersExpanded &&
                    _expandedMonitorDetailPlayerId != null) {
                  _closeExpandedMonitorPlayerDetails();
                } else {
                  setState(() => _showSelectedPlayerDetail = false);
                }
              },
              borderRadius: BorderRadius.circular(8),
              child: Container(
                width: double.infinity,
                height: 30,
                padding: const EdgeInsets.symmetric(horizontal: 8),
                decoration: BoxDecoration(
                  color: _OF.greenSoftStrong,
                  borderRadius: BorderRadius.circular(8),
                ),
                child: const Row(
                  children: [
                    Icon(Icons.arrow_back_rounded, size: 14, color: _OF.green),
