  Widget _focusedHeartRateZones(List<int> bpmValues) {
    final counts = List<int>.filled(5, 0);
    for (final bpm in bpmValues) {
      final index = bpm < 120
          ? 0
          : bpm < 145
              ? 1
              : bpm < 165
                  ? 2
                  : bpm < 180
                      ? 3
                      : 4;
      counts[index]++;
    }
    final total = math.max(1, bpmValues.length);
    const colors = <Color>[
      _OF.cyan,
      _OF.green,
      _OF.orange,
      Color(0xFFF97316),
      _OF.red
    ];
    return Row(
      children: List.generate(5, (index) {
        final ratio = counts[index] / total;
        return Expanded(
          child: Padding(
            padding: EdgeInsets.only(right: index == 4 ? 0 : 5),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  Text('Z${index + 1}',
                      style: TextStyle(
                          color: colors[index],
                          fontSize: AppTypography.badgeSize,
                          fontWeight: FontWeight.w900)),
                  const Spacer(),
                  Text('${(ratio * 100).round()}%',
                      style: const TextStyle(
                          color: _OF.muted2,
                          fontSize: 8.2,
                          fontWeight: FontWeight.w700)),
                ]),
                const SizedBox(height: 3),
                ClipRRect(
                  borderRadius: BorderRadius.circular(999),
                  child: LinearProgressIndicator(
                    value: ratio,
                    minHeight: 5,
                    backgroundColor: _OF.line,
                    valueColor: AlwaysStoppedAnimation<Color>(colors[index]),
                  ),
                ),
              ],
            ),
          ),
        );
      }),
    );
  }

