  Widget _tabletMonitoringGridPanel(
      {bool compact = false, bool showFieldAction = false}) {
    final players = _monitorPlayersForGrid();
    final title = compact ? 'Live-мониторинг' : 'Live-мониторинг игроков';
    final subtitle = players.isEmpty
        ? 'выберите игроков сверху'
        : '${players.length} выбрано · свайп влево/вправо для остальных';
    return _ofPanel(
      title: title,
      subtitle: subtitle,
      actions: [
        if (_activity.requiresField) _fieldPanelToggleButton(compact: compact),
        if (showFieldAction)
          _livePanelWindowButton(
            label: 'Поле',
            tooltip: 'Открыть поле отдельным окном',
            onTap: () => _openExpandedLiveBlock('Поле / тактическая карта',
                Icons.map_rounded, () => _fieldCard()),
          ),
      ],
      child: players.isEmpty
          ? _monitorEmptyState()
          : LayoutBuilder(
              builder: (context, c) {
                final columns =
                    c.maxWidth >= 1060 ? 4 : (c.maxWidth >= 700 ? 3 : 2);
                final perPage =
                    math.max(1, math.min(_maxMonitorPlayers, columns * 2));
                final aspect = columns >= 4
                    ? (compact ? 2.18 : 2.30)
                    : (columns == 3
                        ? (compact ? 1.92 : 2.05)
                        : (compact ? 1.62 : 1.75));
                Widget gridFor(List<TrackerPlayerOption> pagePlayers) =>
                    GridView.builder(
                      physics: const BouncingScrollPhysics(
                          parent: AlwaysScrollableScrollPhysics()),
                      padding: EdgeInsets.all(compact ? 7 : 9),
                      itemCount: pagePlayers.length,
                      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: columns,
                        mainAxisSpacing: compact ? 8 : 10,
                        crossAxisSpacing: compact ? 8 : 10,
                        childAspectRatio: aspect,
                      ),
                      itemBuilder: (_, i) => _tabletLiveMonitorCard(
                          pagePlayers[i], i,
                          compact: compact),
                    );

                if (players.length <= perPage) return gridFor(players);
                final pages = <List<TrackerPlayerOption>>[];
                for (var i = 0; i < players.length; i += perPage) {
                  pages.add(players.sublist(
                      i, math.min(players.length, i + perPage)));
                }
                return Stack(
                  children: [
                    PageView.builder(
                      physics: const BouncingScrollPhysics(),
                      itemCount: pages.length,
                      itemBuilder: (_, page) => gridFor(pages[page]),
                    ),
                    Positioned(
                      right: 10,
                      top: 8,
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 4),
                        decoration: BoxDecoration(
                            color: Colors.white.withOpacity(.92),
                            borderRadius:
                                BorderRadius.circular(_OF.tabletInnerRadius)),
                        child: Text('${pages.length} стр.',
                            style: const TextStyle(
                                color: _OF.muted2,
                                fontSize: AppTypography.menuGroupSize,
                                fontWeight: FontWeight.w800)),
                      ),
                    ),
                  ],
                );
              },
            ),
    );
  }

