  Widget _tabletLiveMonitorCard(TrackerPlayerOption player, int index,
      {required bool compact}) {
    final local = _localTrackForPlayer(player.id);
    final session = _sessionForPlayer(player.id);
    final heartRate = _heartRateForPlayerId(player.id);
    final distance =
        math.max(session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? 0.0);
    final speed = _currentLiveSpeed(
      local: local,
      serverSpeed: session?.speedKmh ?? 0.0,
    );
    final maxSpeed = math.max(_safeLiveSpeed(session?.maxSpeedKmh ?? 0.0),
        _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0));
    final load = math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0);
    final sprint = math.max(
        session?.sprintDistanceM ?? 0.0, local?.sprintDistanceM ?? 0.0);
    final points = local?.points.length ??
        (session?.latitude != null && session?.longitude != null ? 1 : 0);
    final online = _isPlayerOnlineLive(player.id) ||
        session?.isOnline == true ||
        heartRate != null ||
        points > 0;
    final gpsReady = widget.connectedTeamPlayerIds.contains(player.id);
    final mapActive = _monitorMapPlayerIds.contains(player.id);
    final signalLabel = _signalLabelForPlayer(player);
    final signalColor = _signalColorForPlayer(player);
    return Material(
      color: Colors.transparent,
      borderRadius: BorderRadius.circular(_OF.tabletCardRadius),
      child: _NoHoverTap(
        onTap: () => _openPlayerOnSidePanel(player, mode: 'map'),
        onLongPress: () => _selectPlayerForAnalytics(player),
        borderRadius: BorderRadius.circular(_OF.tabletCardRadius),
        child: Container(
          padding: EdgeInsets.all(compact ? 7 : 9),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(_OF.tabletCardRadius),
            border: Border.all(
                color: online ? _OF.greenBorder : _OF.line,
                width: online ? 1.15 : 1),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  _playerAvatarCircle(
                      player: player,
                      radius: compact ? 16 : 19,
                      online: online),
                  const SizedBox(width: 7),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(_compactPlayerName(player.displayName ?? player.name),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color: _OF.text,
                                fontSize: compact ? 9.8 : 10.5,
                                fontWeight: FontWeight.w900,
                                letterSpacing: -.12)),
                        const SizedBox(height: 2),
                        Text(
                          '№${player.number ?? index + 1} · ${mapActive ? 'открыт справа' : (online ? 'online' : (gpsReady ? 'BLE готов · ждёт Старт' : (_running ? 'ждём данные' : 'GPS привязан')))}',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            color: mapActive || online || gpsReady
                                ? _OF.green
                                : _OF.muted2,
                            fontSize: compact ? 7.8 : 8.4,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ],
                    ),
                  ),
                  _NoHoverTap(
                    onTap: () => _openPlayerOnSidePanel(player, mode: 'map'),
                    borderRadius: BorderRadius.circular(999),
                    child: Container(
                      width: compact ? 24 : 26,
                      height: compact ? 24 : 26,
                      alignment: Alignment.center,
                      decoration:
                          const BoxDecoration(color: Colors.transparent),
                      child: Icon(
                          mapActive ? Icons.map_rounded : Icons.map_outlined,
                          color: mapActive ? _OF.green : _OF.muted2,
                          size: 14),
                    ),
                  ),
                  const SizedBox(width: 5),
                  _NoHoverTap(
                    onTap: () => _removeMonitorPlayer(player),
                    borderRadius: BorderRadius.circular(999),
                    child: Container(
                      width: compact ? 24 : 26,
                      height: compact ? 24 : 26,
                      alignment: Alignment.center,
                      decoration:
                          const BoxDecoration(color: Colors.transparent),
                      child: const Icon(Icons.close_rounded,
                          color: _OF.muted2, size: 14),
                    ),
                  ),
                ],
              ),
              SizedBox(height: compact ? 5 : 6),
              Expanded(
                child: AnimatedSwitcher(
                  duration: const Duration(milliseconds: 180),
                  child: _playerMonitorStatsBody(
                    distance: distance,
                    speed: speed,
                    maxSpeed: maxSpeed,
                    load: load,
                    sprint: sprint,
                    heartRate: heartRate,
                    points: points,
                    signalLabel: signalLabel,
                    signalColor: signalColor,
                    compact: compact,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

