  Widget _phoneLiveLoadPreviewCard() {
    final selected = widget.selectedPlayer;
    final players = selected == null
        ? _monitorCandidatePlayers().take(6).toList(growable: false)
        : <TrackerPlayerOption>[selected];
    final heartSeries = <_LiveMetricSeries>[];
    final speedSeries = <_LiveMetricSeries>[];
    final loadByPlayer = <int, double>{};
    final currentHeart = <int>[];
    final currentSpeed = <double>[];

    for (var i = 0; i < players.length; i++) {
      final player = players[i];
      final heart = _heartRateForPlayerId(player.id);
      if (heart != null) currentHeart.add(heart.bpm);
      final heartHistory = _focusedHeartRateHistory(player, heart);
      if (heartHistory.isNotEmpty) {
        heartSeries.add(
          _LiveMetricSeries(
            label: _compactPlayerName(player.displayName ?? player.name),
            color: selected == null ? _chartColor(i) : _OF.green,
            points: heartHistory
                .map((point) => _LiveMetricPoint(
                      timeMs: point.timeMs,
                      value: point.bpm.toDouble(),
                    ))
                .toList(growable: false),
          ),
        );
      }

      final track = _displayTrackForPlayer(player);
      if (track != null && track.points.isNotEmpty) {
        currentSpeed.add(_safeLiveSpeed(track.speedKmh));
        speedSeries.add(
          _LiveMetricSeries(
            label: _compactPlayerName(player.displayName ?? player.name),
            color: selected == null ? _chartColor(i) : _OF.green,
            points: track.points
                .map((point) => _LiveMetricPoint(
                      timeMs: point.timeMs,
                      value: _safeLiveSpeed(point.speedKmh),
                    ))
                .toList(growable: false),
          ),
        );
      }
      loadByPlayer[player.id] = _loadForPlayerId(player.id);
    }

    final averageHeart = currentHeart.isEmpty
        ? 0
        : (currentHeart.fold<int>(0, (sum, value) => sum + value) /
                currentHeart.length)
            .round();
    final averageSpeed = currentSpeed.isEmpty
        ? 0.0
        : currentSpeed.fold<double>(0, (sum, value) => sum + value) /
            currentSpeed.length;
    final validLoads = loadByPlayer.values.where((value) => value > 0).toList();
    final averageLoad = validLoads.isEmpty
        ? 0.0
        : validLoads.fold<double>(0, (sum, value) => sum + value) /
            validLoads.length;
    final maxHeart = heartSeries
        .expand((series) => series.points)
        .fold<double>(0, (value, point) => math.max(value, point.value));
    final maxSpeed = speedSeries
        .expand((series) => series.points)
        .fold<double>(0, (value, point) => math.max(value, point.value));

