          ],
        );
      }
      if (_focusedTeamMetricMode == 'speed') {
        return Column(
          children: [
            item(const Color(0xFF8BCF9D), 'Умеренный бег', '< 14 км/ч'),
            item(_OF.orange, 'HIR', '14–18 км/ч'),
            item(_OF.red, 'Спринт', '18+ км/ч'),
          ],
        );
      }
      return const SizedBox.shrink();
    }

    String primaryValue() {
      switch (_focusedTeamMetricMode) {
        case 'heart':
          return averageHeart <= 0 ? '—' : '$averageHeart';
        case 'speed':
          return averageSpeed.toStringAsFixed(1);
        default:
          return averageLoad.toStringAsFixed(1);
      }
    }

    String secondaryValue() {
      switch (_focusedTeamMetricMode) {
        case 'heart':
          return maxHeart <= 0 ? '—' : maxHeart.toStringAsFixed(0);
        case 'speed':
          return maxSpeed.toStringAsFixed(1);
        default:
          return validLoads.isEmpty
              ? '—'
              : validLoads.reduce((a, b) => math.max(a, b).toDouble()).toStringAsFixed(1);
      }
    }

    String unit() {
      switch (_focusedTeamMetricMode) {
        case 'heart':
          return 'уд/мин';
        case 'speed':
          return 'км/ч';
        default:
          return 'AU';
      }
    }

