  Widget _phoneMiniFieldCanvas() {
    if (!_activity.requiresField) return _fieldCard();
    final player = widget.selectedPlayer;
    final focusedTrack = player == null ? null : _displayTrackForPlayer(player);
    final tracks = player == null
        ? _tracks.values.toList(growable: false)
        : _focusedFieldTracks(player);

    return ClipRRect(
      borderRadius: BorderRadius.circular(_OF.mobileInnerRadius),
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(_OF.mobileInnerRadius),
        ),
        child: LayoutBuilder(
          builder: (context, constraints) {
            final size = constraints.biggest;
            final bounds = _phoneFieldBounds(tracks);
            final pitch = _phoneFieldPitch(size);
            final markerTracks = _showLabels
                ? tracks
                    .where((track) => track.points.isNotEmpty)
                    .toList(growable: false)
                : const <_RuntimeTrack>[];

            return Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Positioned.fill(
                  child: CustomPaint(
                    painter: _RuntimeFieldPainter(
                      field: widget.selectedField,
                      motionCache: _runtimeMotionEnabled ? _runtimeMotionCache : null,
                      repaint: _runtimeMotionController,
                      tracks: tracks,
                      focusedTrackKey: focusedTrack?.key,
                      showVectors: _showVectors,
                      showHeatmap: _showHeatmap,
                      showTrace: _showTrace,
                      // На телефоне имя и фото выводятся Flutter-виджетом поверх
                      // карты. Это читается лучше, чем подписи внутри canvas.
                      showLabels: false,
                      showTeamShapeConnections:
                          player == null && _showTeamShapeConnections,
                      warningEvents: _fieldLiveEvents(playerId: player?.id),
                      selectedWarningEventId: _selectedLiveEventId,
                    ),
                    child: const SizedBox.expand(),
                  ),
                ),
                if (_showPlayerAvatars)
                  for (final track in markerTracks)
                    _phoneFieldAvatarMarker(
                      track: track,
                      pitch: pitch,
                      bounds: bounds,
                      focused: focusedTrack?.key == track.key,
                    ),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _phoneFieldAvatarMarker({
    required _RuntimeTrack track,
    required Rect pitch,
    required _MapBounds bounds,
    required bool focused,
  }) {
    final point = track.points.last;
    final position = _phoneProjectFieldPoint(point, pitch, bounds);
    final player = _phonePlayerForTrack(track);
    final avatarUrl = _trackerAbsolutePhotoUrl(player?.avatar ?? track.avatar);
    final markerSize = focused ? 42.0 : 34.0;
    final left = (position.dx - markerSize / 2)
        .clamp(pitch.left - 2, pitch.right - markerSize + 2)
        .toDouble();
    final top = (position.dy - markerSize / 2)
        .clamp(pitch.top - 2, pitch.bottom - markerSize + 2)
        .toDouble();

    return AnimatedPositioned(
      key: ValueKey<String>('phone_field_avatar_${track.key}'),
      duration: const Duration(milliseconds: 780),
      curve: Curves.easeInOutCubic,
      left: left,
      top: top,
      width: markerSize,
      height: markerSize + 17,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: player == null
            ? null
            : () {
                widget.onSelectPlayer?.call(player);
                HapticFeedback.selectionClick();
              },
        child: Stack(
          clipBehavior: Clip.none,
          alignment: Alignment.topCenter,
          children: [
            AnimatedContainer(
              duration: const Duration(milliseconds: 180),
              width: markerSize,
              height: markerSize,
              padding: EdgeInsets.all(focused ? 2 : 1.5),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: Colors.white,
                border: Border.all(
                  color: focused ? _OF.green : Colors.white,
                  width: focused ? 2.2 : 1.6,
                ),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(.18),
                    blurRadius: focused ? 12 : 8,
                    spreadRadius: -3,
                    offset: const Offset(0, 4),
                  ),
                  if (focused)
                    BoxShadow(
                      color: _OF.green.withOpacity(.22),
                      blurRadius: 14,
                      spreadRadius: 1,
                    ),
                ],
              ),
              child: ClipOval(
                child: avatarUrl.isNotEmpty
                    ? Image.network(
                        avatarUrl,
                        fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => _phoneFieldInitials(track),
                      )
                    : _phoneFieldInitials(track),
              ),
            ),
            Positioned(
              top: markerSize - 7,
              child: Container(
                constraints: const BoxConstraints(minWidth: 30),
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                decoration: BoxDecoration(
                  color: focused ? _OF.green : const Color(0xFF1F2923),
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(color: Colors.white, width: 1.2),
                ),
                child: Text(
                  '${track.speedKmh.toStringAsFixed(1)}',
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 8.2,
                    fontWeight: FontWeight.w800,
                    height: 1,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _phoneFieldInitials(_RuntimeTrack track) {
    final parts = track.playerName
        .trim()
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList(growable: false);
    final initials = parts.isEmpty
        ? '•'
        : parts.take(2).map((part) => part[0].toUpperCase()).join();
    return Container(
      color: const Color(0xFFEFF8F2),
      alignment: Alignment.center,
      child: Text(
        initials,
        style: const TextStyle(
          color: _OF.green,
          fontSize: AppTypography.captionSize,
          fontWeight: FontWeight.w800,
        ),
      ),
    );
  }

  TrackerPlayerOption? _phonePlayerForTrack(_RuntimeTrack track) {
    final keyMatch = RegExp(r'(?:^|-)P(\d+)(?:$|-)').firstMatch(track.key);
    final keyPlayerId = keyMatch == null ? null : int.tryParse(keyMatch.group(1)!);
    for (final player in widget.players) {
      if (keyPlayerId != null &&
          (player.id == keyPlayerId || player.identityIds.contains(keyPlayerId))) {
        return player;
      }
      if (player.name.trim().toLowerCase() ==
          track.playerName.trim().toLowerCase()) {
        return player;
      }
    }
    return null;
  }

  Rect _phoneFieldPitch(Size size) {
    // V203 LIVE/REPLAY FIELD PARITY: поле Live использует ту же геометрию,
    // что и карта разбора. Сам газон заполняет весь canvas, а GPS/аватары
    // проецируются внутрь белой линии с отступом 10 px.
    return Rect.fromLTWH(
      10,
      10,
      math.max(1.0, size.width - 20),
      math.max(1.0, size.height - 20),
    );
  }

  _MapBounds _phoneFieldBounds(List<_RuntimeTrack> tracks) {
    final latValues = <double>[];
    final lonValues = <double>[];
    final previous = _liveGpsFallbackBounds;
    var hasRuntimeGps = previous != null;
    if (previous != null) {
      latValues.addAll(<double>[previous.minLat, previous.maxLat]);
      lonValues.addAll(<double>[previous.minLon, previous.maxLon]);
    }
    for (final track in tracks) {
      for (final point in track.points) {
        if (point.lat.isFinite && point.lon.isFinite) {
          hasRuntimeGps = true;
          latValues.add(point.lat);
          lonValues.add(point.lon);
        }
      }
    }
    // Калиброванные углы не смешиваем с реальными Live-точками. Если GPS
    // оказался за пределами старой/чужой калибровки, именно эти bounds служат
    // аварийной проекцией и должны показывать движение команды, а не прижимать
    // всех к одной границе поля.
    final field = widget.selectedField;
    if (latValues.isEmpty &&
        lonValues.isEmpty &&
        field?.hasCalibration == true) {
      latValues.addAll(<double?>[
        field!.cornerALat,
        field.cornerBLat,
        field.cornerCLat,
        field.cornerDLat,
      ].whereType<double>());
      lonValues.addAll(<double?>[
        field.cornerALng,
        field.cornerBLng,
        field.cornerCLng,
        field.cornerDLng,
      ].whereType<double>());
    }
    if (latValues.isEmpty || lonValues.isEmpty) {
      return const _MapBounds(
        minLat: -0.00005,
        maxLat: 0.00005,
        minLon: -0.00005,
        maxLon: 0.00005,
      );
    }
    var minLat = latValues.reduce(math.min);
    var maxLat = latValues.reduce(math.max);
    var minLon = lonValues.reduce(math.min);
    var maxLon = lonValues.reduce(math.max);
    if ((maxLat - minLat).abs() < 0.00001) {
      minLat -= 0.00005;
      maxLat += 0.00005;
    }
    if ((maxLon - minLon).abs() < 0.00001) {
      minLon -= 0.00005;
      maxLon += 0.00005;
    }
    final next = _MapBounds(
      minLat: minLat,
      maxLat: maxLat,
      minLon: minLon,
      maxLon: maxLon,
    );
    if (hasRuntimeGps) _liveGpsFallbackBounds = next;
    return next;
  }

  Offset _phoneProjectFieldPoint(
      _RuntimePoint point, Rect pitch, _MapBounds bounds) {
    final projected = TrackerPitchProjector.projectGps(
      widget.selectedField,
      latitude: point.lat,
      longitude: point.lon,
    );
    if (projected != null && projected.isInside) {
      return Offset(
        pitch.left + projected.clampedNx * pitch.width,
        pitch.bottom - projected.clampedNy * pitch.height,
      );
    }
    final lonRange = (bounds.maxLon - bounds.minLon).abs();
    final latRange = (bounds.maxLat - bounds.minLat).abs();
    final nx = lonRange < 0.000001
        ? .5
        : ((point.lon - bounds.minLon) / lonRange)
            .clamp(.035, .965)
            .toDouble();
    final ny = latRange < 0.000001
        ? .5
        : ((point.lat - bounds.minLat) / latRange)
            .clamp(.035, .965)
            .toDouble();
    return Offset(
      pitch.left + nx * pitch.width,
      pitch.bottom - ny * pitch.height,
    );
  }

