  Future<void> _openPhonePlayerAnalysisSheet(TrackerPlayerOption player) async {
    if (!mounted) return;
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(.26),
      builder: (sheetContext) {
        return DraggableScrollableSheet(
          initialChildSize: .92,
          minChildSize: .64,
          maxChildSize: .96,
          builder: (context, scrollController) {
            return Padding(
              padding: const EdgeInsets.fromLTRB(8, 8, 8, 0),
              child: ClipRRect(
                borderRadius: BorderRadius.vertical(
                    top: Radius.circular(_OF.sheetRadius)),
                child: Material(
                  color: Colors.white,
                  child: SafeArea(
                    top: false,
                    child: _phonePlayerAnalysisSheetContent(
                        player,
                        scrollController,
                        () => Navigator.of(sheetContext).pop()),
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }

  Widget _phonePlayerAnalysisSheetContent(TrackerPlayerOption player,
      ScrollController scrollController, VoidCallback onClose) {
    final local = _localTrackForPlayer(player.id);
    final session = _sessionForPlayer(player.id);
    final distance =
        math.max(session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? 0.0);
    final speed = _currentLiveSpeed(
      local: local,
      serverSpeed: session?.speedKmh ?? 0.0,
    );
    final maxSpeed = math.max(_safeLiveSpeed(session?.maxSpeedKmh ?? 0.0),
        _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0));
    final load = math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0);
    final hir =
        math.max(session?.hirDistanceM ?? 0.0, local?.hirDistanceM ?? 0.0);
    final vhir =
        math.max(session?.vhirDistanceM ?? 0.0, local?.vhirDistanceM ?? 0.0);
    final sprint = math.max(
        session?.sprintDistanceM ?? 0.0, local?.sprintDistanceM ?? 0.0);
    final heartRate = _heartRateForPlayerId(player.id);
    final maxBand = math.max(1.0, math.max(hir, math.max(vhir, sprint)));
    final hasData = distance > 0 || speed > 0 || load > 0 || heartRate != null;
    final liveState = _isPlayerOnlineLive(player.id)
        ? 'online'
        : (_running ? 'ждём данные' : 'готов к старту');
    return ListView(
      controller: scrollController,
      physics: const BouncingScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(16, 10, 16, 22),
      children: [
        Center(
          child: Container(
            width: 46,
            height: 4,
            decoration: BoxDecoration(
                color: _OF.lineStrong,
                borderRadius: BorderRadius.circular(999)),
          ),
        ),
        const SizedBox(height: 8),
        Row(
          children: [
            _playerAvatarCircle(
                player: player,
                radius: 24,
                online: _isPlayerOnlineLive(player.id)),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(player.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: _OF.text,
                          fontSize: 18,
                          fontWeight: FontWeight.w700,
                          letterSpacing: -.35)),
                  const SizedBox(height: 3),
                  Text(
                      '${_activity.shortTitle} · $liveState · ${_lastGpsAt == null ? 'GPS —' : 'GPS активен'}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: _OF.muted2,
                          fontSize: AppTypography.secondarySize,
                          fontWeight: FontWeight.w700)),
                ],
              ),
            ),
            _phoneSheetCloseButton(onClose),
          ],
        ),
        const SizedBox(height: 8),
        GridView.count(
          crossAxisCount: 2,
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          crossAxisSpacing: 8,
          mainAxisSpacing: 8,
          childAspectRatio: 2.45,
          children: [
            _phoneAnalysisMetric(
                'Дистанция', '${distance.toStringAsFixed(0)} м'),
            _phoneAnalysisMetric(
                'Скорость', '${speed.toStringAsFixed(1)} км/ч'),
            _phoneAnalysisMetric(
                'Макс. скорость', '${maxSpeed.toStringAsFixed(1)} км/ч'),
            _phoneAnalysisMetric(
                'Пульс', heartRate == null ? '—' : '${heartRate.bpm} bpm'),
            _phoneAnalysisMetric('Нагрузка', load.toStringAsFixed(0)),
            _phoneAnalysisMetric('Точки', '${local?.points.length ?? 0}'),
          ],
        ),
        const SizedBox(height: 8),
        _phoneAnalysisSection(
          title: 'Зоны скорости',
          icon: Icons.speed_rounded,
          child: hasData
              ? Column(
                  children: [
                    _phoneAnalysisBand('HIR', hir, maxBand, _OF.orange),
                    const SizedBox(height: 8),
                    _phoneAnalysisBand('VHIR', vhir, maxBand, _OF.cyan),
                    const SizedBox(height: 8),
                    _phoneAnalysisBand('SPR', sprint, maxBand, _OF.red),
                  ],
                )
              : _phoneAnalysisEmpty(
                  'После GPS здесь появятся HIR/VHIR/SPR, спринты и нагрузка.'),
        ),
        const SizedBox(height: 8),
        _phoneAnalysisSection(
          title: 'Нагрузка и рекомендация',
          icon: Icons.bolt_rounded,
          child: Text(
            _combinedLiveRecommendation(track: local, sample: heartRate),
            style: const TextStyle(
                color: _OF.muted,
                fontSize: AppTypography.secondarySize,
                fontWeight: FontWeight.w700,
                height: 1.35),
          ),
        ),
        const SizedBox(height: 8),
        SizedBox(
          height: 48,
          child: FilledButton.icon(
            onPressed: () {
              onClose();
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (mounted) unawaited(_openPlayerLiveDetails(player));
              });
            },
            style: FilledButton.styleFrom(
              backgroundColor: _OF.green,
              foregroundColor: Colors.white,
              elevation: 0,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(_OF.mobileButtonRadius)),
            ),
            icon: const Icon(Icons.analytics_rounded, size: 18),
            label: const Text('Открыть полный анализ',
                style: TextStyle(fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w700)),
          ),
        ),
      ],
    );
  }

