  Future<void> _openPhoneMoreActionsSheet(int online, int active) async {
    if (!mounted) return;
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(.24),
      builder: (sheetContext) {
        final bottom = MediaQuery.of(sheetContext).padding.bottom;

        void closeThen(VoidCallback action) {
          Navigator.of(sheetContext).pop();
          Future<void>.delayed(const Duration(milliseconds: 120), () {
            if (!mounted) return;
            action();
          });
        }

        Widget item({
          required IconData icon,
          required String title,
          required String subtitle,
          required VoidCallback onTap,
          bool primary = false,
          bool danger = false,
        }) {
          final color = danger ? _OF.red : (primary ? _OF.green : _OF.graphite);
          return _NoHoverTap(
            onTap: onTap,
            borderRadius: BorderRadius.circular(14),
            child: Container(
              padding: const EdgeInsets.fromLTRB(10, 9, 9, 9),
              decoration: BoxDecoration(
                color: primary ? _OF.greenSoft : Colors.white,
                borderRadius: BorderRadius.zero,
                border: Border.all(color: primary ? _OF.greenBorder : _OF.line),
              ),
              child: Row(
                children: [
                  Container(
                    width: 34,
                    height: 34,
                    decoration: BoxDecoration(
                        color: color.withOpacity(.09), shape: BoxShape.circle),
                    child: Icon(icon, color: color, size: 18),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color: danger ? _OF.red : _OF.text,
                                fontSize: AppTypography.bodySize,
                                fontWeight: FontWeight.w700,
                                letterSpacing: -.08)),
                        const SizedBox(height: 2),
                        Text(subtitle,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: _OF.muted2,
                                fontSize: AppTypography.captionSize,
                                fontWeight: FontWeight.w600)),
                      ],
                    ),
                  ),
                  Icon(Icons.chevron_right_rounded,
                      color: primary ? _OF.green : _OF.muted2, size: 20),
                ],
              ),
            ),
          );
        }

        return SafeArea(
          top: false,
          child: Padding(
            padding: EdgeInsets.fromLTRB(8, 8, 8, 8 + bottom),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(_OF.sheetRadius),
              child: Material(
                color: Colors.white,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Center(
                        child: Container(
                            width: 42,
                            height: 4,
                            decoration: BoxDecoration(
                                color: _OF.lineStrong,
                                borderRadius: BorderRadius.circular(999))),
                      ),
                      const SizedBox(height: 8),
                      Row(
                        children: [
                          Container(
                            width: 34,
                            height: 34,
                            decoration: BoxDecoration(
                                color: _OF.greenSoft,
                                shape: BoxShape.circle,
                                border: Border.all(color: _OF.greenBorder)),
                            child: const Icon(Icons.menu_rounded,
                                color: _OF.green, size: 19),
                          ),
                          const SizedBox(width: 10),
