                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Меню Live',
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                        color: _OF.text,
                                        fontSize: AppTypography.sectionTitleSize,
                                        fontWeight: FontWeight.w700,
                                        letterSpacing: -.12)),
