  Widget _teamLiveCommandCenter({required bool compact, bool phone = false}) {
    final loads = _teamLoadValues();
    final totalLoad = loads.fold<double>(0.0, (sum, v) => sum + v);
    final avgLoad = loads.isEmpty ? 0.0 : totalLoad / loads.length;
    final freshHeart = widget.heartRateByPlayerId.values
        .where((sample) =>
            DateTime.now().difference(sample.measuredAt).inSeconds <= 35)
        .toList();
    final avgHeart = freshHeart.isEmpty
        ? 0
        : (freshHeart.fold<int>(0, (sum, sample) => sum + sample.bpm) /
                freshHeart.length)
            .round();
    final livePlayers = _livePlayerOptions();
    final connectedPlayers = livePlayers
        .where((p) =>
            _isPlayerOnlineLive(p.id) || _heartRateForPlayerId(p.id) != null)
        .length;

    return Container(
      color: Colors.white,
      padding: EdgeInsets.fromLTRB(
          phone ? 6 : 8, phone ? 6 : 7, phone ? 6 : 8, phone ? 6 : 7),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                  child: _liveCommandKpi(
                      icon: Icons.groups_rounded,
                      label: 'Подключены',
                      value: '$connectedPlayers/${livePlayers.length}',
                      active: connectedPlayers > 0)),
              const SizedBox(width: 5),
              Expanded(
                  child: _liveCommandKpi(
                      icon: Icons.monitor_heart_rounded,
                      label: 'Пульс ср.',
                      value: avgHeart <= 0 ? '—' : '$avgHeart',
                      active: avgHeart > 0)),
              const SizedBox(width: 5),
              Expanded(
                  child: _liveCommandKpi(
                      icon: Icons.local_fire_department_rounded,
                      label: 'Нагрузка',
                      value: avgLoad.toStringAsFixed(0),
                      active: avgLoad > 0)),
            ],
          ),
          const SizedBox(height: 6),
          SizedBox(
              height: phone ? 44 : 52,
              child: _quickPlayerSelector(phone: phone, compact: compact)),
          const SizedBox(height: 6),
          Expanded(child: _teamLoadDotsChart(compact: compact)),
        ],
      ),
    );
  }

  Widget _liveCommandKpi(
      {required IconData icon,
      required String label,
      required String value,
      required bool active}) {
    return Container(
      height: 32,
      padding: const EdgeInsets.symmetric(horizontal: 6),
      decoration: BoxDecoration(
        color: active ? _OF.greenSoft : _OF.header,
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: active ? _OF.greenBorder : _OF.line),
      ),
      child: Row(
        children: [
          Icon(icon, size: 12, color: active ? _OF.green : _OF.muted2),
          const SizedBox(width: 6),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: _OF.muted2,
                        fontSize: AppTypography.captionSize,
                        fontWeight: FontWeight.w700)),
                const SizedBox(height: 1),
                Text(value,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: active ? _OF.text : _OF.muted2,
                        fontSize: AppTypography.secondarySize,
                        fontWeight: FontWeight.w700)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _quickPlayerSelector({required bool phone, required bool compact}) {
    final players = _monitorCandidatePlayers();
    if (players.isEmpty) {
      return Container(
        alignment: Alignment.center,
        decoration: BoxDecoration(
            color: Colors.white, borderRadius: BorderRadius.circular(4)),
        child: const Text('Игроки появятся после загрузки состава',
            style: TextStyle(
                color: _OF.muted2,
                fontSize: AppTypography.secondarySize,
                fontWeight: FontWeight.w700)),
      );
    }
    return ListView.separated(
      scrollDirection: Axis.horizontal,
      physics: const BouncingScrollPhysics(),
      itemCount: players.length,
      separatorBuilder: (_, __) => const SizedBox(width: 5),
      itemBuilder: (_, i) =>
          _quickPlayerChip(players[i], i, phone: phone, compact: compact),
    );
  }

  Widget _quickPlayerChip(TrackerPlayerOption player, int index,
      {required bool phone, required bool compact}) {
    final selected = _isPlayerInMonitorGrid(player.id);
    final focused = widget.selectedPlayer?.id == player.id;
    final online = _isPlayerOnlineLive(player.id);
    final load = _loadForPlayerId(player.id);
    final bpm = _heartRateForPlayerId(player.id)?.bpm;
    final mark = _loadMarkLabel(load, heartRateBpm: bpm);
    final markColor = _loadMarkColor(load, heartRateBpm: bpm);
    final avatar = _trackerAbsolutePhotoUrl(
        player.avatar ?? _sessionForPlayer(player.id)?.avatarUrl);
    final number = player.number ?? '${index + 1}';
    return Material(
      color: selected || focused
          ? _OF.greenSoft
          : (online ? _OF.greenSoft : _OF.header),
      borderRadius: BorderRadius.circular(4),
      child: _NoHoverTap(
        onTap: () => _toggleMonitorPlayer(player),
        onLongPress: () => _selectPlayerForAnalytics(player),
        borderRadius: BorderRadius.circular(4),
        child: Container(
          width: phone ? 150 : (compact ? 170 : 190),
          padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(4),
            border: Border.all(
                color: selected || focused
                    ? _OF.green
                    : (online ? _OF.greenBorder : _OF.line)),
          ),
          child: Row(
            children: [
              Stack(
                clipBehavior: Clip.none,
                children: [
                  CircleAvatar(
                    radius: phone ? 12 : 14,
                    backgroundColor: selected || focused
                        ? _OF.green
                        : (online ? _OF.green : Colors.white),
                    backgroundImage:
                        avatar.isNotEmpty ? NetworkImage(avatar) : null,
                    child: avatar.isEmpty
                        ? Text(_playerInitials(player.name),
                            style: TextStyle(
                                color: online || selected || focused
                                    ? Colors.white
                                    : _OF.graphite,
                                fontSize: AppTypography.secondarySize,
                                fontWeight: FontWeight.w700))
                        : null,
                  ),
                  Positioned(
                    right: -3,
                    bottom: -3,
                    child: Container(
                      width: 13,
                      height: 13,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(4),
                          border:
                              Border.all(color: online ? _OF.green : _OF.line)),
                      child: Text(number,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: online ? _OF.green : _OF.muted2,
                              fontSize: AppTypography.menuGroupSize,
                              fontWeight: FontWeight.w700)),
                    ),
                  ),
                ],
              ),
              const SizedBox(width: 9),
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(_compactPlayerName(player.displayName ?? player.name),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                            color: selected || focused ? _OF.green : _OF.text,
                            fontSize: phone ? 9.4 : 10.2,
                            fontWeight: FontWeight.w700)),
                    const SizedBox(height: 2),
                    Row(
                      children: [
                        _miniValuePill(
                            icon: Icons.favorite_rounded,
                            text: bpm == null ? '—' : '$bpm',
                            active: bpm != null,
                            color: _OF.red),
                        const SizedBox(width: 4),
                        _miniValuePill(
                            icon: Icons.local_fire_department_rounded,
                            text: load.toStringAsFixed(0),
                            active: load > 0,
                            color: markColor),
                        const SizedBox(width: 4),
                        Flexible(
                            child: Text(mark,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: TextStyle(
                                    color: markColor,
                                    fontSize: AppTypography.menuGroupSize,
                                    fontWeight: FontWeight.w700))),
                      ],
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 4),
              _NoHoverTap(
                onTap: () => _toggleMonitorPlayer(player),
                child: Container(
                  width: 22,
                  height: 22,
                  decoration: BoxDecoration(
                      color: selected ? _OF.green : Colors.white,
                      borderRadius: BorderRadius.circular(4),
                      border: Border.all(
                          color: selected ? _OF.green : _OF.greenBorder)),
                  child: Icon(
                      selected ? Icons.check_rounded : Icons.add_rounded,
                      size: 13,
                      color: selected ? Colors.white : _OF.green),
                ),
