  Widget _teamLoadDotsChart({required bool compact}) {
    final samples = _teamLoadTimelineForPaint();
    if (samples.isEmpty ||
        samples.every((v) => v.avgLoad <= 0 && v.maxLoad <= 0)) {
      return Container(
        alignment: Alignment.centerLeft,
        padding: const EdgeInsets.symmetric(horizontal: 10),
        decoration: BoxDecoration(
            color: Colors.white, borderRadius: BorderRadius.circular(8)),
        child: const Text('График нагрузки появится после первых live-пакетов',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
                color: _OF.muted2,
                fontSize: AppTypography.captionSize,
                fontWeight: FontWeight.w600)),
      );
    }
    final maxLoad = math
        .max(
            1.0,
            samples
                .map((s) => s.maxLoad)
                .fold<double>(0, (m, v) => math.max(m, v).toDouble()))
        .toDouble();
    final maxElapsed = math
        .max(
            60,
            samples
                .map((s) => s.elapsedSec)
                .fold<int>(0, (m, v) => math.max(m, v).toInt()))
        .toInt();
    return Container(
      decoration: BoxDecoration(
          color: Colors.white, borderRadius: BorderRadius.circular(8)),
      child: CustomPaint(
        painter: _TeamLoadTimePainter(
            samples: samples,
            maxValue: maxLoad,
            maxElapsedSec: maxElapsed,
            showAxis: !compact),
        child: Stack(
          children: [
            Positioned(
              left: 10,
              top: 7,
              child: Text('нагрузка команды · по времени',
                  style: TextStyle(
                      color: _OF.muted2.withOpacity(.92),
                      fontSize: compact ? 8.4 : 9.4,
                      fontWeight: FontWeight.w700)),
            ),
            Positioned(
              right: 10,
              top: 7,
              child: Text(
                  'max ${maxLoad.toStringAsFixed(maxLoad < 10 ? 1 : 0)}',
                  style: TextStyle(
                      color: _OF.green,
                      fontSize: compact ? 8.4 : 9.4,
                      fontWeight: FontWeight.w700)),
            ),
          ],
        ),
      ),
    );
  }

