  Future<void> _openActivityChooser() async {
    if (_running) {
      _toast('Сначала остановите Live, затем смените тип тренировки');
      return;
    }
    final selected = await showDialog<TrackerTrainingActivity>(
      context: context,
      barrierColor: const Color(0x66000000),
      builder: (context) {
        return Dialog(
          insetPadding: const EdgeInsets.all(9),
          backgroundColor: Colors.transparent,
          child: LayoutBuilder(
            builder: (context, c) {
              final phone = c.maxWidth < 620;
              final maxWidth = phone ? c.maxWidth : math.min(c.maxWidth, 820.0);
              return Center(
                child: Container(
                  width: maxWidth,
                  padding: const EdgeInsets.all(9),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(8),
                    boxShadow: null,
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 38,
                            height: 38,
                            decoration: BoxDecoration(
                                color: _OF.greenSoft,
                                borderRadius: BorderRadius.circular(6)),
                            child: const Icon(Icons.tune_rounded,
                                color: _OF.green, size: 19),
                          ),
                          const SizedBox(width: 8),
                          const Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Выберите тип трекинга',
                                    style: TextStyle(
                                        color: _OF.text,
                                        fontSize: AppTypography.itemTitleSize,
                                        fontWeight: FontWeight.w700)),
                                SizedBox(height: 2),
                                Text(
                                    'Поле требуется только для футбола. Кросс и зал запускаются без field_id.',
                                    style: TextStyle(
                                        color: _OF.muted,
                                        fontSize: AppTypography.secondarySize,
                                        fontWeight: FontWeight.w600)),
                              ],
                            ),
                          ),
                          _NoHoverTap(
                            onTap: () => Navigator.of(context).pop(),
                            child: const SizedBox(
                                width: 32,
                                height: 32,
                                child: Icon(Icons.close_rounded,
                                    color: _OF.muted, size: 18)),
                          ),
                        ],
                      ),
                      const SizedBox(height: 8),
                      if (phone) ...[
                        _ActivityModeCard(
                            activity: TrackerTrainingActivity.footballField,
                            selected: _activity ==
                                TrackerTrainingActivity.footballField),
                        const SizedBox(height: 8),
                        _ActivityModeCard(
                            activity: TrackerTrainingActivity.outdoorRun,
                            selected: _activity ==
                                TrackerTrainingActivity.outdoorRun),
                        const SizedBox(height: 8),
                        _ActivityModeCard(
                            activity: TrackerTrainingActivity.indoorStrength,
                            selected: _activity ==
                                TrackerTrainingActivity.indoorStrength),
                      ] else
                        Row(
                          children: [
                            Expanded(
                                child: _ActivityModeCard(
                                    activity:
                                        TrackerTrainingActivity.footballField,
                                    selected: _activity ==
                                        TrackerTrainingActivity.footballField,
                                    vertical: true)),
                            const SizedBox(width: 8),
                            Expanded(
                                child: _ActivityModeCard(
                                    activity:
                                        TrackerTrainingActivity.outdoorRun,
                                    selected: _activity ==
                                        TrackerTrainingActivity.outdoorRun,
                                    vertical: true)),
                            const SizedBox(width: 8),
                            Expanded(
                                child: _ActivityModeCard(
                                    activity:
                                        TrackerTrainingActivity.indoorStrength,
                                    selected: _activity ==
                                        TrackerTrainingActivity.indoorStrength,
                                    vertical: true)),
                          ],
                        ),
                    ],
                  ),
                ),
              );
            },
          ),
        );
      },
    );
    if (!mounted || selected == null) return;
    setState(() {
      _activity = selected;
      _tracks.clear();
      _sessions = <TrackerLiveSessionModel>[];
      _teamLoadHistory.clear();
      _lastProblem = selected.requiresField
          ? 'Выбран режим «${selected.title}»: нужно откалиброванное поле.'
          : 'Выбран режим «${selected.title}»: поле не требуется, сессия будет сохранена без field_id.';
    });
    await _loadLiveState();
  }

  Future<void> _openLiveViewSettings() async {
    await showDialog<void>(
      context: context,
      barrierColor: const Color(0x55000000),
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (dialogContext, localSetState) {
            void apply(VoidCallback change) {
              if (!mounted) return;
              setState(change);
              localSetState(() {});
            }

            Widget toggleTile({
              required IconData icon,
              required String title,
              required String subtitle,
              required bool value,
              required ValueChanged<bool> onChanged,
            }) {
              return Container(
                margin: const EdgeInsets.only(bottom: 6),
                padding: const EdgeInsets.fromLTRB(10, 8, 8, 8),
                decoration: BoxDecoration(
                  color: value ? _OF.greenSoftStrong : _OF.soft,
                  borderRadius: BorderRadius.circular(11),
