  Widget _liveControlStrip(int online, int active, {required bool compact}) {
    final trackerReady = _teamTrackerReady || widget.ble.connectedInfo != null;
    final hasPolar =
        widget.heartRateConnectedCount > 0 || _hasTeamHeartRateOnline;
    final gpsReady = _lastGpsAt != null &&
        DateTime.now().difference(_lastGpsAt!).inSeconds < 8;
    final duration = _durationText();

    Widget primaryLiveButton({required bool phone}) {
      final text = _starting
          ? '...'
          : (_paused
              ? 'Продолжить'
              : (_running ? 'Стоп' : (phone ? 'Старт Live' : 'Старт')));
      final accent = _running ? _OF.red : _OF.green;
      final surface = _running ? _OF.red : _OF.green;
      return SizedBox(
        height: 36,
        child: FilledButton.icon(
          onPressed: _starting
              ? null
              : (_paused
                  ? _resumeLiveCollection
                  : (_running ? _stopLive : _startLive)),
          style: FilledButton.styleFrom(
            backgroundColor: surface,
            disabledBackgroundColor: _OF.soft,
            disabledForegroundColor: _OF.muted,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 11),
            shape:
                RoundedRectangleBorder(borderRadius: BorderRadius.circular(9)),
            elevation: 0,
          ),
          icon: Icon(
              _paused
                  ? Icons.play_arrow_rounded
                  : (_running ? Icons.stop_rounded : Icons.play_arrow_rounded),
              size: 15),
          label: Text(
            text,
            style: _OFText.button(
              color: Colors.white,
              size: 11.0,
              weight: FontWeight.w600,
            ),
          ),
        ),
      );
    }

    if (compact) {
      return Container(
        height: 50,
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(_OF.tabletCardRadius),
        ),
        child: Row(
          children: [
            SizedBox(width: 112, child: primaryLiveButton(phone: true)),
            const SizedBox(width: 7),
            _activitySelectorChip(compact: true),
            const SizedBox(width: 7),
            Expanded(
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                child: Row(
                  children: [
                    SizedBox(
                        width: 94,
                        child: _liveMiniChip(Icons.timer_rounded, duration,
                            active: _running && !_paused, tight: true)),
                    const SizedBox(width: 5),
                    SizedBox(
                        width: 60,
                        child: _liveMiniChip(
                            Icons.groups_rounded, '$online/$active',
                            active: online > 0, tight: true)),
                    const SizedBox(width: 5),
                    SizedBox(
                        width: 66,
                        child: _liveMiniChip(
                            Icons.gps_fixed_rounded, gpsReady ? 'GPS' : 'GPS —',
                            active: gpsReady, tight: true)),
                    const SizedBox(width: 5),
                    SizedBox(
                        width: 72,
                        child: _liveMiniChip(Icons.favorite_rounded,
                            hasPolar ? 'Polar' : 'Polar —',
                            active: hasPolar, tight: true)),
                    const SizedBox(width: 5),
                    SizedBox(
                        width: 72,
                        child: _liveMiniChip(Icons.sensors_rounded,
                            trackerReady ? 'BLE' : 'BLE —',
                            active: trackerReady, tight: true)),
                    const SizedBox(width: 5),
                    _liveViewSettingsButton(compact: true),
                    if (widget.onResetTeamGps != null) ...[
                      const SizedBox(width: 5),
                      _liveResetGpsButton(compact: true),
                    ],
                    if (_running) ...[
                      const SizedBox(width: 5),
                      _liveExitButton(compact: true),
                    ] else if (!trackerReady &&
                        widget.onScanBluetooth != null) ...[
                      const SizedBox(width: 5),
                      SizedBox(
                        width: 38,
                        height: 32,
                        child: TextButton(
                          onPressed: widget.scanningBluetooth
                              ? null
                              : widget.onScanBluetooth,
                          style: TextButton.styleFrom(
                            foregroundColor: _OF.graphite,
                            backgroundColor: const Color(0xFFF1F3F6),
                            shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(4)),
                            padding: EdgeInsets.zero,
                          ),
                          child: widget.scanningBluetooth
                              ? const SizedBox(
                                  width: 13,
                                  height: 13,
                                  child:
                                      CircularProgressIndicator(strokeWidth: 2))
                              : const Icon(Icons.bluetooth_searching_rounded,
                                  size: 15),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
          ],
        ),
      );
    }

    return Container(
      height: 50,
      padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(_OF.tabletCardRadius),
        border: Border.all(color: _OF.line.withOpacity(.72), width: .7),
      ),
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        child: Row(
          children: [
            _ofStatusDot(
                _paused ? _OF.orange : (_running ? _OF.green : _OF.muted2)),
            const SizedBox(width: 8),
            Text(
              _paused ? 'Пауза' : (_running ? 'Live' : 'Готовность'),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  color: _OF.text,
                  fontSize: AppTypography.secondarySize,
                  fontWeight: FontWeight.w700,
                  letterSpacing: -.12),
            ),
            const SizedBox(width: 8),
            _liveMiniChip(Icons.timer_rounded, duration,
                active: _running && !_paused),
            const SizedBox(width: 6),
            _activitySelectorChip(compact: false),
            const SizedBox(width: 6),
            _liveMiniChip(Icons.groups_rounded, '$online/$active',
                active: online > 0),
            const SizedBox(width: 6),
            _liveMiniChip(
                Icons.monitor_heart_rounded,
                hasPolar
                    ? 'Polar ${widget.heartRateConnectedCount}'
                    : 'Polar —',
                active: hasPolar),
            const SizedBox(width: 6),
            _liveMiniChip(Icons.gps_fixed_rounded, gpsReady ? 'GPS' : 'GPS нет',
                active: gpsReady),
            const SizedBox(width: 6),
            _liveMiniChip(
                Icons.sensors_rounded, trackerReady ? 'Трекер' : 'Трекер нет',
                active: trackerReady),
            if (_running) ...[
              const SizedBox(width: 6),
              _liveExitButton(compact: false),
            ],
            const SizedBox(width: 8),
            SizedBox(width: 160, child: _compactLoadTimeline()),
            const SizedBox(width: 8),
            if (!trackerReady && widget.onScanBluetooth != null) ...[
              SizedBox(
                height: 30,
                child: OutlinedButton.icon(
                  onPressed: widget.scanningBluetooth
                      ? null
                      : (widget.onScanBluetooth ?? widget.onManageTrackers),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: _OF.graphite,
                    side: BorderSide.none,
                    backgroundColor: _OF.header,
                    padding: const EdgeInsets.symmetric(horizontal: 10),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(4)),
                  ),
                  icon: widget.scanningBluetooth
                      ? const SizedBox(
                          width: 12,
                          height: 12,
                          child: CircularProgressIndicator(strokeWidth: 2))
                      : const Icon(Icons.bluetooth_searching_rounded, size: 14),
                  label: Text(
                      widget.scanningBluetooth ? 'Поиск...' : 'Bluetooth',
                      style: const TextStyle(
                          fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w700)),
                ),
              ),
              const SizedBox(width: 6),
            ],
            _liveViewSettingsButton(compact: false),
            const SizedBox(width: 6),
            if (widget.onResetTeamGps != null) ...[
              _liveResetGpsButton(compact: false),
              const SizedBox(width: 6),
            ],
            primaryLiveButton(phone: false),
          ],
        ),
      ),
    );
  }

