  Widget _liveMiniChip(IconData icon, String label,
      {required bool active, bool tight = false}) {
    return Container(
      height: tight ? 32 : 22,
      padding: EdgeInsets.symmetric(horizontal: tight ? 4 : 6),
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: active ? _OF.greenSoftStrong : Colors.transparent,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(
        mainAxisSize: tight ? MainAxisSize.max : MainAxisSize.min,
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(icon,
              color: active ? _OF.green : _OF.muted, size: tight ? 12 : 13),
          SizedBox(width: tight ? 3 : 5),
          Flexible(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
