  Widget _activePlayersPanel(int online, int active) {
    final connectedPlayers = _connectedPlayerOptions();
    final totalPlayers = _livePlayerOptions().length;
    return _ofPanel(
      title: 'Игроки онлайн',
      subtitle: connectedPlayers.isEmpty
          ? '$online/$active онлайн · ждём данные'
          : '${connectedPlayers.length}/$totalPlayers в списке · $online онлайн',
      actions: const [],
      child: connectedPlayers.isEmpty
          ? _playersFallbackList(connectedOnly: true)
          : ListView.builder(
              itemCount: connectedPlayers.length,
              itemBuilder: (_, i) {
                final p = connectedPlayers[i];
                final session = _sessionForPlayer(p.id);
                final local = _localTrackForPlayer(p.id);
                final isSelected = widget.selectedPlayer?.id == p.id;
                return _ofPlayerRow(
                  player: p,
                  name: p.name,
                  number: '${p.number ?? i + 1}',
                  speed: _currentLiveSpeed(
                    local: local,
                    serverSpeed: session?.speedKmh ?? 0.0,
                  ),
                  load: math.max(
                      session?.loadScore ?? 0.0, local?.loadScore ?? 0.0),
                  heartRateBpm: _heartRateForPlayerId(p.id)?.bpm,
                  online: _isPlayerOnlineLive(p.id),
                  selected: isSelected,
                  onTap: () => _selectPlayerAndOpenDetails(p),
                );
              },
            ),
    );
  }

  Widget _playersFallbackList({bool connectedOnly = false}) {
    if (connectedOnly) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.symmetric(horizontal: 14),
          child: Text(
            'Подключённые GPS/Polar игроки появятся здесь сразу после первых live-данных.',
            textAlign: TextAlign.center,
            style: TextStyle(
                color: _OF.muted, fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w700),
          ),
        ),
      );
    }
    if (widget.players.isEmpty) {
      return const Center(
          child: Text('Нет игроков команды',
              style: TextStyle(color: _OF.muted, fontWeight: FontWeight.w500)));
    }
    return ListView.builder(
      itemCount: widget.players.length,
      itemBuilder: (_, i) {
        final p = widget.players[i];
        return _ofPlayerRow(
          player: p,
          name: p.name,
          number: '${p.number ?? i + 1}',
          speed: 0,
          load: 0,
          heartRateBpm: _heartRateForPlayerId(p.id)?.bpm,
          online: false,
          selected: widget.selectedPlayer?.id == p.id,
          onTap: () => _selectPlayerAndOpenDetails(p),
