  String _compactPlayerName(String raw) {
    final parts =
        raw.trim().split(RegExp(r'\s+')).where((p) => p.isNotEmpty).toList();
    if (parts.length < 2) return raw.trim();
    // TrackerPlayerOption canonical name is surname-first (CMR convention).
    // Keep that order in Live chips/list: «Берёзкин А.», not «Арсений Б.». 
    final surname = parts.first;
    final initials = parts
        .skip(1)
        .where((p) => p.isNotEmpty)
        .map((p) => p.endsWith('.') ? p : '${p.substring(0, 1)}.')
        .join(' ');
    return initials.isEmpty ? surname : '$surname $initials';
  }

  /// V208: Live-events API can return a technical label like «Игрок 93»
  /// even when the roster already contains the real player. Resolve the event
  /// back to TrackerPlayerOption before rendering the journal/timeline.
  TrackerPlayerOption? _playerForLiveEvent(TrackerLiveEventModel event) {
    final ids = <int>{};
    final directId = event.playerId;
    if (directId != null && directId > 0) ids.add(directId);

    final technical = RegExp(
      r'^(?:Игрок|Player)\s*#?\s*(\d+)$',
      caseSensitive: false,
    ).firstMatch(event.playerName.trim());
    final technicalId = technical == null ? null : int.tryParse(technical.group(1)!);
    if (technicalId != null && technicalId > 0) ids.add(technicalId);

    final candidates = _monitorCandidatePlayers();
    if (ids.isNotEmpty) {
      for (final candidate in candidates) {
        if (ids.contains(candidate.id) ||
            candidate.identityIds.any(ids.contains)) {
          return candidate;
        }
      }
    }

    final rawName = event.playerName.trim().toLowerCase();
    if (rawName.isNotEmpty &&
        rawName != 'игрок' &&
        rawName != 'player') {
      for (final candidate in candidates) {
        final canonical = candidate.name.trim().toLowerCase();
        final display = (candidate.displayName ?? '').trim().toLowerCase();
        if (rawName == canonical || (display.isNotEmpty && rawName == display)) {
          return candidate;
        }
      }
    }
    return null;
  }

  String _liveEventPlayerName(
    TrackerLiveEventModel event, {
    // Live journal follows the same compact CMR name format as player cards:
    // «Берёзкин А.», not «Берёзкин Арсений».
    bool compact = true,
  }) {
    final player = _playerForLiveEvent(event);
    final resolved = (player?.displayName ?? player?.name ?? event.playerName).trim();
    final name = resolved.isEmpty ? 'Игрок' : resolved;
    return compact ? _compactPlayerName(name) : name;
  }

