  String _liveTacticalRole(String? raw) {
    final value = (raw ?? '').trim().toLowerCase();
    if (value.isEmpty) return 'unknown';
    if (value.contains('врат') ||
        value == 'gk' ||
        value.contains('goalkeeper')) {
      return 'gk';
    }
    if (value.contains('защит') ||
        value.contains('defender') ||
        value.contains('centre back') ||
        value.contains('center back') ||
        RegExp(r'(^|\W)(cb|lb|rb|lwb|rwb)(\W|$)').hasMatch(value)) {
      return 'def';
    }
    if (value.contains('полузащ') ||
        value.contains('midfield') ||
        RegExp(r'(^|\W)(cm|dm|cdm|am|cam|lm|rm)(\W|$)').hasMatch(value)) {
      return 'mid';
    }
    if (value.contains('напад') ||
        value.contains('forward') ||
        value.contains('striker') ||
        value.contains('winger') ||
        RegExp(r'(^|\W)(st|cf|fw|lw|rw)(\W|$)').hasMatch(value)) {
      return 'att';
    }
    return 'unknown';
  }

  List<double> _liveTacticalClusterCenters(List<double> values) {
    if (values.isEmpty) return const <double>[];
    final sorted = List<double>.from(values)..sort();
    if (sorted.length < 3) return sorted;
    var centers = <double>[sorted.first, sorted[sorted.length ~/ 2], sorted.last];
    for (var iteration = 0; iteration < 10; iteration++) {
      final groups = <List<double>>[
        <double>[],
        <double>[],
        <double>[],
      ];
      for (final value in sorted) {
        var best = 0;
        var bestDistance = (value - centers.first).abs();
        for (var i = 1; i < centers.length; i++) {
          final distance = (value - centers[i]).abs();
          if (distance < bestDistance) {
            best = i;
            bestDistance = distance;
          }
        }
        groups[best].add(value);
      }
      for (var i = 0; i < groups.length; i++) {
        if (groups[i].isNotEmpty) {
          centers[i] = groups[i].reduce((a, b) => a + b) / groups[i].length;
        }
      }
      centers.sort();
    }
    return centers;
  }

  double _liveTacticalHullArea(List<Offset> meterPoints) {
    if (meterPoints.length < 3) return 0;
    final hull = _runtimeConvexHull(meterPoints);
    if (hull.length < 3) return 0;
    var sum = 0.0;
    for (var i = 0; i < hull.length; i++) {
      final a = hull[i];
      final b = hull[(i + 1) % hull.length];
      sum += a.dx * b.dy - b.dx * a.dy;
    }
    return sum.abs() * .5;
  }

  _LiveTacticalSnapshot _liveMapTacticalSnapshot(List<_RuntimeTrack> tracks) {
    final fieldLength = (widget.selectedField?.lengthM ?? 105.0)
        .clamp(20.0, 180.0)
        .toDouble();
    final fieldWidth = (widget.selectedField?.widthM ?? 68.0)
        .clamp(15.0, 120.0)
        .toDouble();
    final fallbackBounds = _phoneFieldBounds(tracks);
    var newest = 0;
    for (final track in tracks) {
      if (track.points.isNotEmpty) {
        newest = math.max(newest, track.points.last.timeMs).toInt();
      }
    }

    final positions = <_LiveTacticalPlayerPosition>[];
    for (final track in tracks) {
      if (track.points.isEmpty) continue;
      final point = track.points.last;
      if (newest > 0 && newest - point.timeMs > 15000) continue;

      double nx;
      double ny;
      final projected = TrackerPitchProjector.projectGps(
        widget.selectedField,
        latitude: point.lat,
        longitude: point.lon,
      );
      if (projected != null && projected.isInside) {
        nx = projected.clampedNx;
        ny = projected.clampedNy;
      } else {
        final lonRange = (fallbackBounds.maxLon - fallbackBounds.minLon).abs();
        final latRange = (fallbackBounds.maxLat - fallbackBounds.minLat).abs();
        nx = lonRange < 0.000001
            ? .5
            : ((point.lon - fallbackBounds.minLon) / lonRange)
                .clamp(.0, 1.0)
                .toDouble();
        ny = latRange < 0.000001
            ? .5
            : ((point.lat - fallbackBounds.minLat) / latRange)
                .clamp(.0, 1.0)
                .toDouble();
      }
      final player = _phonePlayerForTrack(track);
      positions.add(_LiveTacticalPlayerPosition(
        trackKey: track.key,
        playerId: player?.id,
        playerName: player?.name ?? track.playerName,
        number: player?.number,
        role: _liveTacticalRole(player?.position),
        nx: nx,
        ny: ny,
        xM: nx * fieldLength,
        yM: ny * fieldWidth,
        speedKmh: _safeLiveSpeed(track.speedKmh),
        timeMs: point.timeMs,
      ));
    }

    if (positions.isEmpty) {
      return _LiveTacticalSnapshot.empty(
        fieldLengthM: fieldLength,
        fieldWidthM: fieldWidth,
        attackRight: _liveMapProAttackRight,
      );
    }

    final xs = positions.map((p) => p.nx).toList(growable: false);
    final ys = positions.map((p) => p.ny).toList(growable: false);
    final minX = xs.reduce(math.min);
    final maxX = xs.reduce(math.max);
    final minY = ys.reduce(math.min);
    final maxY = ys.reduce(math.max);
    final depthM = (maxX - minX).abs() * fieldLength;
    final widthM = (maxY - minY).abs() * fieldWidth;
    final footprintAreaM2 = math.max(0.0, depthM * widthM).toDouble();
    final hullAreaM2 = _liveTacticalHullArea(
      positions.map((p) => Offset(p.xM, p.yM)).toList(growable: false),
    );
    final pitchArea = math.max(1.0, fieldLength * fieldWidth).toDouble();
    final compactness =
        (100.0 * (1.0 - footprintAreaM2 / pitchArea)).clamp(0.0, 100.0).toDouble();
    final centroidNx = xs.reduce((a, b) => a + b) / xs.length;
    final centroidNy = ys.reduce((a, b) => a + b) / ys.length;

    var nearestSum = 0.0;
    var nearestCount = 0;
    for (var i = 0; i < positions.length; i++) {
      var nearest = double.infinity;
      for (var j = 0; j < positions.length; j++) {
        if (i == j) continue;
        final dx = positions[i].xM - positions[j].xM;
        final dy = positions[i].yM - positions[j].yM;
        final distance = math.sqrt(dx * dx + dy * dy);
        if (distance < nearest) nearest = distance;
      }
      if (nearest.isFinite) {
        nearestSum += nearest;
        nearestCount++;
      }
    }
    final avgNearestM = nearestCount == 0 ? 0.0 : nearestSum / nearestCount;

    double? defenseLineNx;
    double? midfieldLineNx;
    double? attackLineNx;
    var formationLabel = '—';
    final defenders = positions.where((p) => p.role == 'def').toList();
    final midfielders = positions.where((p) => p.role == 'mid').toList();
    final attackers = positions.where((p) => p.role == 'att').toList();
    final recognized = defenders.length + midfielders.length + attackers.length;
    double meanNx(List<_LiveTacticalPlayerPosition> list) =>
        list.map((p) => p.nx).reduce((a, b) => a + b) / list.length;

    if (recognized >= math.max(4, positions.length ~/ 2) &&
        defenders.isNotEmpty &&
        midfielders.isNotEmpty &&
        attackers.isNotEmpty) {
      defenseLineNx = meanNx(defenders);
      midfieldLineNx = meanNx(midfielders);
      attackLineNx = meanNx(attackers);
      formationLabel = '${defenders.length}-${midfielders.length}-${attackers.length}';
    } else {
      final centers = _liveTacticalClusterCenters(xs);
      if (centers.length >= 3) {
        final counts = <int>[0, 0, 0];
        for (final value in xs) {
          var best = 0;
          var bestDistance = (value - centers[0]).abs();
          for (var i = 1; i < 3; i++) {
            final distance = (value - centers[i]).abs();
            if (distance < bestDistance) {
              best = i;
              bestDistance = distance;
            }
          }
          counts[best]++;
        }
        if (_liveMapProAttackRight) {
          defenseLineNx = centers[0];
          midfieldLineNx = centers[1];
          attackLineNx = centers[2];
          formationLabel = '≈${counts[0]}-${counts[1]}-${counts[2]}';
        } else {
          defenseLineNx = centers[2];
          midfieldLineNx = centers[1];
          attackLineNx = centers[0];
          formationLabel = '≈${counts[2]}-${counts[1]}-${counts[0]}';
        }
      }
    }

    double? offsideGuideNx;
    final offsideCandidates = defenders.length >= 2 ? defenders : positions;
    if (offsideCandidates.length >= 2) {
      final ordered = List<_LiveTacticalPlayerPosition>.from(offsideCandidates)
        ..sort((a, b) => a.nx.compareTo(b.nx));
      // Это ориентир по собственной защитной линии. При известных позициях
      // берём второго защитника от своих ворот; без ролей — второй крайний
      // игрок команды. Для официального офсайда нужны соперник и момент паса.
      offsideGuideNx = _liveMapProAttackRight
          ? ordered[math.min(1, ordered.length - 1).toInt()].nx
          : ordered[math.max(0, ordered.length - 2).toInt()].nx;
    }

    final defenseMidGapM = defenseLineNx == null || midfieldLineNx == null
        ? null
        : (defenseLineNx - midfieldLineNx).abs() * fieldLength;
    final midAttackGapM = midfieldLineNx == null || attackLineNx == null
        ? null
        : (midfieldLineNx - attackLineNx).abs() * fieldLength;
    final avgSpeedKmh = positions.isEmpty
        ? 0.0
        : positions.map((p) => p.speedKmh).reduce((a, b) => a + b) /
            positions.length;
    final highIntensityPlayers = positions.where((p) => p.speedKmh >= 18.0).length;
    final centerProgressPct = (_liveMapProAttackRight
            ? centroidNx * 100.0
            : (1.0 - centroidNx) * 100.0)
        .clamp(0.0, 100.0)
        .toDouble();
    final defenseLineHeightM = defenseLineNx == null
        ? null
        : (_liveMapProAttackRight
                ? defenseLineNx * fieldLength
                : (1.0 - defenseLineNx) * fieldLength)
            .clamp(0.0, fieldLength)
            .toDouble();
    final lateralBalancePct =
        (100.0 - (centroidNy - .5).abs() * 200.0).clamp(0.0, 100.0).toDouble();
    var leftLanePlayers = 0;
    var centralLanePlayers = 0;
    var rightLanePlayers = 0;
    var ownThirdPlayers = 0;
    var middleThirdPlayers = 0;
    var finalThirdPlayers = 0;
    for (final player in positions) {
      if (player.ny < 1 / 3) {
        leftLanePlayers++;
      } else if (player.ny > 2 / 3) {
        rightLanePlayers++;
      } else {
        centralLanePlayers++;
      }
      final progress = _liveMapProAttackRight ? player.nx : 1.0 - player.nx;
      if (progress < 1 / 3) {
        ownThirdPlayers++;
      } else if (progress > 2 / 3) {
        finalThirdPlayers++;
      } else {
        middleThirdPlayers++;
      }
    }

    final alerts = <_LiveTacticalAlert>[];
    if (defenseMidGapM != null && defenseMidGapM > 23.0) {
      alerts.add(_LiveTacticalAlert(
        level: defenseMidGapM > 30.0 ? 3 : 2,
        title: 'Разрыв защита → полузащита',
        detail: '${defenseMidGapM.toStringAsFixed(1)} м',
        icon: Icons.horizontal_rule_rounded,
      ));
    }
    if (midAttackGapM != null && midAttackGapM > 23.0) {
      alerts.add(_LiveTacticalAlert(
        level: midAttackGapM > 30.0 ? 3 : 2,
        title: 'Разрыв полузащита → атака',
        detail: '${midAttackGapM.toStringAsFixed(1)} м',
        icon: Icons.horizontal_rule_rounded,
      ));
    }
    if (widthM > fieldWidth * .80) {
      alerts.add(_LiveTacticalAlert(
        level: widthM > fieldWidth * .92 ? 2 : 1,
        title: 'Очень широкая структура',
        detail: '${widthM.toStringAsFixed(1)} м',
        icon: Icons.swap_horiz_rounded,
      ));
    }
    if (depthM > fieldLength * .62 || compactness < 55.0) {
      alerts.add(_LiveTacticalAlert(
        level: compactness < 42.0 ? 2 : 1,
        title: 'Команда растянута',
        detail:
            '${depthM.toStringAsFixed(0)}×${widthM.toStringAsFixed(0)} м · компактность ${compactness.toStringAsFixed(0)}%',
        icon: Icons.open_in_full_rounded,
      ));
    }
    if (avgNearestM > 18.0 && positions.length >= 5) {
      alerts.add(_LiveTacticalAlert(
        level: avgNearestM > 23.0 ? 2 : 1,
        title: 'Большие интервалы между игроками',
        detail: 'средний ближайший ${avgNearestM.toStringAsFixed(1)} м',
        icon: Icons.compare_arrows_rounded,
      ));
    }
    if (positions.length >= 7 &&
        (leftLanePlayers - rightLanePlayers).abs() >= 4) {
      alerts.add(_LiveTacticalAlert(
        level: 1,
        title: leftLanePlayers > rightLanePlayers
            ? 'Перегруз левого фланга'
            : 'Перегруз правого фланга',
        detail: '$leftLanePlayers · $centralLanePlayers · $rightLanePlayers',
        icon: Icons.swap_horiz_rounded,
      ));
    }
    if (alerts.isEmpty && positions.length >= 4) {
      alerts.add(const _LiveTacticalAlert(
        level: 0,
        title: 'Структура стабильна',
        detail: 'критических разрывов сейчас нет',
        icon: Icons.verified_rounded,
      ));
    }
    alerts.sort((a, b) => b.level.compareTo(a.level));

    return _LiveTacticalSnapshot(
      fieldLengthM: fieldLength,
      fieldWidthM: fieldWidth,
      attackRight: _liveMapProAttackRight,
      players: positions,
      widthM: widthM,
      depthM: depthM,
      footprintAreaM2: footprintAreaM2,
      hullAreaM2: hullAreaM2,
      compactnessPct: compactness,
      centroidNx: centroidNx,
      centroidNy: centroidNy,
      avgNearestM: avgNearestM,
      defenseLineNx: defenseLineNx,
      midfieldLineNx: midfieldLineNx,
      attackLineNx: attackLineNx,
      offsideGuideNx: offsideGuideNx,
      defenseMidGapM: defenseMidGapM,
      midAttackGapM: midAttackGapM,
      avgSpeedKmh: avgSpeedKmh,
      highIntensityPlayers: highIntensityPlayers,
      centerProgressPct: centerProgressPct,
      defenseLineHeightM: defenseLineHeightM,
      lateralBalancePct: lateralBalancePct,
      leftLanePlayers: leftLanePlayers,
      centralLanePlayers: centralLanePlayers,
      rightLanePlayers: rightLanePlayers,
      ownThirdPlayers: ownThirdPlayers,
      middleThirdPlayers: middleThirdPlayers,
      finalThirdPlayers: finalThirdPlayers,
      formationLabel: formationLabel,
      alerts: alerts,
    );
  }

  void _stopLiveMapReplay({bool rebuild = false}) {
    _liveMapReplayTimer?.cancel();
    _liveMapReplayTimer = null;
    if (!_liveMapProReplayPlaying) return;
    if (rebuild && mounted) {
      setState(() => _liveMapProReplayPlaying = false);
    } else {
      _liveMapProReplayPlaying = false;
    }
  }

  void _toggleLiveMapReplay() {
    if (_liveTacticalReviewMode) {
      _toast('Сначала завершите стоп-кадр и разбор.');
      return;
    }
    if (_liveMapProReplayPlaying) {
      _stopLiveMapReplay(rebuild: true);
      return;
    }
    final range = _teamLiveTimelineRange();
    var cursor = _liveReviewTeamTimeMs;
    if (cursor == null || cursor <= range.startMs || cursor >= range.endMs - 500) {
      cursor = math.max(range.startMs, range.endMs - 30000).toInt();
    }
    setState(() {
      _liveReviewTeamTimeMs = cursor;
      _selectedLiveEventId = null;
      _liveMapProReplayPlaying = true;
    });
    _liveMapReplayTimer?.cancel();
    _liveMapReplayTimer = Timer.periodic(const Duration(milliseconds: 250), (_) {
      if (!mounted || !_liveMapProExpanded || !_liveMapProReplayPlaying) {
        _liveMapReplayTimer?.cancel();
        return;
      }
      final currentRange = _teamLiveTimelineRange();
      final current = _liveReviewTeamTimeMs ?? currentRange.startMs;
      final next = current + (250 * _liveMapProReplaySpeed).round();
      if (next >= currentRange.endMs - 350) {
        _liveMapReplayTimer?.cancel();
        _liveMapReplayTimer = null;
        setState(() {
          _liveMapProReplayPlaying = false;
          _liveReviewTeamTimeMs = null;
          _selectedLiveEventId = null;
        });
        return;
      }
      setState(() {
        _liveReviewTeamTimeMs = next;
        _selectedLiveEventId = null;
      });
    });
  }

  void _shiftLiveMapReplay(int seconds) {
    if (_liveTacticalReviewMode) {
      _toast('Стоп-кадр зафиксирован. Завершите разбор для перемотки.');
      return;
    }
    _stopLiveMapReplay();
    final range = _teamLiveTimelineRange();
    final base = _liveReviewTeamTimeMs ?? range.endMs;
    final target = (base + seconds * 1000).clamp(range.startMs, range.endMs).toInt();
    if (target >= range.endMs - 500) {
      _returnTeamToLive();
      return;
    }
    setState(() {
      _liveReviewTeamTimeMs = target;
      _selectedLiveEventId = null;
      _liveReviewPlayerId = null;
      _liveReviewTimeMs = null;
      _showLoadHotPoints = true;
    });
  }

  void _cycleLiveMapReplaySpeed() {
    const speeds = <double>[.5, 1.0, 2.0, 4.0];
    var index = speeds.indexWhere((value) => value == _liveMapProReplaySpeed);
    if (index < 0) index = 1;
    setState(() => _liveMapProReplaySpeed = speeds[(index + 1) % speeds.length]);
  }


  void _openLiveMapPro() {
    setState(() {
      _liveMapProExpanded = true;
      _liveMapProJournalVisible = true;
      _teamLivePanelJournal = true;
      _showSelectedPlayerDetail = false;
    });
  }

  void _closeLiveMapPro() {
    if (!_liveMapProExpanded) return;
    _stopLiveMapReplay();
    setState(() {
      _liveMapProExpanded = false;
      _liveTacticalReviewMode = false;
      _liveTacticalFreezeTracks = <_RuntimeTrack>[];
      _liveReviewTeamTimeMs = null;
    });
    unawaited(_flushLiveTacticalReviewSave());
  }

