  List<TrackerGeoTrack> _liveGeoTracksForMap(List<_RuntimeTrack> tracks) {
    const colors = <Color>[
      Color(0xFF16794B),
      Color(0xFF2879D0),
      Color(0xFFF08A24),
      Color(0xFF8B5CC7),
      Color(0xFFD84C5A),
      Color(0xFF078F95),
    ];
    final result = <TrackerGeoTrack>[];
    for (var index = 0; index < tracks.length; index++) {
      final track = tracks[index];
      final player = _phonePlayerForTrack(track);
      result.add(
        TrackerGeoTrack(
          id: track.key,
          name: player?.name ?? track.playerName,
          avatar: player?.avatar ?? track.avatar,
          color: colors[index % colors.length],
          selected: widget.selectedPlayer != null &&
              player != null &&
              (player.id == widget.selectedPlayer!.id ||
                  player.identityIds.contains(widget.selectedPlayer!.id)),
          points: track.points
              .where((point) => point.acceptedForMetrics)
              .map(
                (point) => TrackerGeoPoint(
                  latitude: point.lat,
                  longitude: point.lon,
                  timeMs: point.timeMs,
                  speedKmh: point.speedKmh,
                ),
              )
              .toList(growable: false),
        ),
      );
    }
    return result;
  }

  Widget _liveMapProMapCanvas({required bool compact, bool embedded = false}) {
    if (!_activity.requiresField &&
        _liveGeoBaseLayer == TrackerGeoBaseLayer.pitch) {
      return Stack(
        children: [
          Positioned.fill(child: _fieldCard()),
          if (!embedded)
            Positioned(left: 10, top: 10, right: 100, child: _liveMapProHud()),
          if (!embedded)
            Positioned(top: 10, right: 10, child: _liveMapProWindowButtons()),
        ],
      );
    }

    final liveTracks = _sidePanelTracks();
    final tracks = _liveTacticalReviewMode &&
            _liveTacticalFreezeTracks.isNotEmpty
        ? _liveTacticalFreezeTracks
        : liveTracks;
    final selected = _selectedLiveEvent();
    final tactical = _liveMapTacticalSnapshot(tracks);
    final geoTracks = _liveGeoBaseLayer == TrackerGeoBaseLayer.pitch ||
            !Tracker2GisMapLayer.hasMapKey
        ? const <TrackerGeoTrack>[]
        : _liveGeoTracksForMap(tracks);
    return ClipRRect(
      // V203: тот же радиус рабочей карты, что в полном разборе матча.
      borderRadius: BorderRadius.circular(16),
      child: LayoutBuilder(
          builder: (context, fieldBox) {
            final size = fieldBox.biggest;
            final bounds = _phoneFieldBounds(tracks);
            final pitch = _phoneFieldPitch(size);
            final markerTracks = tracks
                .where((track) => track.points.isNotEmpty)
                .take(16)
                .toList(growable: false);

            final fieldLayer = Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Positioned.fill(
                  child: CustomPaint(
                    painter: _RuntimeFieldPainter(
                      field: widget.selectedField,
                      motionCache: _runtimeMotionEnabled ? _runtimeMotionCache : null,
                      repaint: _runtimeMotionController,
                      tracks: tracks,
                      showVectors: _showVectors,
                      showHeatmap: _showHeatmap,
                      showTrace: _showTrace,
                      showLabels: false,
                      showLoadHotPoints: _showLoadHotPoints,
                      showTeamShapeConnections: _showTeamShapeConnections,
                      showPassingNetwork: _liveMapProShowPassingNetwork,
                      showTacticalLines: _liveMapProShowTacticalLines,
                      showOffsideGuide: _liveMapProShowOffsideGuide,
                      showControlZones: _liveMapProShowControlZones,
                      showTeamCenter: _liveMapProShowTeamCenter,
                      showPitchZones: _liveMapProShowPitchZones,
                      tacticalSnapshot: tactical,
                      warningEvents: _liveMapProShowEvents
                          ? _fieldLiveEvents()
                          : const <TrackerLiveEventModel>[],
                      selectedWarningEventId:
                          _liveMapProShowEvents ? _selectedLiveEventId : null,
                    ),
                    child: const SizedBox.expand(),
                  ),
                ),
                if (_showPlayerAvatars)
                  for (final track in markerTracks)
                    _liveMapProPlayerMarker(
                      track: track,
                      pitch: pitch,
                      bounds: bounds,
                      focused: widget.selectedPlayer != null &&
                          _phonePlayerForTrack(track)?.id ==
                              widget.selectedPlayer!.id,
                    ),
              ],
            );
            final baseLayer = _liveGeoBaseLayer == TrackerGeoBaseLayer.pitch
                ? fieldLayer
                : Tracker2GisMapLayer(
                    key: ValueKey<String>(
                      'live-map-${_liveGeoBaseLayer.name}',
                    ),
                    layer: _liveGeoBaseLayer,
                    tracks: geoTracks,
                    cursorTimeMs: _liveTacticalReviewMode
                        ? _liveReviewTeamTimeMs
                        : null,
                    live: _runtimeMotionEnabled,
                    followLatest: _runtimeMotionEnabled,
                    interactive: !_liveTacticalReviewMode,
                    perspective3d: _liveMapProPerspective3d,
                    field: widget.selectedField,
                    rotationDeg: _liveGeoRotationDeg,
                    showPlayers: _showPlayerAvatars,
                    showLabels: _liveMapProShowNames,
                    showTrace: _liveGeoShowTracks,
                    routeWindowMs: 60000,
                  );

            return Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Positioned.fill(
                  child: _LivePitchPerspective(
                    enabled: _liveGeoBaseLayer == TrackerGeoBaseLayer.pitch &&
                        _liveMapProPerspective3d,
                    child: TgAnalyticsOverlay(
                      controller: _liveTacticalReviewController,
                      enabled: _liveTacticalReviewMode,
                      cursorElapsedMs: math.max(
                        0,
                        (_liveReviewTeamTimeMs ??
                                DateTime.now().millisecondsSinceEpoch) -
                            _liveTacticalReviewStartMs(),
                      ),
                      child: baseLayer,
                    ),
                  ),
                ),
                if (!embedded)
                  Positioned(
                    left: 10,
                    top: 10,
                    right: 104,
                    child: _liveMapProHud(),
                  ),
                if (!embedded)
                  Positioned(
                    top: 10,
                    right: 10,
                    child: _liveMapProWindowButtons(),
                  ),
                if (!embedded)
                  Positioned(
                    left: 10,
                    top: 54,
                    child: TrackerGeoLayerStrip(
                    value: _liveGeoBaseLayer,
                    compact: compact,
                    onChanged: (value) => setState(() {
                      _liveGeoBaseLayer = value;
                      if (value != TrackerGeoBaseLayer.pitch) {
                        _liveMapProPerspective3d = false;
                      }
                    }),
                  ),
                ),
                if (_liveMapProShowTacticalRadar && tactical.players.length >= 2)
                  Positioned(
                    right: 12,
                    bottom: _liveTacticalReviewMode
                        ? 154
                        : (_liveMapProPerspective3d ? 106 : 12),
                    child: _liveMapProTacticalRadar(tactical),
                  ),
                if (!embedded)
                  Positioned(
                    left: 12,
                    bottom: 12,
                    child: _liveMapProReplayControls(),
                  ),
                if (_isReviewingTeamLive)
                  Positioned(
                    left: 12,
                    bottom: 54,
                    child: _liveMapProReviewBadge(selected),
                  ),
                if (_liveTacticalReviewMode)
                  Positioned(
                    left: 12,
                    right: 12,
                    bottom: 104,
                    height: 40,
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(.94),
                        borderRadius: BorderRadius.circular(10),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withOpacity(.10),
                            blurRadius: 12,
                            spreadRadius: -5,
                            offset: const Offset(0, 5),
                          ),
                        ],
                      ),
                      child: TgAnalyticsToolbar(
                        controller: _liveTacticalReviewController,
                        teamName: widget.teamName,
                        teamPlayers: widget.players
                            .map((player) => player.toJson())
                            .toList(growable: false),
                      ),
                    ),
                  ),
                if (!embedded)
                  Positioned(
                    right: 12,
                    top: 54,
                    child: TrackerGeoMapDock(
                    layer: _liveGeoBaseLayer,
                    rotationDeg: _liveGeoRotationDeg,
                    compact: compact,
                    expandUp: false,
                    showTrace:
                        _liveGeoBaseLayer == TrackerGeoBaseLayer.pitch
                            ? null
                            : _liveGeoShowTracks,
                    onShowTraceChanged: (value) => setState(() {
                      _liveGeoShowTracks = value;
                    }),
                    onRotationChanged: (value) => setState(() {
                      _liveGeoRotationDeg = value;
                    }),
                    onLayerChanged: (value) => setState(() {
                      _liveGeoBaseLayer = value;
                      if (value != TrackerGeoBaseLayer.pitch) {
                        _liveMapProPerspective3d = false;
                      }
                    }),
                  ),
                ),
              ],
            );
          },
        ),
    );
  }

