  int? _liveMapProHeartRate(int playerId) {
    final reviewMs = _liveReviewTeamTimeMs;
    if (reviewMs == null || reviewMs <= 0) return _heartRateForPlayerId(playerId)?.bpm;
    final history = _liveHrHistoryByPlayer[playerId];
    if (history == null || history.isEmpty) return null;
    _LiveHrPoint? best;
    for (final point in history) {
      if (point.timeMs <= reviewMs && (best == null || point.timeMs > best.timeMs)) {
        best = point;
      }
    }
    return best?.bpm;
  }

  Widget _liveMapProPlayerMarker({
    required _RuntimeTrack track,
    required Rect pitch,
    required _MapBounds bounds,
    required bool focused,
  }) {
    final point = track.points.last;
    final position = _phoneProjectFieldPoint(point, pitch, bounds);
    final player = _phonePlayerForTrack(track);
    final avatarUrl = _trackerAbsolutePhotoUrl(player?.avatar ?? track.avatar);
    final markerSize = focused ? 40.0 : 34.0;
    const infoWidth = 144.0;
    final showInfo = _liveMapProShowNames ||
        _liveMapProShowSpeed ||
        _liveMapProShowHeart ||
        _liveMapProShowLoad ||
        _liveMapProShowDistance ||
        _liveMapProShowSprints;
    final totalWidth = markerSize + (showInfo ? infoWidth + 5 : 0);
    final left = (position.dx - markerSize / 2)
        .clamp(pitch.left - 2, math.max(pitch.left - 2, pitch.right - totalWidth + 2))
        .toDouble();
    final top = (position.dy - markerSize / 2)
        .clamp(pitch.top - 2, math.max(pitch.top - 2, pitch.bottom - 60))
        .toDouble();
    final playerId = player?.id;
    final heart = playerId == null ? null : _liveMapProHeartRate(playerId);
    final session = playerId == null ? null : _sessionForPlayer(playerId);
    final local = playerId == null ? null : _localTrackForPlayer(playerId);
    final reviewing = _isReviewingTeamLive;
    final load = reviewing
        ? track.loadScore
        : math.max(session?.loadScore ?? 0.0, local?.loadScore ?? track.loadScore);
    final distance = reviewing
        ? track.totalDistanceM
        : math.max(session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? track.totalDistanceM);
    final sprints = reviewing
        ? track.sprintCount
        : math.max(session?.sprintCount ?? 0, local?.sprintCount ?? track.sprintCount);

    final metrics = <String>[];
    if (_liveMapProShowSpeed) metrics.add('${track.speedKmh.toStringAsFixed(1)} км/ч');
    if (_liveMapProShowHeart) metrics.add(heart == null ? '♥ —' : '♥ $heart');
    if (_liveMapProShowLoad) metrics.add('Н ${load.toStringAsFixed(0)}');
    if (_liveMapProShowDistance) metrics.add('${(distance / 1000).toStringAsFixed(2)} км');
    if (_liveMapProShowSprints) metrics.add('⚡ $sprints');

    return AnimatedPositioned(
      key: ValueKey<String>('live_map_pro_${track.key}'),
      duration: const Duration(milliseconds: 780),
      curve: Curves.easeInOutCubic,
      left: left,
      top: top,
      width: totalWidth,
      height: 60,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: player == null
            ? null
            : () {
                widget.onSelectPlayer?.call(player);
                HapticFeedback.selectionClick();
              },
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Container(
              width: markerSize,
              height: markerSize,
              padding: EdgeInsets.all(focused ? 2 : 1.4),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: Colors.white,
                border: Border.all(
                    color: focused ? _OF.green : Colors.white,
                    width: focused ? 2.1 : 1.4),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(.18),
                    blurRadius: 8,
                    spreadRadius: -3,
                    offset: const Offset(0, 3),
                  ),
                ],
              ),
              child: ClipOval(
                child: avatarUrl.isNotEmpty
                    ? Image.network(
                        avatarUrl,
                        fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => _phoneFieldInitials(track),
                      )
                    : _phoneFieldInitials(track),
              ),
            ),
            if (showInfo) ...[
              const SizedBox(width: 5),
              Container(
                width: infoWidth,
                padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 5),
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(.94),
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(color: _OF.line),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    if (_liveMapProShowNames)
                      Text(
                        '${player?.number ?? ''}${player?.number == null ? '' : ' · '}${_compactPlayerName(player?.name ?? track.playerName)}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: _OFText.body(
                          size: 8.3,
                          color: _OF.text,
                          weight: FontWeight.w700,
                        ),
                      ),
                    if (_liveMapProShowNames && metrics.isNotEmpty)
                      const SizedBox(height: 2),
                    if (metrics.isNotEmpty)
                      Text(
                        metrics.join('  ·  '),
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: _OFText.body(
                          size: 7.8,
                          color: _OF.muted,
                          weight: FontWeight.w600,
                        ),
                      ),
                  ],
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

