  Widget _wholeTeamTablePanel({bool compact = false, bool phoneCards = false}) {
    final width = MediaQuery.maybeOf(context)?.size.width ?? 9999;
    final hideWindowAction = width < 1180;
    final players = widget.players;
    final rows = _sessions.isNotEmpty ? _sessions : <TrackerLiveSessionModel>[];
    final onlineCount = rows.where((s) => s.isOnline).length;
    final journalEvents = _liveEvents
        .where((event) => event.timeMs > 0)
        .toList(growable: false)
      ..sort((a, b) => b.timeMs.compareTo(a.timeMs));
    final redCount = journalEvents.where((event) => event.isRed).length;
    final journalMode = _teamLivePanelJournal;

    return _ofPanel(
      title: journalMode
          ? (phoneCards
              ? 'Журнал Live'
              : (compact ? 'Журнал Live' : 'Журнал / моменты Live'))
          : (phoneCards
              ? 'Все игроки команды'
              : (compact ? 'Игроки Live' : 'Игроки / live-данные')),
      subtitle: journalMode
          ? (journalEvents.isEmpty
              ? 'моментов пока нет'
              : (compact
                  ? '${journalEvents.length} · красных $redCount'
                  : '${journalEvents.length} событий · $redCount красных'))
          : (_running
              ? (compact
                  ? '$onlineCount/$activeSessionCount онлайн'
                  : '$onlineCount/$activeSessionCount онлайн · подключённые сверху')
              : (compact ? 'Командная сводка' : 'Командная сводка · Анализ')),
      actions: [
        _teamLivePanelModeButton(
          label: 'Игроки',
          icon: Icons.groups_rounded,
          active: !journalMode,
          onTap: () => setState(() {
            _teamLivePanelJournal = false;
            _showSelectedPlayerDetail = false;
          }),
        ),
        const SizedBox(width: 4),
        _teamLivePanelModeButton(
          label: 'Журнал',
          icon: Icons.timeline_rounded,
          active: journalMode,
          badge: redCount > 0 ? redCount : null,
          dangerBadge: redCount > 0,
          onTap: () => setState(() {
            _teamLivePanelJournal = true;
            _showSelectedPlayerDetail = false;
          }),
        ),
      ],
      child: journalMode
          ? _teamLiveJournalContent(
              journalEvents,
              compact: compact,
              phoneCards: phoneCards,
            )
          : (phoneCards
              ? _phonePlayersCardsList(players, rows)
              : Column(children: [
                  _teamTableHeader(compact: compact),
                  Expanded(
                    child: players.isNotEmpty
                        ? ListView.builder(
                            padding: const EdgeInsets.only(bottom: 132),
                            physics: const BouncingScrollPhysics(
                                parent: AlwaysScrollableScrollPhysics()),
                            itemCount: players.length,
                            itemBuilder: (_, i) => _teamTableRowFromPlayer(
                                players[i], i,
                                compact: compact),
                          )
                        : (rows.isEmpty
                            ? _teamTableFallback(compact: compact)
                            : ListView.builder(
                                padding: const EdgeInsets.only(bottom: 132),
                                physics: const BouncingScrollPhysics(
                                    parent: AlwaysScrollableScrollPhysics()),
                                itemCount: rows.length,
                                itemBuilder: (_, i) => _teamTableRowFromSession(
                                    rows[i], i,
                                    compact: compact),
                              )),
                  ),
                ])),
    );
  }

