  Widget _phonePlayersCardsList(
      List<TrackerPlayerOption> players, List<TrackerLiveSessionModel> rows) {
    if (players.isEmpty && rows.isEmpty) {
      return const Center(
          child: Text('Игроки и live-данные появятся после старта мониторинга.',
              textAlign: TextAlign.center,
              style: TextStyle(
                  color: _OF.muted,
                  fontSize: AppTypography.secondarySize,
                  fontWeight: FontWeight.w700)));
    }
    final sortedPlayers = List<TrackerPlayerOption>.from(players);
    sortedPlayers.sort((a, b) {
      final aOnline = _isPlayerOnlineLive(a.id) ? 1 : 0;
      final bOnline = _isPlayerOnlineLive(b.id) ? 1 : 0;
      if (aOnline != bOnline) return bOnline.compareTo(aOnline);
      final aSelected = widget.selectedPlayer?.id == a.id ? 1 : 0;
      final bSelected = widget.selectedPlayer?.id == b.id ? 1 : 0;
      if (aSelected != bSelected) return bSelected.compareTo(aSelected);
      return (int.tryParse(a.number ?? '') ?? 9999)
          .compareTo(int.tryParse(b.number ?? '') ?? 9999);
    });
    final sortedRows = List<TrackerLiveSessionModel>.from(rows);
    sortedRows.sort((a, b) {
      final aOnline = a.isOnline ? 1 : 0;
      final bOnline = b.isOnline ? 1 : 0;
      if (aOnline != bOnline) return bOnline.compareTo(aOnline);
      return b.loadScore.compareTo(a.loadScore);
    });
    final itemCount =
        sortedPlayers.isNotEmpty ? sortedPlayers.length : sortedRows.length;
    return ListView.separated(
      padding: const EdgeInsets.fromLTRB(6, 5, 6, 8),
      itemCount: itemCount,
      separatorBuilder: (_, __) => const SizedBox(height: 4),
      itemBuilder: (_, i) {
        if (sortedPlayers.isNotEmpty)
          return _phonePlayerCardFromPlayer(sortedPlayers[i], i);
        return _phonePlayerCardFromSession(sortedRows[i], i);
      },
    );
  }

  Widget _phonePlayerCardFromPlayer(TrackerPlayerOption p, int i) {
    final session = _sessionForPlayer(p.id);
    final local = _localTrackForPlayer(p.id);
    final selected = widget.selectedPlayer?.id == p.id;
    final live = _liveTelemetryActive;
    return _phonePlayerCard(
      player: p,
      number: '${p.number ?? i + 1}',
      name: p.name,
      online: live && (_isPlayerOnlineLive(p.id) ||
          session?.isOnline == true ||
          (selected && (_mainTrack?.points.isNotEmpty ?? false))),
      distance: live ? math.max(
          session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? 0.0) : 0.0,
      metersPerMin: live ? math.max(
          session?.metersPerMinute ?? 0.0, local?.metersPerMinute ?? 0.0) : 0.0,
      load: live ? math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0) : 0.0,
      max: live ? math.max(_safeLiveSpeed(session?.maxSpeedKmh ?? 0.0),
          _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0)) : 0.0,
      sprint: live ? math.max(
          session?.sprintDistanceM ?? 0.0, local?.sprintDistanceM ?? 0.0) : 0.0,
      heartRateBpm: live ? _heartRateForPlayerId(p.id)?.bpm : null,
      highlight: selected,
      monitoring: _isPlayerInMonitorGrid(p.id),
      onTap: () => _selectPlayerAndOpenDetails(p),
      onAnalyzeTap: () => _toggleMonitorPlayer(p),
      onConnectTap: () => _openDevicesForPlayer(p),
    );
  }

  Widget _phonePlayerCardFromSession(TrackerLiveSessionModel s, int i) {
    final playerId = _resolvedPlayerIdForSession(s);
    final local = _localTrackForPlayer(playerId);
    final player = _playerForSession(s);
    final option = player ??
        TrackerPlayerOption(
            id: playerId ?? 0,
            name: _sessionDisplayName(s),
            avatar: s.avatarUrl,
            number: _sessionDisplayNumber(s, i));
    final live = _liveTelemetryActive;
    return _phonePlayerCard(
      player: option,
      number: _sessionDisplayNumber(s, i),
      name: option.name,
      online: live && (s.isOnline || _isPlayerOnlineLive(option.id)),
      distance: live ? math.max(s.totalDistanceM, local?.totalDistanceM ?? 0.0) : 0.0,
      metersPerMin: live ? math.max(s.metersPerMinute, local?.metersPerMinute ?? 0.0) : 0.0,
      load: live ? math.max(s.loadScore, local?.loadScore ?? 0.0) : 0.0,
      max: live ? math.max(_safeLiveSpeed(s.maxSpeedKmh),
          _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0)) : 0.0,
      sprint: live ? math.max(s.sprintDistanceM, local?.sprintDistanceM ?? 0.0) : 0.0,
      heartRateBpm: live ? _heartRateForPlayerId(option.id)?.bpm : null,
      highlight: widget.selectedPlayer?.id == option.id,
      monitoring: _isPlayerInMonitorGrid(option.id),
      onTap: () => _selectPlayerAndOpenDetails(option),
      onAnalyzeTap: () => _toggleMonitorPlayer(option),
      onConnectTap: () => _openDevicesForPlayer(option),
    );
  }

  Widget _phonePlayerCard({
    required TrackerPlayerOption? player,
    required String number,
    required String name,
    required bool online,
    required double distance,
    required double metersPerMin,
    required double load,
    required double max,
    required double sprint,
    required int? heartRateBpm,
    required bool highlight,
    required bool monitoring,
    required VoidCallback? onTap,
    required VoidCallback? onAnalyzeTap,
    required VoidCallback? onConnectTap,
  }) {
    final mark = _loadMarkLabel(load, heartRateBpm: heartRateBpm);
    final playerId = player?.id;
    final gpsReady = player != null
        ? _gpsChannelReadyForPlayer(player)
        : (playerId != null && widget.connectedTeamPlayerIds.contains(playerId));
    final gpsBound = _deviceForPlayer(playerId) != null;
    final connectionText = online
        ? 'онлайн · данные обновляются'
        : (gpsReady
            ? (_running
                ? 'Live запущен · ждём первый GPS'
                : 'BLE готов · ждёт Старт Live')
            : (gpsBound ? 'GPS привязан · подключите BLE' : 'GPS не назначен'));
    return Material(
      color: Colors.transparent,
      borderRadius: BorderRadius.circular(4),
      child: _NoHoverTap(
        onTap: onTap,
        borderRadius: BorderRadius.circular(4),
        child: Container(
          padding: const EdgeInsets.all(7),
          decoration: BoxDecoration(
            color: highlight ? const Color(0xFFFFF8F1) : Colors.white,
            borderRadius: BorderRadius.circular(4),
            border: Border.all(
                color: highlight ? _OF.orange.withOpacity(.34) : _OF.line),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Stack(
                    clipBehavior: Clip.none,
                    children: [
                      _playerAvatarCircle(
                          player: player,
                          radius: 18,
                          online: online || highlight),
                      Positioned(
                        right: -4,
                        bottom: -4,
                        child: Container(
                          width: 18,
                          height: 18,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: highlight ? _OF.orange : Colors.white,
                            shape: BoxShape.circle,
                            border: Border.all(
                                color: online ? _OF.greenBorder : _OF.line),
                          ),
                          child: Text(number,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                  color: highlight ? Colors.white : _OF.green,
                                  fontSize: AppTypography.menuGroupSize,
                                  fontWeight: FontWeight.w700)),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: _OF.text,
                                fontSize: AppTypography.secondarySize,
                                fontWeight: FontWeight.w700)),
                        Text(connectionText,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                                color:
                                    online || gpsReady ? _OF.green : _OF.muted2,
                                fontSize: AppTypography.menuGroupSize,
                                fontWeight: FontWeight.w700)),
                      ],
                    ),
                  ),
                  _deviceLinkRowButton(
                    compact: true,
                    gpsAssigned: gpsBound,
                    gpsConnected: gpsReady,
                    heartAssigned: player != null && _heartDeviceForPlayer(player.id) != null,
                    heartConnected: player != null && _heartRateForPlayerId(player.id) != null,
                    onTap: onConnectTap,
                  ),
                  const SizedBox(width: 4),
                  _analysisRowButton(
                      compact: true,
                      highlighted: monitoring,
                      onTap: onAnalyzeTap),
                ],
              ),
              const SizedBox(height: 6),
              Wrap(
                spacing: 5,
                runSpacing: 5,
                children: [
                  _phoneStatChip('Дист.', '${distance.toStringAsFixed(0)} м'),
                  _phoneStatChip('м/мин', metersPerMin.toStringAsFixed(1)),
                  _phoneStatChip('Max', '${max.toStringAsFixed(1)} км/ч'),
                  _phoneStatChip(
                      'Пульс', heartRateBpm == null ? '—' : '$heartRateBpm'),
                  _phoneStatChip('Нагр.', load.toStringAsFixed(0)),
                  _phoneStatChip('Метка', mark),
                  _phoneStatChip('SPR', sprint.toStringAsFixed(0)),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }

