      {required TrackerPlayerOption? player,
      required String number,
      required String name,
      required double distance,
      required double metersPerMin,
      required double load,
      required double max,
      required double hir,
      required double vhir,
      required double sprint,
      required num accel,
      required num decel,
      required num cod,
      required int? heartRateBpm,
      required bool compact,
      required bool highlight,
      required bool monitoring,
      VoidCallback? onTap,
      VoidCallback? onAnalyzeTap,
      VoidCallback? onConnectTap}) {
    final displayName = compact ? _compactPlayerName(name) : name;
    final mark = _loadMarkLabel(load, heartRateBpm: heartRateBpm);
    final values = compact
        ? <String>[
            number,
            displayName,
            distance.toStringAsFixed(0),
            heartRateBpm == null ? '—' : '$heartRateBpm',
            load.toStringAsFixed(0),
            mark
          ]
        : <String>[
            number,
            displayName,
            distance.toStringAsFixed(0),
            metersPerMin.toStringAsFixed(1),
            max.toStringAsFixed(1),
            heartRateBpm == null ? '—' : '$heartRateBpm',
            load.toStringAsFixed(0),
            mark,
            hir.toStringAsFixed(0),
            sprint.toStringAsFixed(0),
            accel.toStringAsFixed(0),
            decel.toStringAsFixed(0)
          ];
    final gpsAssigned = player != null && _deviceForPlayer(player.id) != null;
    final gpsConnected = player != null && _gpsChannelReadyForPlayer(player);
    final heartAssigned = player != null && _heartDeviceForPlayer(player.id) != null;
    final heartConnected = player != null && _heartRateForPlayerId(player.id) != null;

    Widget playerIdentityCell() {
      return Row(
        children: [
          if (player != null) ...[
            _playerAvatarCircle(
              player: player,
              radius: compact ? 9.5 : 10,
              online: highlight || gpsConnected || heartConnected,
            ),
            const SizedBox(width: 6),
          ],
          Expanded(
            child: Text(
              displayName,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: highlight ? _OF.green : _OF.text,
                fontSize: compact ? 9.2 : 9.4,
                fontWeight: highlight ? FontWeight.w700 : FontWeight.w600,
              ),
            ),
          ),
          const SizedBox(width: 4),
          Tooltip(
            message: gpsConnected
                ? 'GPS подключён'
                : (gpsAssigned ? 'GPS назначен' : 'GPS не назначен'),
            child: Icon(
              Icons.gps_fixed_rounded,
              size: compact ? 11 : 11,
              color: gpsConnected
                  ? _OF.green
                  : (gpsAssigned ? _OF.orange : _OF.muted2.withOpacity(.42)),
            ),
          ),
          const SizedBox(width: 4),
          Tooltip(
            message: heartConnected
                ? 'Кардио подключено'
                : (heartAssigned ? 'Кардио назначено' : 'Кардио не назначено'),
            child: Icon(
              Icons.favorite_rounded,
              size: compact ? 11 : 11,
              color: heartConnected
                  ? _OF.red
                  : (heartAssigned ? _OF.orange : _OF.muted2.withOpacity(.42)),
            ),
          ),
          if (player != null && widget.onManagePlayerDevices != null) ...[
            const SizedBox(width: 5),
            Tooltip(
              message: (!gpsAssigned || !heartAssigned)
                  ? 'Подключить датчики игрока'
                  : 'Открыть устройства игрока',
              child: Material(
                color: (!gpsAssigned || !heartAssigned)
                    ? _OF.greenSoft
                    : _OF.soft,
                borderRadius: BorderRadius.circular(999),
                child: _NoHoverTap(
                  onTap: () {
                    final targetPlayer = player;
                    if (targetPlayer != null) {
                      widget.onManagePlayerDevices?.call(targetPlayer);
                    }
                  },
                  borderRadius: BorderRadius.circular(999),
                  child: SizedBox(
                    width: compact ? 20 : 21,
                    height: compact ? 20 : 21,
                    child: Icon(
                      (!gpsAssigned || !heartAssigned)
                          ? Icons.add_link_rounded
                          : Icons.sensors_rounded,
                      size: compact ? 11.5 : 12,
                      color: (!gpsAssigned || !heartAssigned)
                          ? _OF.green
                          : _OF.muted2,
                    ),
                  ),
                ),
              ),
            ),
          ],
        ],
      );
    }

    final row = Container(
      height: compact ? 36 : 41,
      color: highlight ? _OF.greenSoft.withOpacity(.82) : Colors.white,
      child: Row(children: [
        for (var i = 0; i < values.length; i++)
          Expanded(
            flex: i == 1
                ? (compact ? 7 : 5)
                : ((compact ? i == 5 : i == 7) ? 2 : 1),
            child: Container(
              alignment: i == 1 ? Alignment.centerLeft : Alignment.center,
              padding: EdgeInsets.only(left: i == 1 ? 7 : 0, right: i == 1 ? 4 : 0),
              child: i == 1
                  ? playerIdentityCell()
                  : Text(
                      values[i],
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: (compact ? i == 5 : i == 7)
                            ? _loadMarkColor(load, heartRateBpm: heartRateBpm)
                            : _OF.text,
                        fontSize: compact ? 9.2 : 9.4,
                        fontWeight: (compact ? i == 5 : i == 7)
                            ? FontWeight.w700
                            : FontWeight.w600,
                      ),
                    ),
            ),
          ),
        Container(
          width: compact ? 90 : 112,
          height: double.infinity,
          alignment: Alignment.center,
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              _deviceLinkRowButton(
                compact: compact,
                gpsAssigned: gpsAssigned,
                gpsConnected: gpsConnected,
                heartAssigned: heartAssigned,
                heartConnected: heartConnected,
                onTap: onConnectTap,
              ),
              const SizedBox(width: 8),
              _analysisRowButton(
                  compact: compact,
                  highlighted: monitoring,
                  onTap: onAnalyzeTap ?? onTap),
            ],
          ),
        ),
      ]),
    );
    return Material(
        color: Colors.transparent,
        child: _NoHoverTap(
            onTap: onTap,
            hoverColor: _OF.greenSoft.withOpacity(.45),
            splashColor: _OF.greenSoft,
            child: row));
  }


  Widget _deviceLinkRowButton({
    required bool compact,
    required bool gpsAssigned,
    required bool gpsConnected,
    required bool heartAssigned,
    required bool heartConnected,
    VoidCallback? onTap,
  }) {
    final needsAttention = !(gpsConnected && heartConnected);
    final tooltip = gpsConnected && heartConnected
        ? 'Открыть экран устройств'
        : (!gpsAssigned && !heartAssigned)
            ? 'Назначить GPS / кардио'
            : (!gpsConnected || !heartConnected)
                ? 'Подключить датчики / открыть устройства'
                : 'Открыть экран устройств';
    final bg = needsAttention ? _OF.orange.withOpacity(.10) : _OF.soft;
    final fg = needsAttention ? _OF.orange : _OF.muted2;
    final size = compact ? 26.0 : 27.0;
    return Tooltip(
      message: tooltip,
      child: Material(
        color: bg,
        shape: const CircleBorder(),
        child: _NoHoverTap(
          onTap: onTap,
          borderRadius: BorderRadius.circular(999),
          child: Container(
            width: size,
            height: size,
            alignment: Alignment.center,
            decoration: const BoxDecoration(shape: BoxShape.circle),
            child: Icon(Icons.sensors_rounded, size: compact ? 13.5 : 13, color: fg),
          ),
        ),
      ),
    );
  }

  void _openDevicesForPlayer(TrackerPlayerOption? player) {
    if (player != null) {
      widget.onSelectPlayer?.call(player);
    }
    widget.onManageTrackers?.call();
  }

