      {required bool compact, required bool highlighted, VoidCallback? onTap}) {
    if (compact) {
      return Tooltip(
        message: highlighted ? 'Убрать live-окно' : 'Добавить live-окно',
        child: Material(
          color: highlighted ? _OF.green : _OF.greenSoft,
          shape: const CircleBorder(),
          child: _NoHoverTap(
            onTap: onTap,
            borderRadius: BorderRadius.circular(999),
            child: Container(
              width: 26,
              height: 26,
              alignment: Alignment.center,
              decoration: const BoxDecoration(shape: BoxShape.circle),
              child: Icon(highlighted ? Icons.check_rounded : Icons.add_rounded,
                  size: 13.5, color: highlighted ? Colors.white : _OF.green),
            ),
          ),
        ),
      );
    }
    return Material(
      color: highlighted ? _OF.green : _OF.greenSoft,
      borderRadius: BorderRadius.circular(999),
      child: _NoHoverTap(
        onTap: onTap,
        borderRadius: BorderRadius.circular(999),
        child: Container(
          height: 27,
          padding: const EdgeInsets.symmetric(horizontal: 10),
          alignment: Alignment.center,
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(highlighted ? Icons.check_rounded : Icons.add_rounded,
                  size: 12, color: highlighted ? Colors.white : _OF.green),
              const SizedBox(width: 4),
              Text(highlighted ? 'Окно' : 'Добавить',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                      color: highlighted ? Colors.white : _OF.green,
                      fontSize: AppTypography.secondarySize,
                      fontWeight: FontWeight.w700)),
            ],
          ),
        ),
      ),
    );
  }

  void _selectPlayerAndOpenDetails(TrackerPlayerOption player) {
    if (!_running) _blockServerAutoRestoreAfterPlayerPick = true;
    widget.onSelectPlayer?.call(player);
    final width = MediaQuery.maybeOf(context)?.size.width ?? 9999;
    if (width >= 720) {
      // На планшете/ПК подробности открываются внутри правой панели.
      // Кнопка «Все игроки» возвращает live-таблицу без закрытия Live.
      if (mounted) setState(() => _showSelectedPlayerDetail = true);
      return;
    }
    if (_phoneLiveSheetVisible) {
      Navigator.of(context).maybePop();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(_openPlayerLiveDetails(player));
      });
      return;
    }
    unawaited(_openPlayerLiveDetails(player));
  }

  void _selectPlayerForAnalytics(TrackerPlayerOption player) {
    final isPhone = (MediaQuery.maybeOf(context)?.size.width ?? 9999) < 720;
    if (_phoneLiveSheetVisible) {
      Navigator.of(context).maybePop();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        if (isPhone) {
          unawaited(_openPhonePlayerAnalysisSheet(player));
        } else {
          unawaited(_openPlayerLiveDetails(player));
        }
      });
      return;
    }
    if (isPhone) {
      unawaited(_openPhonePlayerAnalysisSheet(player));
    } else {
      unawaited(_openPlayerLiveDetails(player));
    }
  }

  Future<void> _openPlayerLiveDetails(TrackerPlayerOption player) async {
    Timer? refreshTimer;
    var dialogOpen = true;

    await showGeneralDialog<void>(
      context: context,
      barrierDismissible: true,
      barrierLabel: 'Закрыть',
      barrierColor: Colors.black.withOpacity(.20),
      transitionDuration: const Duration(milliseconds: 180),
      pageBuilder: (dialogContext, animation, secondaryAnimation) {
        return StatefulBuilder(
          builder: (context, setSheetState) {
            refreshTimer ??=
                Timer.periodic(const Duration(milliseconds: 900), (_) {
              if (dialogOpen && mounted) setSheetState(() {});
            });
            final size = MediaQuery.of(context).size;
            final bool phone = size.width < 720;
            final bool tablet = size.width >= 760 && size.width < 1280;
            final double width = phone
                ? size.width
                : (tablet
                    ? math.min(880.0, size.width * .82)
                    : math.min(1040.0, size.width * .92));
            final double height = phone
                ? size.height
                : (tablet
                    ? math.min(660.0, size.height * .86)
                    : math.min(720.0, size.height * .88));
            return SafeArea(
              bottom: !phone,
              child: Align(
                alignment: phone
                    ? Alignment.center
                    : (tablet ? Alignment.centerRight : Alignment.center),
                child: Padding(
                  padding: phone
                      ? EdgeInsets.zero
                      : EdgeInsets.only(
                          left: tablet ? 14 : 18,
                          right: tablet ? 18 : 18,
                          top: 18,
                          bottom: 18),
                  child: Material(
                    color: Colors.white,
                    elevation: phone ? 0 : 18,
                    shadowColor: Colors.black.withOpacity(.07),
                    borderRadius: BorderRadius.circular(phone ? 0 : 24),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(phone ? 0 : 24),
                      child: SizedBox(
                        width: width,
                        height: height,
                        child: _playerLiveDetailsContent(player,
                            onClose: () => Navigator.of(dialogContext).pop()),
                      ),
                    ),
                  ),
                ),
              ),
            );
          },
        );
      },
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        final curved =
            CurvedAnimation(parent: animation, curve: Curves.easeOutCubic);
        return FadeTransition(
            opacity: curved,
            child: SlideTransition(
                position:
                    Tween<Offset>(begin: const Offset(.06, 0), end: Offset.zero)
                        .animate(curved),
                child: child));
      },
    ).whenComplete(() {
      dialogOpen = false;
      refreshTimer?.cancel();
    });
  }

  Widget _playerLiveDetailsContent(TrackerPlayerOption player,
      {required VoidCallback onClose}) {
    final local = _localTrackForPlayer(player.id);
    final session = _sessionForPlayer(player.id);
    final displayTrack = _displayTrackForPlayer(player);
    final online = session?.isOnline == true ||
        (local != null && local.points.isNotEmpty && _running);
    final speed = _currentLiveSpeed(
      local: local,
      serverSpeed: session?.speedKmh ?? 0.0,
    );
    final distance =
        math.max(session?.totalDistanceM ?? 0.0, local?.totalDistanceM ?? 0.0);
    final mpm = math.max(
        session?.metersPerMinute ?? 0.0, local?.metersPerMinute ?? 0.0);
    final maxSpeed = math.max(_safeLiveSpeed(session?.maxSpeedKmh ?? 0.0),
        _safeLiveSpeed(local?.maxSpeedKmh ?? 0.0));
    final load = math.max(session?.loadScore ?? 0.0, local?.loadScore ?? 0.0);
    final hir =
        math.max(session?.hirDistanceM ?? 0.0, local?.hirDistanceM ?? 0.0);
    final vhir =
        math.max(session?.vhirDistanceM ?? 0.0, local?.vhirDistanceM ?? 0.0);
    final sprint = math.max(
        session?.sprintDistanceM ?? 0.0, local?.sprintDistanceM ?? 0.0);
    final accel = math.max(session?.accelCount ?? 0, local?.accelCount ?? 0);
    final decel = math.max(session?.decelCount ?? 0, local?.decelCount ?? 0);
    final cod = math.max(session?.changeOfDirectionCount ?? 0,
        local?.changeOfDirectionCount ?? 0);
    final durationSec =
        math.max(session?.durationSec ?? 0, local?.durationSec ?? 0);
    final deviceName = session?.deviceName ??
        local?.deviceName ??
        widget.ble.connectedInfo?.name ??
        'Трекер не подключён';
    final heartRate = _heartRateForPlayerId(player.id);
    final heartRateStatus = _heartRateValueLabel(heartRate);
    final heartRateZone = _heartRateZoneLabelForSample(heartRate);
    final phone = MediaQuery.of(context).size.width < 720;

    return Column(
      children: [
        Container(
          height: 64,
          padding: const EdgeInsets.symmetric(horizontal: 10),
          decoration: const BoxDecoration(
              color: Colors.white,
              border: Border(bottom: BorderSide(color: _OF.line))),
          child: Row(
            children: [
              CircleAvatar(
                radius: 19,
                backgroundColor: online ? _OF.green : _OF.header,
                backgroundImage: (player.avatar ?? '').isNotEmpty
                    ? NetworkImage(player.avatar!)
                    : null,
                child: (player.avatar ?? '').isEmpty
                    ? Text(_playerInitials(player.name),
                        style: TextStyle(
                            color: online ? Colors.white : _OF.graphite,
                            fontWeight: FontWeight.w700,
                            fontSize: AppTypography.secondarySize))
                    : null,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(player.name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _OF.text,
                            fontSize: AppTypography.sectionTitleSize,
                            fontWeight: FontWeight.w700,
                            letterSpacing: -.2)),
                    const SizedBox(height: 3),
                    Row(children: [
                      _ofStatusDot(online ? _OF.green : _OF.orange),
                      const SizedBox(width: 6),
                      Flexible(
                          child: Text(
                              online
                                  ? 'онлайн · $deviceName${heartRate == null ? '' : ' · $heartRateStatus'}'
                                  : 'ожидание Live · $deviceName${heartRate == null ? '' : ' · $heartRateStatus'}',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _OF.muted,
                                  fontSize: AppTypography.secondarySize,
                                  fontWeight: FontWeight.w600))),
                    ]),
                  ],
                ),
              ),
              if (!phone) ...[
                _LiveDetailHeaderChip(
                    icon: Icons.timer_rounded,
                    label: durationSec <= 0
                        ? _durationText()
                        : _formatDuration(Duration(seconds: durationSec))),
                const SizedBox(width: 8),
                _LiveDetailHeaderChip(
                    icon: Icons.speed_rounded,
                    label: '${speed.toStringAsFixed(1)} км/ч'),
                const SizedBox(width: 8),
                _LiveDetailHeaderChip(
                    icon: Icons.monitor_heart_rounded,
                    label: heartRate == null
                        ? 'пульс —'
                        : '$heartRateStatus · $heartRateZone'),
                const SizedBox(width: 8),
              ],
              _NoHoverTap(
                  onTap: onClose,
                  child: Container(
                      width: 34,
                      height: 34,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(6)),
                      child: const Icon(Icons.close_rounded,
                          color: _OF.graphite, size: 20))),
            ],
          ),
        ),
        Expanded(
          child: LayoutBuilder(
            builder: (context, c) {
              final vertical = c.maxWidth < 760;
              final dataPanel = _playerLiveMetricPanel(
                  speed: speed,
                  distance: distance,
                  metersPerMin: mpm,
                  maxSpeed: maxSpeed,
                  load: load,
                  hir: hir,
                  vhir: vhir,
                  sprint: sprint,
                  accel: accel,
                  decel: decel,
                  cod: cod,
                  track: displayTrack,
                  heartRate: heartRate);
              final fieldPanel =
                  _playerLiveFieldPanel(player: player, track: displayTrack);
              if (vertical) {
                return Column(children: [
                  Expanded(flex: 7, child: fieldPanel),
                  _ofHorizontalDivider(),
                  Expanded(flex: 6, child: dataPanel)
                ]);
              }
              return Row(children: [
                Expanded(flex: 45, child: dataPanel),
                _ofVerticalDivider(),
                Expanded(flex: 55, child: fieldPanel)
              ]);
            },
          ),
        ),
      ],
    );
  }

