  Widget _loadMarkBanner(
      {required double load, required HeartRateSample? heartRate}) {
    final mark = _loadMarkLabel(load, heartRateBpm: heartRate?.bpm);
    final color = _loadMarkColor(load, heartRateBpm: heartRate?.bpm);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
      decoration: BoxDecoration(
          color: color.withOpacity(.08),
          borderRadius: BorderRadius.circular(6),
          border: Border.all(color: color.withOpacity(.22))),
      child: Row(
        children: [
          Container(
              width: 30,
              height: 30,
              decoration: BoxDecoration(
                  color: Colors.white, borderRadius: BorderRadius.circular(6)),
              child: Icon(Icons.flag_rounded, size: 16, color: color)),
          const SizedBox(width: 8),
          Expanded(
              child: Text('Метка нагрузки: $mark',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
