  Widget _floatingLiveWindowLayer() {
    return LayoutBuilder(
      builder: (context, c) {
        if (c.maxWidth < 720) {
          return Material(
            color: _OF.bg,
            child: SafeArea(
              bottom: false,
              child: Column(
                children: [
                  Container(
                    height: 52,
                    padding: const EdgeInsets.symmetric(horizontal: 8),
                    decoration: const BoxDecoration(
                        color: _OF.bg,
                        border: Border(bottom: BorderSide(color: _OF.line))),
                    child: Row(
                      children: [
                        _NoHoverTap(
                          onTap: _closeFloatingLiveWindow,
                          child: const SizedBox(
                              width: 36,
                              height: 36,
                              child: Icon(Icons.arrow_back_rounded,
                                  color: _OF.graphite)),
                        ),
                        Container(
                          width: 32,
                          height: 32,
                          decoration: BoxDecoration(
                              color: _OF.greenSoft,
                              borderRadius: BorderRadius.circular(6),
                              border: Border.all(
                                  color: _OF.green.withOpacity(.07))),
                          child: Icon(_floatingLiveIcon,
                              color: _OF.green, size: 17),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            _floatingLiveTitle ?? 'Окно',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: _OF.text,
                                fontSize: AppTypography.sectionTitleSize,
                                fontWeight: FontWeight.w700,
                                letterSpacing: -.2),
                          ),
                        ),
                        _NoHoverTap(
                          onTap: _closeFloatingLiveWindow,
                          child: const SizedBox(
                              width: 36,
                              height: 36,
                              child:
                                  Icon(Icons.close_rounded, color: _OF.muted2)),
                        ),
                      ],
                    ),
                  ),
                  Expanded(child: _buildFloatingLiveContent()),
                ],
              ),
            ),
          );
        }

        final compact = c.maxWidth < 1180;
        final margin = compact ? 6.0 : 14.0;
        // На планшете всплывающие окна сразу почти во весь экран: не нужно
        // ловить маленькое окно и листать внутренний контент. На ПК оставляем
        // привычный плавающий размер.
        final windowWidth = _floatingLiveMaximized || compact
            ? c.maxWidth - margin * 2
            : math.min(c.maxWidth - margin * 2, 980.0);
        final windowHeight = _floatingLiveMaximized || compact
            ? c.maxHeight - margin * 2
            : math.min(c.maxHeight - margin * 2, 660.0);

        final defaultLeft = (c.maxWidth - windowWidth) / 2;
        final defaultTop = math.max(margin, (c.maxHeight - windowHeight) / 2);
        final maxLeft = math.max(margin, c.maxWidth - windowWidth - margin);
        final maxTop = math.max(margin, c.maxHeight - windowHeight - margin);
        final raw = _floatingLiveOffset ?? Offset(defaultLeft, defaultTop);
        final left = _floatingLiveMaximized
            ? margin
            : raw.dx.clamp(margin, maxLeft).toDouble();
        final top = _floatingLiveMaximized
            ? margin
            : raw.dy.clamp(margin, maxTop).toDouble();

        void dragWindow(DragUpdateDetails details) {
          if (_floatingLiveMaximized) return;
          final current = _floatingLiveOffset ?? Offset(left, top);
          final next = Offset(
            (current.dx + details.delta.dx).clamp(margin, maxLeft).toDouble(),
            (current.dy + details.delta.dy).clamp(margin, maxTop).toDouble(),
          );
          setState(() => _floatingLiveOffset = next);
        }

        return Stack(
          children: [
            Positioned(
              left: left,
              top: top,
              width: windowWidth,
              height: windowHeight,
              child: Material(
                color: Colors.transparent,
                child: Container(
                  clipBehavior: Clip.antiAlias,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(.98),
                    borderRadius:
                        BorderRadius.circular(_floatingLiveMaximized ? 6 : 8),
                    boxShadow: null,
                  ),
                  child: Column(
                    children: [
                      GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onPanUpdate: dragWindow,
                        child: Container(
                          height: 46,
                          padding: const EdgeInsets.symmetric(horizontal: 10),
                          decoration: const BoxDecoration(
                              border:
                                  Border(bottom: BorderSide(color: _OF.line))),
                          child: Row(
                            children: [
                              _floatingWindowControl(Icons.close_rounded,
                                  _closeFloatingLiveWindow, 'Закрыть'),
                              const SizedBox(width: 6),
                              _floatingWindowControl(
                                  Icons.remove_rounded,
                                  () => setState(
                                      () => _floatingLiveMinimized = true),
                                  'Свернуть'),
                              const SizedBox(width: 6),
                              _floatingWindowControl(
                                  _floatingLiveMaximized
                                      ? Icons.close_fullscreen_rounded
                                      : Icons.open_in_full_rounded,
                                  () => setState(() => _floatingLiveMaximized =
                                      !_floatingLiveMaximized),
                                  _floatingLiveMaximized
                                      ? 'Вернуть размер'
                                      : 'Развернуть'),
                              const SizedBox(width: 8),
                              Container(
                                width: 30,
                                height: 30,
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(4),
                                ),
                                child: Icon(_floatingLiveIcon,
                                    color: _OF.muted2, size: 17),
                              ),
                              const SizedBox(width: 9),
                              Expanded(
                                child: Text(
                                  _floatingLiveTitle ?? 'Окно',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                      color: _OF.text,
                                      fontSize: AppTypography.itemTitleSize,
                                      fontWeight: FontWeight.w700,
                                      letterSpacing: -.2),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                      Expanded(
                        child: Padding(
                          padding: const EdgeInsets.all(1),
                          child: _buildFloatingLiveContent(),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ],
        );
      },
    );
  }

