            child: Container(
              color: const Color(0xFFF8F9FA),
              child: LayoutBuilder(
                builder: (context, c) {
                  const aspect = 105.0 / 68.0;
                  final maxW = c.maxWidth.isFinite ? c.maxWidth : 420.0;
                  final maxH = c.maxHeight.isFinite ? c.maxHeight : 420.0;
                  var w = maxW - 8;
                  var h = w / aspect;
                  if (h > maxH - 8) {
                    h = maxH - 8;
                    w = h * aspect;
