  HeartRateSample? get _selectedHeartRateSample {
    return _heartRateForPlayerId(widget.selectedPlayer?.id);
  }

  HeartRateSample? _heartRateForPlayerId(int? playerId) {
    if (playerId == null) return null;
    return widget.heartRateByPlayerId[playerId];
  }

  Map<String, dynamic> _trackAnalysisWithHeartRate(_RuntimeTrack track) {
    final sample = _selectedHeartRateSample;
    final data = <String, dynamic>{...track.toJson()};
    if (sample != null) {
      data.addAll(sample.toJson());
      data['internal_load_note'] =
          'внешняя нагрузка GPS + пульс Polar/Heart Rate BLE';
    }
    return data;
  }

  String get _heartRateKpiLabel =>
      _heartRateValueLabel(_selectedHeartRateSample);

  String get _heartRateZoneLabel =>
      _heartRateZoneLabelForSample(_selectedHeartRateSample);

  String _heartRateValueLabel(HeartRateSample? sample) {
    if (sample == null) return '—';
    final age = DateTime.now().difference(sample.measuredAt).inSeconds;
    if (age > 20) return '${sample.bpm} bpm*';
    return '${sample.bpm} bpm';
  }

  String _heartRateZoneLabelForSample(HeartRateSample? sample) {
    final bpm = sample?.bpm ?? 0;
    if (bpm <= 0) return '—';
    if (bpm < 120) return 'Z1';
    if (bpm < 145) return 'Z2';
    if (bpm < 165) return 'Z3';
    if (bpm < 180) return 'Z4';
    return 'Z5';
  }

  String _heartRateLiveRecommendation(
      {required _RuntimeTrack? track, required HeartRateSample? sample}) {
    if (sample == null) {
      return 'Polar H10 не привязан к этому игроку или ещё не отдаёт online bpm.';
    }
    final bpm = sample.bpm;
    final ageSec = DateTime.now().difference(sample.measuredAt).inSeconds;
    if (ageSec > 20) {
      return 'Пульс устарел: последние данные были ${ageSec} сек. назад. Проверьте контакт ремня и BLE-связь.';
    }
    final speed = track?.speedKmh ?? 0;
    final load = track?.loadScore ?? 0;
    if (bpm >= 180)
      return 'Высокая ЧСС Z5: снизить интенсивность и контролировать восстановление игрока.';
    if (bpm >= 165 && speed < 7)
      return 'Пульс высокий при низкой скорости: возможная усталость, стресс или плохой контакт ремня.';
    if (bpm >= 165)
      return 'Интенсивная работа Z4: держать под контролем длительность отрезка и паузы.';
    if (bpm < 120 && load > 20)
      return 'Внешняя нагрузка растёт, а пульс низкий: проверьте посадку Polar H10 и контакт электродов.';
    if (bpm < 120)
      return 'Низкая зона ЧСС: разминка/восстановление, критичных признаков нет.';
    return 'Пульс соответствует рабочей зоне, нагрузка контролируемая.';
  }

  String _combinedLiveRecommendation(
      {required _RuntimeTrack? track, required HeartRateSample? sample}) {
    final base = track?.recommendation ??
        'Live-данные появятся после подключения трекера и старта сессии.';
    if (sample == null) return base;
    return '$base\nПульс: ${_heartRateLiveRecommendation(track: track, sample: sample)}';
  }

  Widget _liveHeartRateSidePanel() {
    final players = _sidePanelPlayers();
    final series = <_LiveMetricSeries>[];
    for (var i = 0; i < players.length; i++) {
      final p = players[i];
      final history = List<_LiveMetricPoint>.from(
        (_liveHrHistoryByPlayer[p.id] ?? const <_LiveHrPoint>[]).map(
            (e) => _LiveMetricPoint(timeMs: e.timeMs, value: e.bpm.toDouble())),
      );
      final current = _heartRateForPlayerId(p.id);
      if (history.isEmpty && current != null) {
        history.add(_LiveMetricPoint(
            timeMs: current.measuredAt.millisecondsSinceEpoch,
            value: current.bpm.toDouble()));
      }
      if (history.isNotEmpty) {
        series.add(_LiveMetricSeries(
            label: _compactPlayerName(p.displayName ?? p.name),
            color: _chartColor(i),
            points: history));
      }
    }
    final fresh =
        players.where((p) => _heartRateForPlayerId(p.id) != null).length;
    return _LiveCard(
      padding: const EdgeInsets.all(10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _sidePanelSummaryRow(
            icon: Icons.favorite_rounded,
            title: 'Online ЧСС выбранных игроков',
            value: series.isEmpty
                ? 'нет данных Polar'
                : '$fresh/${players.length} online',
            color: _OF.red,
          ),
          const SizedBox(height: 8),
          Expanded(
            child: series.isEmpty
                ? _sideEmptyState(
                    Icons.monitor_heart_rounded,
                    'Нет live-пульса',
                    'Назначьте Polar игрокам или выберите игроков, у которых сейчас есть ЧСС.')
                : ClipRRect(
                    borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius:
                              BorderRadius.circular(_OF.tabletInnerRadius)),
                      child: CustomPaint(
                        painter: _LiveLineChartPainter(
                          series: series,
                          minY: 80,
                          maxY: 205,
                          valueSuffix: ' bpm',
                          thresholds: const <_LiveChartThreshold>[
                            _LiveChartThreshold(value: 145, label: 'Z3'),
                            _LiveChartThreshold(value: 165, label: 'Z4'),
                            _LiveChartThreshold(value: 180, label: 'Z5'),
                          ],
                        ),
                        child: const SizedBox.expand(),
                      ),
                    ),
                  ),
          ),
          const SizedBox(height: 8),
          _sideLegend(series),
        ],
      ),
    );
  }

  Widget _liveSprintSidePanel() {
    final players = _sidePanelPlayers();
    final tracks = <_RuntimeTrack>[];
    for (final p in players) {
      final track = _displayTrackForPlayer(p);
      if (track != null && track.points.isNotEmpty) tracks.add(track);
    }
    final series = <_LiveMetricSeries>[];
    for (var i = 0; i < tracks.length; i++) {
      final track = tracks[i];
      series.add(_LiveMetricSeries(
        label: _compactPlayerName(track.playerName),
        color: _chartColor(i),
        points: track.points
            .map((p) => _LiveMetricPoint(timeMs: p.timeMs, value: p.speedKmh))
            .toList(growable: false),
      ));
    }
    final sprintDistance =
        tracks.fold<double>(0, (sum, t) => sum + t.sprintDistanceM);
    final hsrDistance =
        tracks.fold<double>(0, (sum, t) => sum + t.hsrDistanceM);
    final accel = tracks.fold<int>(0, (sum, t) => sum + t.accelCount);
    final decel = tracks.fold<int>(0, (sum, t) => sum + t.decelCount);
    return _LiveCard(
      padding: const EdgeInsets.all(10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _sidePanelSummaryRow(
            icon: Icons.speed_rounded,
            title: 'Скорость, HIR и спринты',
            value:
                tracks.isEmpty ? 'нет GPS-точек' : '${tracks.length} трек(ов)',
            color: _OF.green,
          ),
          const SizedBox(height: 8),
          Expanded(
            child: series.isEmpty
                ? _sideEmptyState(Icons.speed_rounded, 'Нет GPS-скорости',
                    'После первых пакетов трекера здесь появятся скорость, HIR, спринты, ускорения и торможения.')
                : ClipRRect(
                    borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius:
                              BorderRadius.circular(_OF.tabletInnerRadius)),
                      child: CustomPaint(
                        painter: _LiveLineChartPainter(
                          series: series,
                          minY: 0,
                          maxY: math.max(
                              22.0,
                              series.expand((s) => s.points).fold<double>(
                                      0, (m, p) => math.max(m, p.value)) +
                                  3),
                          valueSuffix: ' км/ч',
                          thresholds: const <_LiveChartThreshold>[
                            _LiveChartThreshold(value: 14, label: 'HIR'),
                            _LiveChartThreshold(value: 18, label: 'SPR'),
                          ],
                          highlightAbove: 18,
                        ),
                        child: const SizedBox.expand(),
                      ),
                    ),
                  ),
          ),
          const SizedBox(height: 8),
          Row(children: [
            Expanded(
                child: _sideMetricChip(
                    'HIR', '${hsrDistance.toStringAsFixed(0)} м', _OF.orange)),
            const SizedBox(width: 6),
            Expanded(
                child: _sideMetricChip(
                    'SPR', '${sprintDistance.toStringAsFixed(0)} м', _OF.red)),
            const SizedBox(width: 6),
            Expanded(child: _sideMetricChip('ACC', '$accel', _OF.green)),
            const SizedBox(width: 6),
            Expanded(child: _sideMetricChip('DEC', '$decel', _OF.blue)),
          ]),
          const SizedBox(height: 7),
          _sideLegend(series),
        ],
      ),
    );
  }

  Widget _liveSignalSidePanel() {
    final players = _sidePanelPlayers();
    return _LiveCard(
      padding: const EdgeInsets.all(10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _sidePanelSummaryRow(
            icon: Icons.network_check_rounded,
            title: 'Уровень сигнала BLE / Polar',
            value:
                players.isEmpty ? 'нет игроков' : '${players.length} выбран.',
            color: _OF.green,
          ),
          const SizedBox(height: 8),
          Expanded(
            child: players.isEmpty
                ? _sideEmptyState(
                    Icons.network_check_rounded,
                    'Нет выбранных игроков',
                    'Выберите игроков в Live-мониторинге, чтобы видеть сигнал трекера и Polar.')
                : ListView.separated(
                    padding: EdgeInsets.zero,
                    itemCount: players.length,
                    separatorBuilder: (_, __) => const SizedBox(height: 7),
                    itemBuilder: (_, i) => _liveSignalPlayerRow(players[i]),
                  ),
          ),
        ],
      ),
    );
  }

  Widget _liveSignalPlayerRow(TrackerPlayerOption player) {
    final rssi = _playerBleRssi(player);
    final device = _deviceForPlayer(player.id);
    final hr = _heartRateForPlayerId(player.id);
    final hrAge =
        hr == null ? null : DateTime.now().difference(hr.measuredAt).inSeconds;
    final color = _signalColorForPlayer(player);
    final level = rssi == null
        ? (device?.isNearby == true || hr != null ? .64 : .14)
        : ((rssi + 100) / 45).clamp(.08, 1.0).toDouble();
    final battery = device?.batteryPercent ??
        hr?.batteryPercent ??
        (widget.selectedPlayer?.id == player.id ? widget.batteryPercent : null);
    return Container(
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(_OF.tabletInnerRadius)),
      child: Row(children: [
        _playerAvatarCircle(
            player: player, radius: 17, online: color == _OF.green),
        const SizedBox(width: 8),
        Expanded(
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(_compactPlayerName(player.displayName ?? player.name),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: _OF.text,
                    fontSize: AppTypography.secondarySize,
                    fontWeight: FontWeight.w900)),
            const SizedBox(height: 4),
            Row(children: [
              Expanded(child: _signalBar(level, color)),
              const SizedBox(width: 7),
              Text(rssi == null ? _signalLabelForPlayer(player) : '$rssi dBm',
                  style: TextStyle(
                      color: color,
                      fontSize: AppTypography.menuGroupSize,
                      fontWeight: FontWeight.w900)),
            ]),
          ]),
        ),
        const SizedBox(width: 8),
        Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
          Text(battery == null ? 'бат. —' : 'бат. $battery%',
              style: const TextStyle(
                  color: _OF.muted2,
                  fontSize: AppTypography.menuGroupSize,
                  fontWeight: FontWeight.w800)),
          const SizedBox(height: 5),
          Text(
              hr == null
                  ? 'HR —'
                  : '${hr.bpm} bpm${hrAge != null && hrAge > 25 ? ' · ${hrAge}s' : ''}',
              style: TextStyle(
                  color: hr == null ? _OF.muted2 : _OF.red,
                  fontSize: AppTypography.menuGroupSize,
                  fontWeight: FontWeight.w900)),
        ]),
      ]),
    );
  }

  Widget _sidePanelSummaryRow(
      {required IconData icon,
      required String title,
      required String value,
      required Color color}) {
    return Row(children: [
      Container(
          width: 30,
          height: 30,
          alignment: Alignment.center,
          decoration: BoxDecoration(
              color: color.withOpacity(.08),
              borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
              border: Border.all(color: color.withOpacity(.07))),
          child: Icon(icon, color: color, size: 16)),
      const SizedBox(width: 8),
      Expanded(
          child: Text(title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  color: _OF.text, fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w900))),
      Text(value,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: const TextStyle(
              color: _OF.muted2, fontSize: AppTypography.captionSize, fontWeight: FontWeight.w800)),
    ]);
  }

  Widget _sideEmptyState(IconData icon, String title, String text) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxHeight < 115;
        final veryCompact = constraints.maxHeight < 72;
        return Center(
          child: Padding(
            padding: EdgeInsets.all(veryCompact ? 2 : (compact ? 5 : 10)),
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              if (!veryCompact) ...[
                Icon(icon, color: _OF.muted2, size: compact ? 20 : 30),
                SizedBox(height: compact ? 4 : 9),
              ],
              Text(
                title,
                maxLines: veryCompact ? 1 : 2,
                overflow: TextOverflow.ellipsis,
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: _OF.text,
                  fontSize: compact ? 9.6 : 11,
                  fontWeight: FontWeight.w900,
                ),
              ),
              if (!compact) ...[
                const SizedBox(height: 5),
                Text(
                  text,
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: _OF.muted2,
                    fontSize: AppTypography.secondarySize,
                    fontWeight: FontWeight.w700,
                    height: 1.25,
                  ),
                ),
              ],
            ]),
          ),
        );
      },
    );
  }

  Widget _sideMetricChip(String label, String value, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
      decoration: BoxDecoration(
          color: color.withOpacity(.07),
          borderRadius: BorderRadius.circular(_OF.tabletInnerRadius),
          border: Border.all(color: color.withOpacity(.07))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
                color: color, fontSize: AppTypography.captionSize, fontWeight: FontWeight.w900)),
        const SizedBox(height: 2),
        Text(value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
                color: _OF.text, fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w900)),
      ]),
    );
  }

  Widget _signalBar(double value, Color color) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(999),
      child: Container(
        height: 7,
        color: _OF.line,
        alignment: Alignment.centerLeft,
        child: FractionallySizedBox(
          widthFactor: value.clamp(.04, 1.0).toDouble(),
          child: Container(color: color),
        ),
      ),
    );
  }

  Widget _sideLegend(List<_LiveMetricSeries> series) {
    if (series.isEmpty) return const SizedBox.shrink();
    return SizedBox(
      height: 23,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        itemCount: series.length,
        separatorBuilder: (_, __) => const SizedBox(width: 6),
        itemBuilder: (_, i) => Container(
          padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
          decoration: BoxDecoration(
            color: series[i].color.withOpacity(.08),
            borderRadius: BorderRadius.circular(999),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Container(
                width: 6,
                height: 6,
                decoration: BoxDecoration(
                    color: series[i].color, shape: BoxShape.circle)),
            const SizedBox(width: 5),
            Text(
              series[i].label,
              style: _OFText.body(
                size: 9.6,
                color: _OF.text,
                weight: FontWeight.w600,
              ),
            ),
          ]),
        ),
      ),
    );
  }

  Color _chartColor(int index) {
    const colors = <Color>[
      _OF.green,
      _OF.blue,
      _OF.orange,
      _OF.red,
      _OF.cyan,
      Color(0xFF7C3AED),
      Color(0xFF0F766E),
      Color(0xFFDB2777),
      Color(0xFF475569),
      Color(0xFFCA8A04),
      Color(0xFF0891B2),
      Color(0xFF16A34A)
    ];
    return colors[index % colors.length];
  }

  Widget _fieldCard() {
    if (!_activity.requiresField) {
      final track = _liveTelemetryActive ? _mainTrack : null;
      return _LiveCard(
        padding: const EdgeInsets.all(10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Container(
                  width: 42,
                  height: 42,
                  decoration: BoxDecoration(
                      color: _OF.greenSoft,
                      borderRadius: BorderRadius.circular(6)),
                  child: Icon(_activity.icon, color: _OF.green, size: 21),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(_activity.title,
                          style: const TextStyle(
                              color: _OF.text,
                              fontSize: AppTypography.itemTitleSize,
                              fontWeight: FontWeight.w700)),
                      const SizedBox(height: 3),
                      Text(_activity.subtitle,
                          style: const TextStyle(
                              color: _OF.muted,
                              fontSize: AppTypography.secondarySize,
                              fontWeight: FontWeight.w600)),
                    ],
                  ),
                ),
              ],
            ),
            const Spacer(),
            Row(
              children: [
                Expanded(
                    child: _NoFieldMetricTile(
                        label: 'Дистанция',
                        value:
                            '${((track?.totalDistanceM ?? 0) / 1000).toStringAsFixed(2)} км')),
                const SizedBox(width: 8),
                Expanded(
                    child: _NoFieldMetricTile(
                        label: 'Темп',
                        value:
                            '${track?.metersPerMinute.toStringAsFixed(0) ?? '0'} м/мин')),
                const SizedBox(width: 8),
                Expanded(
                    child: _NoFieldMetricTile(
                        label: 'Нагрузка',
                        value:
                            '${track?.loadScore.toStringAsFixed(0) ?? '0'}')),
              ],
            ),
            const SizedBox(height: 8),
            Container(
              height: 88,
              decoration: BoxDecoration(
                  color: Colors.white, borderRadius: BorderRadius.circular(6)),
              child: CustomPaint(
                painter: _OpenFieldTimelinePainter(
                  points: track?.points ?? const <_RuntimePoint>[],
                  running: _running,
                  progressRatio: _timelineProgressRatio(),
                ),
                child: Center(
                  child: Text(
                    track == null || track.points.length < 2
                        ? 'Ожидание данных трекера'
                        : 'Активность записывается без привязки к полю',
                    style: const TextStyle(
                        color: _OF.muted,
                        fontSize: AppTypography.secondarySize,
                        fontWeight: FontWeight.w700),
                  ),
                ),
              ),
            ),
          ],
        ),
      );
    }
    return _LiveCard(
      padding: EdgeInsets.zero,
      child: LayoutBuilder(
        builder: (context, c) {
          final tracks = _sidePanelTracks();
          final tactical = _liveMapTacticalSnapshot(tracks);
          return ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: LayoutBuilder(
              builder: (context, fieldBox) {
                    final size = fieldBox.biggest;
                    final bounds = _phoneFieldBounds(tracks);
                    final pitch = _phoneFieldPitch(size);
                    final markerTracks = tracks
                        .where((track) => track.points.isNotEmpty)
                        .take(16)
                        .toList(growable: false);
                    return Stack(
                      clipBehavior: Clip.hardEdge,
                      children: [
                        Positioned.fill(
                          child: CustomPaint(
                            painter: _RuntimeFieldPainter(
                              field: widget.selectedField,
                              motionCache: _runtimeMotionEnabled ? _runtimeMotionCache : null,
                              repaint: _runtimeMotionController,
                              tracks: tracks,
                              showVectors: _showVectors,
                              showHeatmap: _showHeatmap,
                              showTrace: _showTrace,
                              // Аватар, имя/скорость и выбор игрока рисуем Flutter-
                              // виджетами поверх canvas. Так они одинаково выглядят
                              // на телефоне, планшете и ПК и не теряются на heatmap.
                              showLabels: false,
                              showLoadHotPoints: _showLoadHotPoints,
                              showTeamShapeConnections:
                                  _showTeamShapeConnections,
                              showPassingNetwork:
                                  _liveMapProShowPassingNetwork,
                              showTacticalLines:
                                  _liveMapProShowTacticalLines,
                              showOffsideGuide:
                                  _liveMapProShowOffsideGuide,
                              showControlZones:
                                  _liveMapProShowControlZones,
                              showTeamCenter:
                                  _liveMapProShowTeamCenter,
                              showPitchZones:
                                  _liveMapProShowPitchZones,
                              tacticalSnapshot: tactical,
                              warningEvents: _fieldLiveEvents(),
                              selectedWarningEventId: _selectedLiveEventId,
                            ),
                            child: const SizedBox.expand(),
                          ),
                        ),
                        if (_showPlayerAvatars)
                          for (final track in markerTracks)
                            _phoneFieldAvatarMarker(
                              track: track,
                              pitch: pitch,
                              bounds: bounds,
                              focused: widget.selectedPlayer != null &&
                                _phonePlayerForTrack(track)?.id ==
                                    widget.selectedPlayer!.id,
                          ),
                      ],
                    );
              },
            ),
          );
        },
      ),
    );
  }

  Widget _kpiGrid({required int columns}) {
    final track = _liveTelemetryActive ? _mainTrack : null;
    final lastDelta = track?.lastDeltaM ?? 0;

    final items = [
      _KpiData('Скорость', '${_displaySpeedKmh.toStringAsFixed(1)} км/ч',
          Icons.speed_rounded),
      _KpiData(
          'Темп',
          '${track?.metersPerMinute.toStringAsFixed(0) ?? '0'} м/мин',
          Icons.timer_rounded),
      _KpiData('Пульс', _heartRateKpiLabel, Icons.monitor_heart_rounded),
      _KpiData('Зона ЧСС', _heartRateZoneLabel, Icons.favorite_rounded),
      _KpiData('Нагрузка', '${track?.loadScore.toStringAsFixed(0) ?? '0'}',
          Icons.bolt_rounded),
      _KpiData('Усталость', '${track?.fatigueIndex.toStringAsFixed(0) ?? '0'}%',
          Icons.battery_alert_rounded),
      _KpiData('HSR', '${track?.hsrDistanceM.toStringAsFixed(0) ?? '0'} м',
          Icons.speed_rounded),
      _KpiData(
          'Спринт',
          '${track?.sprintDistanceM.toStringAsFixed(0) ?? '0'} м',
          Icons.flash_on_rounded),
    ];

    return GridView.builder(
      physics: const NeverScrollableScrollPhysics(),
      padding: EdgeInsets.zero,
      itemCount: items.length,
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: columns,
        crossAxisSpacing: 6,
        mainAxisSpacing: 6,
        childAspectRatio: columns == 2 ? 2.85 : (columns == 3 ? 3.15 : 2.15),
      ),
      itemBuilder: (_, i) => _KpiCard(data: items[i]),
    );
  }

