/// 3D-камера Live повторяет управление аналитики, но хранит yaw/tilt/zoom
/// локально. Поэтому движение джойстика композитит готовый слой поля и не
/// запускает повторную сборку всего Live workspace с таблицами и графиками.
class _LivePitchPerspective extends StatefulWidget {
  const _LivePitchPerspective({
    required this.enabled,
    required this.child,
  });

  final bool enabled;
  final Widget child;

  @override
  State<_LivePitchPerspective> createState() =>
      _LivePitchPerspectiveState();
}

class _LivePitchPerspectiveState extends State<_LivePitchPerspective> {
  double _yawDeg = 0.0;
  double _tiltRad = -.34;
  double _zoom = .96;

  void _orbit(Offset delta) {
    if (!widget.enabled) return;
    setState(() {
      _yawDeg = (_yawDeg + delta.dx * .48) % 360.0;
      _tiltRad =
          (_tiltRad - delta.dy * .0065).clamp(-.70, -.10).toDouble();
    });
  }

  void _zoomBy(double delta) {
    if (!widget.enabled) return;
    setState(() {
      _zoom = (_zoom + delta).clamp(.96, 1.38).toDouble();
    });
  }

  void _reset() {
    if (!widget.enabled) return;
    setState(() {
      _yawDeg = 0.0;
      _tiltRad = -.34;
      _zoom = .96;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.enabled) return widget.child;

    final yaw = _yawDeg * math.pi / 180.0;
    final transform = Matrix4.identity()
      ..setEntry(3, 2, .00135)
      ..rotateX(_tiltRad.clamp(-.70, -.10).toDouble())
      ..rotateZ(yaw)
      ..scale(_zoom.clamp(.96, 1.38).toDouble());

    return AnimatedContainer(
      duration: const Duration(milliseconds: 180),
      padding: const EdgeInsets.fromLTRB(6, 5, 6, 4),
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[Color(0xFFDDE7E1), Color(0xFFF6F8F7)],
        ),
      ),
      child: Stack(
        fit: StackFit.expand,
        clipBehavior: Clip.hardEdge,
        children: [
          IgnorePointer(
            child: Transform.translate(
              offset: const Offset(0, 8),
              child: Transform(
                alignment: Alignment.center,
                transform: transform,
                child: Container(
                  decoration: BoxDecoration(
                    color: const Color(0xFF284B38),
                    borderRadius: BorderRadius.circular(14),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(.20),
                        blurRadius: 18,
                        spreadRadius: -6,
                        offset: const Offset(0, 12),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
          Transform.translate(
            offset: const Offset(0, -5),
            child: Transform(
              alignment: Alignment.center,
              transform: transform,
              transformHitTests: true,
              child: RepaintBoundary(child: widget.child),
            ),
          ),
          Positioned(
            right: 12,
            bottom: 12,
            child: _LiveCameraControl(
              onOrbitDelta: _orbit,
              onZoomIn: () => _zoomBy(.08),
              onZoomOut: () => _zoomBy(-.08),
              onReset: _reset,
            ),
          ),
        ],
      ),
    );
  }
}

