class _LiveLineChartPainter extends CustomPainter {
  const _LiveLineChartPainter({
    required this.series,
    required this.minY,
    required this.maxY,
    this.thresholds = const <_LiveChartThreshold>[],
    this.valueSuffix = '',
    this.highlightAbove,
    this.loadPoints = const <_LiveMetricPoint>[],
    this.cursorFraction,
  });

  final List<_LiveMetricSeries> series;
  final double minY;
  final double maxY;
  final List<_LiveChartThreshold> thresholds;
  final String valueSuffix;
  final double? highlightAbove;
  final List<_LiveMetricPoint> loadPoints;
  final double? cursorFraction;

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Offset.zero & size;
    final chart = Rect.fromLTWH(rect.left + 34, rect.top + 14,
        math.max(1.0, rect.width - 46), math.max(1.0, rect.height - 34));
    final heartPoints = series.expand((s) => s.points).toList(growable: false);
    final all = <_LiveMetricPoint>[
      ...heartPoints,
      ...loadPoints,
    ];
    if (all.isEmpty) return;
    final minTime = all.map((p) => p.timeMs).reduce((a, b) => a < b ? a : b);
    final maxTime = all.map((p) => p.timeMs).reduce((a, b) => a > b ? a : b);
    final spanTime = math.max(1.0, (maxTime - minTime).toDouble());
    final yMin = minY;
    final yMax = math.max(maxY, yMin + 1);
    double yForValue(double value) => chart.bottom -
        ((value.clamp(yMin, yMax).toDouble() - yMin) / (yMax - yMin)) *
            chart.height;

    // Нежные цветовые зоны дают тренеру контекст ещё до чтения подписей.
    if (thresholds.isNotEmpty) {
      final sorted = List<_LiveChartThreshold>.from(thresholds)
        ..sort((a, b) => a.value.compareTo(b.value));
      for (var i = 0; i < sorted.length; i++) {
        final low = sorted[i].value.clamp(yMin, yMax).toDouble();
        final high = i + 1 < sorted.length
            ? sorted[i + 1].value.clamp(yMin, yMax).toDouble()
            : yMax;
        if (high <= low) continue;
        final label = sorted[i].label.toUpperCase();
        final zoneColor = label == 'Z5' || label == 'SPR'
            ? _OF.red
            : (label == 'Z4' ? _OF.orange : _OF.green);
        canvas.drawRect(
          Rect.fromLTRB(
            chart.left,
            yForValue(high),
            chart.right,
            yForValue(low),
          ),
          Paint()..color = zoneColor.withOpacity(.035),
        );
      }
    }

    final grid = Paint()
      ..color = _OF.lineStrong.withOpacity(.8)
      ..strokeWidth = 1;
    final textStyle = TextStyle(
        color: _OF.muted2.withOpacity(.86),
        fontSize: 10.4,
        fontWeight: FontWeight.w700);
    for (var i = 0; i <= 4; i++) {
      final y = chart.bottom - chart.height * (i / 4.0);
      canvas.drawLine(Offset(chart.left, y), Offset(chart.right, y), grid);
      final value = yMin + (yMax - yMin) * (i / 4.0);
      final tp = TextPainter(
          text: TextSpan(text: value.toStringAsFixed(0), style: textStyle),
          textDirection: TextDirection.ltr)
        ..layout(maxWidth: 30);
      tp.paint(canvas, Offset(rect.left + 2, y - tp.height / 2));
    }

    for (final threshold in thresholds) {
      if (threshold.value < yMin || threshold.value > yMax) continue;
      final y = chart.bottom -
          ((threshold.value - yMin) / (yMax - yMin)) * chart.height;
      final paint = Paint()
        ..color = (threshold.value >= 18 || threshold.label == 'Z5'
                ? _OF.red
                : _OF.orange)
            .withOpacity(.52)
        ..strokeWidth = 1.2;
      canvas.drawLine(Offset(chart.left, y), Offset(chart.right, y), paint);
      final tp = TextPainter(
        text: TextSpan(
            text: '${threshold.label} ${threshold.value.toStringAsFixed(0)}',
            style: TextStyle(
                color: paint.color.withOpacity(.95),
                fontSize: 9.6,
                fontWeight: FontWeight.w900)),
        textDirection: TextDirection.ltr,
      )..layout(maxWidth: 64);
      tp.paint(canvas, Offset(chart.right - tp.width - 4, y - tp.height - 2));
    }

    double xOf(_LiveMetricPoint p) =>
        chart.left + ((p.timeMs - minTime) / spanTime) * chart.width;
    double yOf(_LiveMetricPoint p) => yForValue(p.value);

    if (loadPoints.isNotEmpty) {
      final load = List<_LiveMetricPoint>.from(loadPoints)
        ..sort((a, b) => a.timeMs.compareTo(b.timeMs));
      double loadY(_LiveMetricPoint point) =>
          chart.bottom -
          (point.value.clamp(0.0, 100.0).toDouble() / 100.0) *
              chart.height *
              .34;
      final loadPath = Path();
      for (var i = 0; i < load.length; i++) {
        final offset = Offset(xOf(load[i]), loadY(load[i]));
        if (i == 0) {
          loadPath.moveTo(offset.dx, offset.dy);
        } else {
          loadPath.lineTo(offset.dx, offset.dy);
        }
      }
      canvas.drawPath(
        loadPath,
        Paint()
          ..color = _OF.green.withOpacity(.14)
          ..strokeWidth = 5
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
      canvas.drawPath(
        loadPath,
        Paint()
          ..color = _OF.green.withOpacity(.82)
          ..strokeWidth = 1.7
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
      final markerStep = math.max(1, (load.length / 72).ceil());
      for (var i = 0; i < load.length; i += markerStep) {
        final point = load[i];
        if (point.value < 8) continue;
        final offset = Offset(xOf(point), loadY(point));
        final color = point.value >= 75
            ? _OF.red
            : (point.value >= 52 ? _OF.orange : _OF.green);
        canvas.drawCircle(
          offset,
          point.value >= 52 ? 3.6 : 2.8,
          Paint()..color = Colors.white.withOpacity(.96),
        );
        canvas.drawCircle(
          offset,
          point.value >= 52 ? 2.5 : 1.9,
          Paint()..color = color,
        );
      }
    }

    for (final item in series) {
      final pts = item.points;
      if (pts.isEmpty) continue;
      final path = Path();
      for (var i = 0; i < pts.length; i++) {
        final o = Offset(xOf(pts[i]), yOf(pts[i]));
        if (i == 0) {
          path.moveTo(o.dx, o.dy);
        } else {
          path.lineTo(o.dx, o.dy);
        }
      }
      canvas.drawPath(
          path,
          Paint()
            ..color = item.color.withOpacity(.20)
            ..strokeWidth = 5.4
            ..style = PaintingStyle.stroke
            ..strokeCap = StrokeCap.round
            ..strokeJoin = StrokeJoin.round);
      canvas.drawPath(
          path,
          Paint()
            ..color = item.color.withOpacity(.88)
            ..strokeWidth = 2.1
            ..style = PaintingStyle.stroke
            ..strokeCap = StrokeCap.round
            ..strokeJoin = StrokeJoin.round);
      for (final p in pts) {
        if (highlightAbove == null || p.value < highlightAbove!) continue;
        final o = Offset(xOf(p), yOf(p));
        canvas.drawCircle(o, 4.8, Paint()..color = _OF.red.withOpacity(.08));
        canvas.drawCircle(o, 2.7, Paint()..color = _OF.red.withOpacity(.9));
      }
      final last = pts.last;
      final lo = Offset(xOf(last), yOf(last));
      canvas.drawCircle(
          lo, 5.2, Paint()..color = Colors.white.withOpacity(.95));
      canvas.drawCircle(lo, 3.4, Paint()..color = item.color);
    }

    if (cursorFraction != null) {
      final fraction = cursorFraction!.clamp(0.0, 1.0).toDouble();
      final cursorX = chart.left + chart.width * fraction;
      final cursorTime = minTime + (spanTime * fraction).round();
      canvas.drawLine(
        Offset(cursorX, chart.top),
        Offset(cursorX, chart.bottom),
        Paint()
          ..color = _OF.graphite.withOpacity(.30)
          ..strokeWidth = 1.1,
      );

      _LiveMetricPoint? primaryPoint;
      Color primaryColor = _OF.green;
      for (final item in series) {
        if (item.points.isEmpty) continue;
        _LiveMetricPoint nearest = item.points.first;
        var best = (nearest.timeMs - cursorTime).abs();
        for (final point in item.points.skip(1)) {
          final distance = (point.timeMs - cursorTime).abs();
          if (distance < best) {
            best = distance;
            nearest = point;
          }
        }
        primaryPoint ??= nearest;
        if (identical(primaryPoint, nearest)) primaryColor = item.color;
        final marker = Offset(xOf(nearest), yOf(nearest));
        canvas.drawCircle(marker, 5.2, Paint()..color = Colors.white);
        canvas.drawCircle(marker, 3.2, Paint()..color = item.color);
      }

      if (primaryPoint != null) {
        final label = '${primaryPoint!.value.toStringAsFixed(0)}$valueSuffix';
        final labelPainter = TextPainter(
          text: TextSpan(
            text: label,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 9.8,
              fontWeight: FontWeight.w900,
            ),
          ),
          textDirection: TextDirection.ltr,
        )..layout(maxWidth: 90);
        final boxWidth = labelPainter.width + 14;
        final boxHeight = labelPainter.height + 8;
        final preferredLeft = cursorX + 7;
        final boxLeft = preferredLeft + boxWidth > chart.right
            ? cursorX - boxWidth - 7
            : preferredLeft;
        final boxTop = chart.top + 5;
        final boxRect = RRect.fromRectAndRadius(
          Rect.fromLTWH(boxLeft, boxTop, boxWidth, boxHeight),
          const Radius.circular(7),
        );
        canvas.drawRRect(boxRect, Paint()..color = primaryColor.withOpacity(.94));
        labelPainter.paint(
          canvas,
          Offset(boxLeft + 7, boxTop + 4),
        );
      }
    }

    final footerStyle = TextStyle(
        color: _OF.muted2.withOpacity(.72),
        fontSize: 9.6,
        fontWeight: FontWeight.w700);
    final footerPoint = heartPoints.isEmpty
        ? null
        : heartPoints.reduce(
            (a, b) => a.timeMs >= b.timeMs ? a : b,
          );
    final rightText = footerPoint == null
        ? 'Нет данных Polar'
        : '${footerPoint.value.toStringAsFixed(0)}$valueSuffix';
    final tp = TextPainter(
        text: TextSpan(text: rightText, style: footerStyle),
        textDirection: TextDirection.ltr)
      ..layout(maxWidth: 90);
    tp.paint(canvas, Offset(chart.right - tp.width, chart.bottom + 7));
  }

  @override
  bool shouldRepaint(covariant _LiveLineChartPainter oldDelegate) => true;
}

