    this.showHeatmap = true,
    this.showTrace = true,
    this.showLabels = true,
    this.showLoadHotPoints = false,
    this.showTeamShapeConnections = false,
    this.showPassingNetwork = false,
    this.showTacticalLines = false,
    this.showOffsideGuide = false,
    this.showControlZones = false,
    this.showTeamCenter = false,
    this.showPitchZones = false,
    this.tacticalSnapshot,
    this.warningEvents = const <TrackerLiveEventModel>[],
    this.selectedWarningEventId,
  }) : super(repaint: repaint);

  final TrackerFieldModel? field;
  final List<_RuntimeTrack> tracks;
  final _RuntimeMotionCache? motionCache;
  final String? focusedTrackKey;
  final bool showVectors;
  final bool showHeatmap;
  final bool showTrace;
  final bool showLabels;
  final bool showLoadHotPoints;
  final bool showTeamShapeConnections;
  final bool showPassingNetwork;
  final bool showTacticalLines;
  final bool showOffsideGuide;
  final bool showControlZones;
  final bool showTeamCenter;
  final bool showPitchZones;
  final _LiveTacticalSnapshot? tacticalSnapshot;
  final List<TrackerLiveEventModel> warningEvents;
  final String? selectedWarningEventId;

  @override
  void paint(Canvas canvas, Size size) {
    final full = Offset.zero & size;

    // V203 LIVE/REPLAY FIELD PARITY:
    // раньше Live вписывал физическое 105×68 в доступный прямоугольник,
    // из-за чего вокруг поля появлялись большие светлые поля и в 3D оно
    // выглядело меньше карты разбора. В разборе газон заполняет canvas,
    // поэтому Live теперь использует ту же full-bleed геометрию.
    _drawRealPitch(canvas, full);
    final pitch = Rect.fromLTWH(
      10,
      10,
      math.max(1.0, size.width - 20),
      math.max(1.0, size.height - 20),
    );
    if (showPitchZones) {
      _drawPitchTacticalZones(canvas, pitch);
    }

    final allPoints = tracks.expand((t) => t.points).toList();
    final hasWarningPoints = warningEvents.any(
      (event) => event.latitude != null && event.longitude != null,
    );
    if (allPoints.isEmpty && !hasWarningPoints) {
      _drawCenterText(
        canvas,
        full,
        field?.hasCalibration == true
            ? 'Ждём GPS от трекера'
            : 'Откалибруйте поле по 4 углам',
      );
      return;
    }

    final bounds = _mapBounds(allPoints, warningEvents);

    if (showControlZones) {
      _drawControlZones(canvas, pitch);
    }

    if (showHeatmap && allPoints.isNotEmpty) {
      _drawHeatLayer(canvas, pitch, allPoints, bounds);
    }

    if (showTeamShapeConnections) {
      _drawTeamShapeConnections(canvas, pitch, bounds);
    }
    if (showPassingNetwork) {
      _drawPassingNetwork(canvas, pitch);
    }
    if (showTacticalLines || showOffsideGuide) {
      _drawTacticalLines(canvas, pitch);
    }

    for (final track in tracks) {
      if (track.points.isEmpty) continue;
      final focused = focusedTrackKey != null && track.key == focusedTrackKey;
      if (showTrace) _drawTrace(canvas, pitch, track, bounds, focused: focused);
      if (showLoadHotPoints) _drawLoadHotPoints(canvas, pitch, track, bounds);
      if (showVectors)
        _drawVector(canvas, pitch, track, bounds, focused: focused);
      _drawPlayer(canvas, pitch, track, bounds, focused: focused);
      if (showLabels) _drawPlayerLabel(canvas, pitch, track, bounds);
    }

    _drawWarningEvents(canvas, pitch, bounds);
    if (showTeamCenter) {
      _drawTeamCenter(canvas, pitch);
    }
    if (showTacticalLines || showOffsideGuide || showPassingNetwork) {
      _drawAttackDirection(canvas, pitch);
    }
  }

  void _drawBackground(Canvas canvas, Rect full) {
// Светлая CMR-подложка без чёрного фона вокруг поля.
    canvas.drawRRect(
      RRect.fromRectAndRadius(full, const Radius.circular(8)),
      Paint()..color = const Color(0xFFF8F9FA),
    );

    final grid = Paint()
      ..color = const Color(0xFFE1E5E2).withOpacity(.34)
      ..strokeWidth = .6;

    const step = 32.0;
    for (double x = 0; x <= full.width; x += step) {
      canvas.drawLine(
        Offset(full.left + x, full.top),
        Offset(full.left + x, full.bottom),
        grid,
      );
    }
    for (double y = 0; y <= full.height; y += step) {
      canvas.drawLine(
        Offset(full.left, full.top + y),
        Offset(full.right, full.top + y),
        grid,
      );
    }
  }

  Rect _fitPitch(Rect area) {
    final length = field?.lengthM ?? 105.0;
    final width = field?.widthM ?? 68.0;
    final aspect = length / width;

    var w = area.width;
    var h = w / aspect;
    if (h > area.height) {
      h = area.height;
      w = h * aspect;
    }

    return Rect.fromCenter(center: area.center, width: w, height: h);
  }

  void _drawRealPitch(Canvas canvas, Rect pitch) {
    // Держим поле пиксельно согласованным с _ActionPitchPainter из карты
    // разбора: те же оттенки газона, полосы, линии и пропорции разметки.
    final border = RRect.fromRectAndRadius(pitch, const Radius.circular(16));
    canvas.drawRRect(border, Paint()..color = const Color(0xFF76947B));

    final clip = Path()..addRRect(border.deflate(8));
    canvas.save();
    canvas.clipPath(clip);
    final stripeW = math.max(36.0, pitch.width / 12);
    for (var i = 0; i < 14; i++) {
      final color =
          i.isEven ? const Color(0xFF719078) : const Color(0xFF819E86);
      canvas.drawRect(
        Rect.fromLTWH(
          pitch.left + 8 + i * stripeW,
          pitch.top + 8,
          stripeW,
          math.max(1.0, pitch.height - 16),
        ),
        Paint()..color = color,
      );
    }
    canvas.restore();

    final line = Paint()
      ..color = Colors.white.withOpacity(.78)
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    final inner = pitch.deflate(10);

    canvas.drawRRect(
      RRect.fromRectAndRadius(inner, const Radius.circular(12)),
      line,
    );
    canvas.drawLine(
      Offset(inner.center.dx, inner.top),
      Offset(inner.center.dx, inner.bottom),
      line,
    );
    canvas.drawCircle(
      inner.center,
      math.min(pitch.width, pitch.height) * .12,
      line,
    );

    canvas.drawRect(
      Rect.fromLTWH(
        inner.left,
        pitch.top + pitch.height * .28,
        pitch.width * .17,
        pitch.height * .44,
      ),
      line,
    );
    canvas.drawRect(
      Rect.fromLTWH(
        inner.left,
        pitch.top + pitch.height * .38,
        pitch.width * .08,
        pitch.height * .24,
      ),
      line,
    );
    canvas.drawRect(
      Rect.fromLTWH(
        inner.right - pitch.width * .17,
        pitch.top + pitch.height * .28,
        pitch.width * .17,
        pitch.height * .44,
      ),
      line,
    );
    canvas.drawRect(
      Rect.fromLTWH(
        inner.right - pitch.width * .08,
        pitch.top + pitch.height * .38,
        pitch.width * .08,
        pitch.height * .24,
      ),
      line,
    );
    canvas.drawCircle(
      Offset(pitch.left + pitch.width * .13, pitch.center.dy),
      3,
      Paint()..color = Colors.white.withOpacity(.75),
    );
    canvas.drawCircle(
      Offset(pitch.left + pitch.width * .87, pitch.center.dy),
      3,
      Paint()..color = Colors.white.withOpacity(.75),
    );
  }

  Offset _tacticalOffset(_LiveTacticalPlayerPosition player, Rect pitch) {
    return Offset(
      pitch.left + player.nx.clamp(0.0, 1.0) * pitch.width,
      pitch.bottom - player.ny.clamp(0.0, 1.0) * pitch.height,
    );
  }

  void _drawPitchTacticalZones(Canvas canvas, Rect pitch) {
    final thirds = <Color>[
      const Color(0xFF4C7A63).withOpacity(.055),
      const Color(0xFFFFFFFF).withOpacity(.025),
      const Color(0xFFB7863C).withOpacity(.045),
    ];
    for (var i = 0; i < 3; i++) {
      final x = pitch.left + pitch.width * i / 3.0;
      canvas.drawRect(
        Rect.fromLTWH(x, pitch.top, pitch.width / 3.0, pitch.height),
        Paint()..color = thirds[i],
      );
    }
    final grid = Paint()
      ..color = Colors.white.withOpacity(.20)
      ..strokeWidth = .8;
    for (var i = 1; i < 3; i++) {
      final x = pitch.left + pitch.width * i / 3.0;
      canvas.drawLine(Offset(x, pitch.top), Offset(x, pitch.bottom), grid);
    }
    for (var i = 1; i < 5; i++) {
      final y = pitch.top + pitch.height * i / 5.0;
      canvas.drawLine(Offset(pitch.left, y), Offset(pitch.right, y),
          Paint()..color = Colors.white.withOpacity(.08));
    }

    final labels = <String>['ЗОНА 1', 'ЗОНА 2', 'ЗОНА 3'];
    for (var i = 0; i < 3; i++) {
      final tp = TextPainter(
        text: TextSpan(
          text: labels[i],
          style: TextStyle(
            color: Colors.white.withOpacity(.34),
            fontSize: 7.0,
            fontWeight: FontWeight.w800,
            letterSpacing: .25,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(
        canvas,
        Offset(
          pitch.left + pitch.width * (i + .5) / 3.0 - tp.width / 2,
          pitch.top + 7,
        ),
      );
    }
  }

  void _drawControlZones(Canvas canvas, Rect pitch) {
    final snapshot = tacticalSnapshot;
    if (snapshot == null || snapshot.players.length < 2) return;
    final points = snapshot.players
        .map((player) => _tacticalOffset(player, pitch))
        .toList(growable: false);

    for (var i = 0; i < points.length; i++) {
      var polygon = <Offset>[
        pitch.topLeft,
        pitch.topRight,
        pitch.bottomRight,
        pitch.bottomLeft,
      ];
      final pi = points[i];
      for (var j = 0; j < points.length && polygon.isNotEmpty; j++) {
        if (i == j) continue;
        final pj = points[j];
        final normal = pj - pi;
        final c = (pj.dx * pj.dx + pj.dy * pj.dy -
                pi.dx * pi.dx -
                pi.dy * pi.dy) /
            2.0;
        polygon = _clipTacticalPolygon(polygon, normal, c);
      }
      if (polygon.length < 3) continue;
      final path = Path()..moveTo(polygon.first.dx, polygon.first.dy);
      for (final point in polygon.skip(1)) {
        path.lineTo(point.dx, point.dy);
      }
      path.close();
      final color = _liveTrackColorForKey(snapshot.players[i].trackKey);
      canvas.drawPath(path, Paint()..color = color.withOpacity(.055));
      canvas.drawPath(
        path,
        Paint()
          ..color = color.withOpacity(.20)
          ..style = PaintingStyle.stroke
          ..strokeWidth = .75,
      );
    }
  }

  List<Offset> _clipTacticalPolygon(
    List<Offset> polygon,
    Offset normal,
    double c,
  ) {
    if (polygon.isEmpty) return const <Offset>[];
    double side(Offset point) => point.dx * normal.dx + point.dy * normal.dy - c;
    final result = <Offset>[];
    for (var i = 0; i < polygon.length; i++) {
      final a = polygon[i];
      final b = polygon[(i + 1) % polygon.length];
      final sa = side(a);
      final sb = side(b);
      final aInside = sa <= .0001;
      final bInside = sb <= .0001;
      if (aInside) result.add(a);
      if (aInside != bInside) {
        final denominator = sa - sb;
        if (denominator.abs() > .000001) {
          final t = (sa / denominator).clamp(0.0, 1.0).toDouble();
          result.add(Offset(
            a.dx + (b.dx - a.dx) * t,
            a.dy + (b.dy - a.dy) * t,
          ));
        }
      }
    }
    return result;
  }

  void _drawPassingNetwork(Canvas canvas, Rect pitch) {
    final snapshot = tacticalSnapshot;
    if (snapshot == null || snapshot.players.length < 3) return;
    final players = snapshot.players;
    final screen = players
        .map((player) => _tacticalOffset(player, pitch))
        .toList(growable: false);
    final edges = <String>{};
    final triangles = <String>{};

    double distanceM(int a, int b) {
      final dx = players[a].xM - players[b].xM;
      final dy = players[a].yM - players[b].yM;
      return math.sqrt(dx * dx + dy * dy);
    }

    for (var i = 0; i < players.length; i++) {
      final nearest = <({int index, double distance})>[];
      for (var j = 0; j < players.length; j++) {
        if (i == j) continue;
        nearest.add((index: j, distance: distanceM(i, j)));
      }
      nearest.sort((a, b) => a.distance.compareTo(b.distance));
      final picked = nearest.where((e) => e.distance <= 34.0).take(3).toList();
      for (final target in picked) {
        final a = math.min(i, target.index).toInt();
        final b = math.max(i, target.index).toInt();
        final key = '$a:$b';
        if (!edges.add(key)) continue;
        final closeness = (1.0 - target.distance / 34.0).clamp(.0, 1.0).toDouble();
        canvas.drawLine(
          screen[a],
          screen[b],
          Paint()
            ..color = const Color(0xFFFFC857).withOpacity(.18 + .35 * closeness)
            ..strokeWidth = .8 + 1.25 * closeness
            ..strokeCap = StrokeCap.round,
        );
      }
      if (picked.length >= 2) {
        final a = i;
        final b = picked[0].index;
        final c = picked[1].index;
        if (distanceM(b, c) <= 34.0) {
          final order = <int>[a, b, c]..sort();
          final key = '${order[0]}:${order[1]}:${order[2]}';
          if (triangles.add(key)) {
            final path = Path()
              ..moveTo(screen[a].dx, screen[a].dy)
              ..lineTo(screen[b].dx, screen[b].dy)
              ..lineTo(screen[c].dx, screen[c].dy)
              ..close();
            canvas.drawPath(
              path,
              Paint()..color = const Color(0xFFFFC857).withOpacity(.035),
            );
          }
        }
      }
    }
  }

  void _drawTacticalLines(Canvas canvas, Rect pitch) {
    final snapshot = tacticalSnapshot;
    if (snapshot == null || snapshot.players.length < 3) return;

    if (showTacticalLines) {
      _drawNamedTacticalLine(
        canvas,
        pitch,
        snapshot.defenseLineNx,
        'ОБОРОНА',
        const Color(0xFF66D9A0),
      );
      _drawNamedTacticalLine(
        canvas,
        pitch,
        snapshot.midfieldLineNx,
        'ПОЛУЗАЩИТА',
        const Color(0xFFFFD166),
      );
      _drawNamedTacticalLine(
        canvas,
        pitch,
        snapshot.attackLineNx,
        'АТАКА',
        const Color(0xFFFF8C66),
      );
      _drawLineGapLabel(
        canvas,
        pitch,
        snapshot.defenseLineNx,
        snapshot.midfieldLineNx,
        snapshot.defenseMidGapM,
      );
      _drawLineGapLabel(
        canvas,
        pitch,
        snapshot.midfieldLineNx,
        snapshot.attackLineNx,
        snapshot.midAttackGapM,
      );
    }

    if (showOffsideGuide && snapshot.offsideGuideNx != null) {
      final x = pitch.left + snapshot.offsideGuideNx!.clamp(0.0, 1.0) * pitch.width;
      final paint = Paint()
        ..color = const Color(0xFFFF5D69).withOpacity(.88)
        ..strokeWidth = 1.35;
      const dash = 7.0;
      const gap = 5.0;
      var y = pitch.top + 2;
      while (y < pitch.bottom - 2) {
        final end = math.min(pitch.bottom - 2, y + dash).toDouble();
        canvas.drawLine(Offset(x, y), Offset(x, end), paint);
        y = end + gap;
      }
      _drawTacticalTag(
        canvas,
        Offset(x, pitch.bottom - 18),
        'ОФСАЙД · ОРИЕНТИР',
        const Color(0xFFFF5D69),
      );
    }
  }

  void _drawNamedTacticalLine(
    Canvas canvas,
    Rect pitch,
    double? nx,
    String label,
    Color color,
  ) {
    if (nx == null) return;
    final x = pitch.left + nx.clamp(0.0, 1.0) * pitch.width;
    canvas.drawLine(
      Offset(x, pitch.top + 2),
      Offset(x, pitch.bottom - 2),
      Paint()
        ..color = color.withOpacity(.78)
        ..strokeWidth = 1.4,
    );
    canvas.drawLine(
      Offset(x - 3, pitch.top + 4),
      Offset(x + 3, pitch.top + 4),
      Paint()
        ..color = color
        ..strokeWidth = 2.0,
    );
    _drawTacticalTag(canvas, Offset(x, pitch.top + 18), label, color);
  }

  void _drawLineGapLabel(
    Canvas canvas,
    Rect pitch,
    double? a,
    double? b,
    double? distanceM,
  ) {
    if (a == null || b == null || distanceM == null) return;
    final x1 = pitch.left + a.clamp(0.0, 1.0) * pitch.width;
    final x2 = pitch.left + b.clamp(0.0, 1.0) * pitch.width;
    final left = math.min(x1, x2).toDouble();
    final right = math.max(x1, x2).toDouble();
    final y = pitch.top + 36;
    final color = distanceM > 23.0 ? const Color(0xFFFFB44F) : Colors.white;
    canvas.drawLine(
      Offset(left + 3, y),
      Offset(right - 3, y),
      Paint()
        ..color = color.withOpacity(.50)
        ..strokeWidth = .9,
    );
    final tp = TextPainter(
      text: TextSpan(
        text: '${distanceM.toStringAsFixed(1)} м',
        style: TextStyle(
          color: color.withOpacity(.92),
          fontSize: 7.0,
          fontWeight: FontWeight.w900,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset((left + right - tp.width) / 2, y - 11));
  }

  void _drawTacticalTag(Canvas canvas, Offset anchor, String text, Color color) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: const TextStyle(
          color: Colors.white,
          fontSize: 6.7,
          fontWeight: FontWeight.w900,
          letterSpacing: .15,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    final rect = RRect.fromRectAndRadius(
      Rect.fromLTWH(
        anchor.dx - tp.width / 2 - 5,
        anchor.dy - 8,
        tp.width + 10,
        16,
      ),
      const Radius.circular(6),
    );
    canvas.drawRRect(rect, Paint()..color = color.withOpacity(.78));
    tp.paint(canvas, Offset(rect.left + 5, rect.top + 4));
  }

  void _drawTeamCenter(Canvas canvas, Rect pitch) {
    final snapshot = tacticalSnapshot;
    if (snapshot == null || snapshot.players.length < 2) return;
    final cx = pitch.left + snapshot.centroidNx.clamp(0.0, 1.0) * pitch.width;
    final cy = pitch.bottom - snapshot.centroidNy.clamp(0.0, 1.0) * pitch.height;
    final positions = snapshot.players;
    final minX = positions.map((p) => p.nx).reduce(math.min);
    final maxX = positions.map((p) => p.nx).reduce(math.max);
    final minY = positions.map((p) => p.ny).reduce(math.min);
    final maxY = positions.map((p) => p.ny).reduce(math.max);
    final left = pitch.left + minX * pitch.width;
    final right = pitch.left + maxX * pitch.width;
    final top = pitch.bottom - maxY * pitch.height;
    final bottom = pitch.bottom - minY * pitch.height;
    final guide = Paint()
      ..color = Colors.white.withOpacity(.24)
      ..strokeWidth = .9;
    canvas.drawLine(Offset(left, cy), Offset(right, cy), guide);
    canvas.drawLine(Offset(cx, top), Offset(cx, bottom), guide);

    canvas.drawCircle(cx.isFinite && cy.isFinite ? Offset(cx, cy) : pitch.center,
        10, Paint()..color = const Color(0xFF64E29B).withOpacity(.15));
    canvas.drawCircle(
      Offset(cx, cy),
      5.5,
      Paint()
        ..color = const Color(0xFF64E29B)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.7,
    );
    canvas.drawLine(Offset(cx - 8, cy), Offset(cx + 8, cy),
        Paint()..color = const Color(0xFF64E29B).withOpacity(.75));
    canvas.drawLine(Offset(cx, cy - 8), Offset(cx, cy + 8),
        Paint()..color = const Color(0xFF64E29B).withOpacity(.75));

    _drawTacticalTag(
      canvas,
      Offset(cx, cy + 18),
      'ЦЕНТР ${snapshot.centerProgressPct.toStringAsFixed(0)}%',
      const Color(0xFF2E8B57),
    );
  }

  void _drawAttackDirection(Canvas canvas, Rect pitch) {
    final snapshot = tacticalSnapshot;
    if (snapshot == null || snapshot.players.isEmpty) return;
    final right = snapshot.attackRight;
    final center = Offset(pitch.center.dx, pitch.bottom - 9);
    final start = Offset(center.dx + (right ? -30 : 30), center.dy);
    final end = Offset(center.dx + (right ? 30 : -30), center.dy);
    final paint = Paint()
      ..color = Colors.white.withOpacity(.52)
      ..strokeWidth = 1.4
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(start, end, paint);
    final direction = right ? 1.0 : -1.0;
    canvas.drawLine(end, Offset(end.dx - direction * 7, end.dy - 4), paint);
    canvas.drawLine(end, Offset(end.dx - direction * 7, end.dy + 4), paint);
    final tp = TextPainter(
      text: const TextSpan(
        text: 'АТАКА',
        style: TextStyle(
          color: Colors.white70,
          fontSize: 6.5,
          fontWeight: FontWeight.w900,
          letterSpacing: .25,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width / 2, center.dy - 15));
  }


  _MapBounds _mapBounds(
    List<_RuntimePoint> allPoints,
    List<TrackerLiveEventModel> events,
  ) {
    final latValues = <double>[];
    final lonValues = <double>[];

    for (final p in allPoints) {
      if (p.lat.isFinite && p.lon.isFinite) {
        latValues.add(p.lat);
        lonValues.add(p.lon);
      }
    }

    for (final event in events) {
      final lat = event.latitude;
      final lon = event.longitude;
      if (lat != null && lon != null && lat.isFinite && lon.isFinite) {
        latValues.add(lat);
        lonValues.add(lon);
      }
    }
    final selectedField = field;
    if (latValues.isEmpty &&
        lonValues.isEmpty &&
        selectedField?.hasCalibration == true) {
      final cornersLat = <double?>[
        selectedField!.cornerALat,
        selectedField.cornerBLat,
        selectedField.cornerCLat,
        selectedField.cornerDLat,
      ];
      final cornersLon = <double?>[
        selectedField.cornerALng,
        selectedField.cornerBLng,
        selectedField.cornerCLng,
        selectedField.cornerDLng,
      ];
      latValues.addAll(cornersLat.whereType<double>());
      lonValues.addAll(cornersLon.whereType<double>());
    }

    if (latValues.isEmpty || lonValues.isEmpty) {
      // Нет ни GPS-точек, ни валидных углов поля: рисуем стабильный пустой диапазон,
      // а не падаем на reduce()/null-check при первом открытии мобильного Live.
      return const _MapBounds(
          minLat: -0.00005, maxLat: 0.00005, minLon: -0.00005, maxLon: 0.00005);
    }

    var minLat = latValues.reduce(math.min);
    var maxLat = latValues.reduce(math.max);
    var minLon = lonValues.reduce(math.min);
    var maxLon = lonValues.reduce(math.max);

// Если GPS-точки почти не сдвинулись, добавляем небольшой диапазон,
// чтобы точка не прыгала по всему полю.
    if ((maxLat - minLat).abs() < 0.00001) {
      minLat -= 0.00005;
      maxLat += 0.00005;
    }
    if ((maxLon - minLon).abs() < 0.00001) {
      minLon -= 0.00005;
      maxLon += 0.00005;
    }

    return _MapBounds(
        minLat: minLat, maxLat: maxLat, minLon: minLon, maxLon: maxLon);
  }

  void _drawHeatLayer(Canvas canvas, Rect pitch, List<_RuntimePoint> points,
      _MapBounds bounds) {
    final lastPoints =
        points.length > 160 ? points.sublist(points.length - 160) : points;
    for (final p in lastPoints) {
      final pos = _project(p, pitch, bounds);
      final intensity = (p.speedKmh / 28).clamp(.12, .9).toDouble();
      final color = p.speedKmh >= 25
          ? _C.red
          : p.speedKmh >= 14.0
              ? _C.orange
              : _C.greenDark;

      final radius = 12 + 18 * intensity;
      canvas.drawCircle(
        pos,
        radius,
        Paint()
          ..shader = RadialGradient(
            colors: [
              color.withOpacity(.13 * intensity),
              color.withOpacity(.035 * intensity),
              Colors.transparent,
            ],
          ).createShader(Rect.fromCircle(center: pos, radius: radius)),
      );
    }
  }

  void _drawTrace(
    Canvas canvas,
    Rect pitch,
    _RuntimeTrack track,
    _MapBounds bounds, {
    required bool focused,
  }) {
    if (track.points.length < 2) return;

    final path = Path();
    for (var i = 0; i < track.points.length; i++) {
      final p = _project(track.points[i], pitch, bounds);
      if (i == 0) {
        path.moveTo(p.dx, p.dy);
      } else {
        path.lineTo(p.dx, p.dy);
      }
    }

    canvas.drawPath(
      path,
      Paint()
        ..color = Colors.black.withOpacity(.08)
        ..strokeWidth = 5.5
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );

    canvas.drawPath(
      path,
      Paint()
        ..color = focused
            ? _OF.green.withOpacity(.92)
            : _trackAccentColor(track).withOpacity(.88)
        ..strokeWidth = focused ? 3.0 : 1.8
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );
  }

  void _drawLoadHotPoints(
      Canvas canvas, Rect pitch, _RuntimeTrack track, _MapBounds bounds) {
    if (track.points.isEmpty) return;
    for (final point in track.points) {
      final hot = point.speedKmh >= 18.0 || point.distanceDeltaM >= 5.0;
      final mid = point.speedKmh >= 14.0 || point.distanceDeltaM >= 3.0;
      if (!hot && !mid) continue;
      final pos = _project(point, pitch, bounds);
      final color = hot ? _C.red : _C.orange;
      final radius = hot ? 6.2 : 4.6;
      canvas.drawCircle(
          pos, radius + 4, Paint()..color = color.withOpacity(.13));
      canvas.drawCircle(
          pos, radius, Paint()..color = color.withOpacity(hot ? .88 : .76));
      canvas.drawCircle(
        pos,
        radius + 1.6,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1
          ..color = Colors.white.withOpacity(.72),
      );
    }
  }

  void _drawWarningEvents(
    Canvas canvas,
    Rect pitch,
    _MapBounds bounds,
  ) {
    if (warningEvents.isEmpty) return;
    for (final event in warningEvents) {
      final lat = event.latitude;
      final lon = event.longitude;
      if (lat == null || lon == null || !lat.isFinite || !lon.isFinite) {
        continue;
      }
      final point = _RuntimePoint(
        lat: lat,
        lon: lon,
        timeMs: event.timeMs,
        speedKmh: event.speedKmh,
        rawSpeedKmh: event.speedKmh,
        distanceDeltaM: 0,
        packetType: 'live-event',
      );
      final pos = _project(point, pitch, bounds);
      final selected = event.id == selectedWarningEventId;
      final color = event.isRed ? _OF.red : _OF.orange;
      final radius = selected ? 8.4 : 5.7;

      canvas.drawCircle(
        pos,
        selected ? radius + 9 : radius + 5,
        Paint()..color = color.withOpacity(selected ? .16 : .10),
      );
      canvas.drawCircle(
        pos,
        radius,
        Paint()..color = color.withOpacity(.94),
      );
      canvas.drawCircle(
        pos,
        radius + 1.8,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = selected ? 2.0 : 1.2
          ..color = Colors.white.withOpacity(.92),
      );
      if (selected) {
        canvas.drawCircle(
          pos,
          radius + 6,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2.2
            ..color = color.withOpacity(.82),
        );
      }

      final tp = TextPainter(
        text: TextSpan(
          text: '!',
          style: TextStyle(
            color: Colors.white,
            fontSize: selected ? 10.0 : 7.5,
            fontWeight: FontWeight.w900,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(pos.dx - tp.width / 2, pos.dy - tp.height / 2));
    }
  }

  void _drawTeamShapeConnections(
    Canvas canvas,
    Rect pitch,
    _MapBounds bounds,
  ) {
    final available = tracks.where((track) => track.points.isNotEmpty).toList();
    if (available.length < 3) return;
    var newest = 0;
    for (final track in available) {
      newest = math.max(newest, track.points.last.timeMs).toInt();
    }
    final positions = <Offset>[];
    for (final track in available) {
      final last = track.points.last;
      // Как в аналитике: давно пропавшего игрока не тянем в командную форму.
      if (newest > 0 && newest - last.timeMs > 15000) continue;
      positions.add(_projectTrackCurrent(track, pitch, bounds));
    }
    if (positions.length < 3) return;
    final hull = _runtimeConvexHull(positions);
    if (hull.length < 3) return;
    final path = Path()..moveTo(hull.first.dx, hull.first.dy);
    for (final point in hull.skip(1)) {
      path.lineTo(point.dx, point.dy);
    }
    path.close();
    const amber = Color(0xFFF59E0B);
    canvas.drawPath(
      path,
      Paint()
        ..color = amber.withOpacity(.10)
        ..style = PaintingStyle.fill,
    );
    canvas.drawPath(
      path,
      Paint()
        ..color = amber.withOpacity(.18)
        ..strokeWidth = 5.0
        ..style = PaintingStyle.stroke,
    );
    canvas.drawPath(
      path,
      Paint()
        ..color = amber.withOpacity(.96)
        ..strokeWidth = 1.8
        ..style = PaintingStyle.stroke,
    );
  }

  void _drawVector(
    Canvas canvas,
    Rect pitch,
    _RuntimeTrack track,
    _MapBounds bounds, {
    required bool focused,
  }) {
    if (track.points.length < 2 || track.lastDeltaM <= 0.25) return;

    final pos = _projectTrackCurrent(track, pitch, bounds);
    final angle = track.headingDeg * math.pi / 180.0;
    final length = (24 + track.speedKmh * 1.4).clamp(24.0, 62.0);
    final end = Offset(
      pos.dx + math.sin(angle) * length,
      pos.dy - math.cos(angle) * length,
    );

    final paint = Paint()
      ..color =
          (focused ? _OF.green : _trackAccentColor(track)).withOpacity(.88)
      ..strokeWidth = 2.4
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(pos, end, paint);

    final head1 = angle + math.pi * .78;
    final head2 = angle - math.pi * .78;
    final h = 10.0;
    canvas.drawLine(
        end,
        Offset(end.dx + math.sin(head1) * h, end.dy - math.cos(head1) * h),
        paint);
    canvas.drawLine(
        end,
        Offset(end.dx + math.sin(head2) * h, end.dy - math.cos(head2) * h),
        paint);
  }

  void _drawPlayer(
    Canvas canvas,
    Rect pitch,
    _RuntimeTrack track,
    _MapBounds bounds, {
    required bool focused,
  }) {
    final pos = _projectTrackCurrent(track, pitch, bounds);
    final color = focused ? _OF.green : _trackAccentColor(track);
    final coreRadius = focused ? 11.5 : 8.0;

    canvas.drawCircle(
      pos,
      focused ? 19 : 13,
      Paint()
        ..color = color.withOpacity(.08)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 7),
    );
    canvas.drawCircle(pos, coreRadius, Paint()..color = color);
    canvas.drawCircle(
      pos,
      focused ? 15 : 11,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = focused ? 2.2 : 1.6
        ..color = Colors.white.withOpacity(.82),
    );

    final tp = TextPainter(
      text: TextSpan(
        text: track.speedKmh.toStringAsFixed(1),
        style: _OFText.value(
          11.0,
          color: const Color(0xFFF4F5F6),
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: 36);
    tp.paint(canvas, pos - Offset(tp.width / 2, tp.height / 2));
  }

  Color _trackAccentColor(_RuntimeTrack track) {
    return _liveTrackColorForKey(track.key);
  }

  void _drawPlayerLabel(
      Canvas canvas, Rect pitch, _RuntimeTrack track, _MapBounds bounds) {
    final pos = _projectTrackCurrent(track, pitch, bounds);
    final label =
        '${track.playerName} · ${track.speedKmh.toStringAsFixed(1)} км/ч';

    final tp = TextPainter(
      text: TextSpan(
        text: label.length > 30 ? '${label.substring(0, 30)}…' : label,
        style: _OFText.body(
          size: 11.4,
          color: Colors.white,
          weight: FontWeight.w500,
        ).copyWith(
          shadows: const <Shadow>[
            Shadow(color: Colors.black87, blurRadius: 7),
          ],
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: math.min(210, pitch.width * .56));

    final left = (pos.dx + 14)
        .clamp(pitch.left + 6, pitch.right - tp.width - 20)
        .toDouble();
    final top =
        (pos.dy - 34).clamp(pitch.top + 6, pitch.bottom - 28).toDouble();

    final bg = RRect.fromRectAndRadius(
      Rect.fromLTWH(left, top, tp.width + 18, 25),
      const Radius.circular(8),
    );

    canvas.drawRRect(bg, Paint()..color = Colors.black.withOpacity(.34));
    canvas.drawRRect(
      bg,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1
        ..color = Colors.white.withOpacity(.07),
    );
    tp.paint(canvas, Offset(bg.left + 9, bg.top + 5));
  }

  void _drawPitchMeta(Canvas canvas, Rect pitch) {
    final text = field?.hasCalibration == true
        ? '${field!.title} · ${field!.lengthM.toStringAsFixed(0)}×${field!.widthM.toStringAsFixed(0)} м'
        : 'Поле 105×68 · калибровка не задана';

    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: Colors.white.withOpacity(.78),
          fontSize: 11.2,
          fontWeight: FontWeight.w500,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: pitch.width - 24);

    final bg = RRect.fromRectAndRadius(
      Rect.fromLTWH(pitch.left + 10, pitch.bottom - 30, tp.width + 18, 22),
      const Radius.circular(7),
    );
    canvas.drawRRect(bg, Paint()..color = Colors.black.withOpacity(.24));
    tp.paint(canvas, Offset(bg.left + 9, bg.top + 4));
  }

  Offset _projectTrackCurrent(
    _RuntimeTrack track,
    Rect pitch,
    _MapBounds bounds,
  ) {
    final current = motionCache?.resolve(
      track,
      DateTime.now().millisecondsSinceEpoch,
    );
    if (current == null) {
      return _project(track.points.last, pitch, bounds);
    }
    return _projectLatLon(current.lat, current.lon, pitch, bounds);
  }

  Offset _project(_RuntimePoint p, Rect pitch, _MapBounds bounds) {
    return _projectLatLon(p.lat, p.lon, pitch, bounds);
  }

  Offset _projectLatLon(
    double latitude,
    double longitude,
    Rect pitch,
    _MapBounds bounds,
  ) {
    final projected = TrackerPitchProjector.projectGps(
      field,
      latitude: latitude,
      longitude: longitude,
    );
    if (projected != null && projected.isInside) {
      return Offset(
        pitch.left + projected.clampedNx * pitch.width,
        pitch.bottom - projected.clampedNy * pitch.height,
      );
    }

    final lonRange = (bounds.maxLon - bounds.minLon).abs();
    final latRange = (bounds.maxLat - bounds.minLat).abs();

    final nx = lonRange < 0.000001
        ? 0.5
        : ((longitude - bounds.minLon) / lonRange)
            .clamp(0.035, 0.965)
            .toDouble();
    final ny = latRange < 0.000001
        ? 0.5
        : ((latitude - bounds.minLat) / latRange)
            .clamp(0.035, 0.965)
            .toDouble();

    return Offset(
      pitch.left + nx * pitch.width,
      pitch.bottom - ny * pitch.height,
    );
  }

  void _drawCenterText(Canvas canvas, Rect full, String text) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: Colors.white.withOpacity(.86),
          fontSize: full.width < 360 ? 12.5 : 14.5,
          fontWeight: FontWeight.w500,
          letterSpacing: -.15,
        ),
      ),
      textDirection: TextDirection.ltr,
      textAlign: TextAlign.center,
    )..layout(maxWidth: full.width - 48);

    tp.paint(
      canvas,
      Offset(
        (full.width - tp.width) / 2,
        (full.height - tp.height) / 2,
      ),
    );
  }

  @override
  bool shouldRepaint(covariant _RuntimeFieldPainter oldDelegate) => true;
}

List<Offset> _runtimeConvexHull(List<Offset> points) {
  if (points.length <= 3) return List<Offset>.from(points);
  final sorted = List<Offset>.from(points)
    ..sort((a, b) {
      final x = a.dx.compareTo(b.dx);
      return x != 0 ? x : a.dy.compareTo(b.dy);
    });
  double cross(Offset o, Offset a, Offset b) =>
      (a.dx - o.dx) * (b.dy - o.dy) -
      (a.dy - o.dy) * (b.dx - o.dx);
  final lower = <Offset>[];
  for (final point in sorted) {
    while (lower.length >= 2 &&
        cross(lower[lower.length - 2], lower.last, point) <= 0) {
      lower.removeLast();
    }
    lower.add(point);
  }
  final upper = <Offset>[];
  for (final point in sorted.reversed) {
    while (upper.length >= 2 &&
        cross(upper[upper.length - 2], upper.last, point) <= 0) {
      upper.removeLast();
    }
    upper.add(point);
  }
  lower.removeLast();
  upper.removeLast();
  return <Offset>[...lower, ...upper];
}

class _MapBounds {
  const _MapBounds({
    required this.minLat,
    required this.maxLat,
    required this.minLon,
    required this.maxLon,
  });

  final double minLat;
  final double maxLat;
  final double minLon;
  final double maxLon;
}

class _TrackerPlayerAvatarDark extends StatelessWidget {
  const _TrackerPlayerAvatarDark({
    required this.photo,
    required this.name,
    required this.size,
    required this.borderColor,
  });

  final String? photo;
  final String name;
  final double size;
  final Color borderColor;

  @override
  Widget build(BuildContext context) {
    final url = _trackerAbsolutePhotoUrl(photo);
    final initials = _trackerInitials(name);
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: _C.greenSoft,
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: borderColor.withOpacity(.55), width: 1.1),
      ),
      clipBehavior: Clip.antiAlias,
      child: url.isEmpty
          ? Center(
              child: Text(
                initials,
                style: TextStyle(
                    color: _C.green,
                    fontSize: size * .28,
                    fontWeight: FontWeight.w500),
              ),
            )
          : Image.network(
              url,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) => Center(
                child: Text(
                  initials,
                  style: TextStyle(
                      color: _C.green,
                      fontSize: size * .28,
                      fontWeight: FontWeight.w500),
                ),
              ),
            ),
    );
  }
}

String _trackerAbsolutePhotoUrl(String? raw) {
  final value = '${raw ?? ''}'.trim();
  if (value.isEmpty || value == 'null') return '';
  if (value.startsWith('http://') || value.startsWith('https://')) return value;
  final cleaned = value.startsWith('/') ? value.substring(1) : value;
  return 'https://sportotekaapp.ru/$cleaned';
}

String _trackerInitials(String name) {
  final parts =
      name.trim().split(RegExp(r'\s+')).where((e) => e.isNotEmpty).toList();
  if (parts.isEmpty) return 'И';
  if (parts.length == 1) return parts.first.substring(0, 1).toUpperCase();
  return '${parts[0].substring(0, 1)}${parts[1].substring(0, 1)}'.toUpperCase();
}

