      child: Row(
        children: [
          Icon(danger ? Icons.warning_amber_rounded : Icons.insights_rounded,
              color: color),
          const SizedBox(width: 9),
          Expanded(
            child: Text(
              track.recommendation,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                  color: color,
                  fontWeight: FontWeight.w500,
                  fontSize: AppTypography.secondarySize,
                  height: 1.25),
            ),
          ),
        ],
      ),
    );
  }
}

