class _ZoneDistribution extends StatelessWidget {
  const _ZoneDistribution({required this.track});
  final _RuntimeTrack track;

  @override
  Widget build(BuildContext context) {
    final walk = track.points
        .where((p) => p.speedKmh < 7)
        .fold<double>(0, (s, p) => s + p.distanceDeltaM);
    final jog = track.points
        .where((p) => p.speedKmh >= 7 && p.speedKmh < 11.5)
        .fold<double>(0, (s, p) => s + p.distanceDeltaM);
    final hir = track.hirDistanceM;
    final vhir = track.vhirDistanceM;
    final sprint = track.sprintDistanceM;
    final total = math.max(1.0, walk + jog + hir + vhir + sprint);

    return _LiveCard(
      padding: const EdgeInsets.all(5),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Зоны интенсивности',
              style: TextStyle(
                  color: _C.text, fontWeight: FontWeight.w500, fontSize: AppTypography.bodySize)),
          const SizedBox(height: 8),
          _ZoneLine(
              label: 'Ходьба', value: walk, total: total, color: _C.subtle),
          _ZoneLine(label: 'Бег', value: jog, total: total, color: _C.green),
          _ZoneLine(label: 'HIR', value: hir, total: total, color: _C.orange),
          _ZoneLine(
              label: 'VHIR',
              value: vhir,
              total: total,
              color: const Color(0xFFEAB308)),
          _ZoneLine(
              label: 'Спринт', value: sprint, total: total, color: _C.red),
        ],
      ),
    );
  }
}

class _ZoneLine extends StatelessWidget {
