class _LiveSourceSelector extends StatelessWidget {
  const _LiveSourceSelector({
    required this.value,
    required this.running,
    required this.heartRateOnline,
    required this.onChanged,
    required this.titleOf,
    required this.iconOf,
  });

  final TrackerLiveSourceMode value;
  final bool running;
  final bool heartRateOnline;
  final ValueChanged<TrackerLiveSourceMode> onChanged;
  final String Function(TrackerLiveSourceMode mode) titleOf;
  final IconData Function(TrackerLiveSourceMode mode) iconOf;

  @override
  Widget build(BuildContext context) {
    final modes = const <TrackerLiveSourceMode>[
      TrackerLiveSourceMode.trackerExperimental,
      TrackerLiveSourceMode.heartRateOnly,
    ];
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const Text('Источник Live',
          style: TextStyle(
              color: _OF.text, fontSize: AppTypography.secondarySize, fontWeight: FontWeight.w700)),
      const SizedBox(height: 6),
      Wrap(
        spacing: 6,
        runSpacing: 6,
        children: modes.map((mode) {
          final active = value == mode;
          final disabled = running;
          final hint =
              mode == TrackerLiveSourceMode.heartRateOnly && !heartRateOnline
                  ? ' · ждёт bpm'
                  : '';
          return _NoHoverTap(
            onTap: disabled ? null : () => onChanged(mode),
            borderRadius: BorderRadius.circular(6),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: active ? _OF.greenSoft : _OF.header,
                borderRadius: BorderRadius.circular(6),
                border: Border.all(color: active ? _OF.greenBorder : _OF.line),
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                Icon(iconOf(mode),
                    size: 15, color: active ? _OF.green : _OF.graphite),
                const SizedBox(width: 6),
                Text('${titleOf(mode)}$hint',
                    style: TextStyle(
                        color: active ? _OF.green : _OF.graphite,
                        fontSize: AppTypography.secondarySize,
                        fontWeight: FontWeight.w700)),
              ]),
            ),
          );
        }).toList(),
      ),
      if (value == TrackerLiveSourceMode.heartRateOnly) ...[
        const SizedBox(height: 6),
        const Text(
            'Этот режим запускает Live без GPS-трекера: online bpm от всех привязанных Polar H10 сохраняется в live_session_id и затем попадает в отчёт.',
            style: TextStyle(
                color: _OF.muted, fontSize: AppTypography.captionSize, fontWeight: FontWeight.w700)),
      ],
    ]);
  }
}

class _TeamHeartRateOnlineCard extends StatelessWidget {
  const _TeamHeartRateOnlineCard(
      {required this.players, required this.samples});

  final List<TrackerPlayerOption> players;
  final Map<int, HeartRateSample> samples;

  TrackerPlayerOption? _player(int id) {
    final found = players.where((p) => p.id == id).toList();
    return found.isEmpty ? null : found.first;
  }

  String _zone(int bpm) {
    if (bpm <= 0) return '—';
    if (bpm < 120) return 'Z1';
    if (bpm < 145) return 'Z2';
    if (bpm < 165) return 'Z3';
    if (bpm < 180) return 'Z4';
    return 'Z5';
  }

  @override
  Widget build(BuildContext context) {
    final entries = samples.entries.toList()
      ..sort((a, b) => b.value.measuredAt.compareTo(a.value.measuredAt));
    return Container(
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
          color: Colors.white, borderRadius: BorderRadius.circular(6)),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
              width: 30,
              height: 30,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                  color: _OF.greenSoft, borderRadius: BorderRadius.circular(6)),
              child: const Icon(Icons.groups_2_rounded,
                  color: _OF.green, size: 16)),
          const SizedBox(width: 8),
          Expanded(
              child: Text('Команда Polar H10 online',
                  style: const TextStyle(
                      color: _OF.text,
                      fontSize: AppTypography.secondarySize,
                      fontWeight: FontWeight.w700))),
          Text('${entries.length} игрок.',
              style: const TextStyle(
                  color: _OF.muted,
                  fontSize: AppTypography.secondarySize,
                  fontWeight: FontWeight.w700)),
        ]),
        const SizedBox(height: 8),
        if (entries.isEmpty)
          const Text('Нет назначенных Polar H10.',
              style: TextStyle(
                  color: _OF.muted,
                  fontSize: AppTypography.captionSize,
                  fontWeight: FontWeight.w700))
        else
          ...entries.take(12).map((entry) {
            final p = _player(entry.key);
            final sample = entry.value;
            final age = DateTime.now().difference(sample.measuredAt).inSeconds;
            final fresh = age <= 25;
            return Padding(
              padding: const EdgeInsets.only(bottom: 7),
              child: Row(children: [
                Icon(Icons.favorite_rounded,
                    size: 15, color: fresh ? _OF.red : _OF.muted),
                const SizedBox(width: 5),
                Expanded(
                    child: Text(p?.name ?? 'Игрок ${entry.key}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _OF.text,
                            fontSize: AppTypography.secondarySize,
                            fontWeight: FontWeight.w700))),
                Text(
                    '${sample.bpm} bpm · ${_zone(sample.bpm)}${fresh ? '' : ' · ${age}s'}',
                    style: TextStyle(
                        color: fresh ? _OF.text : _OF.muted,
                        fontSize: AppTypography.secondarySize,
                        fontWeight: FontWeight.w700)),
              ]),
            );
          }),
      ]),
    );
  }
}

class _HeartRateLiveCard extends StatelessWidget {
  const _HeartRateLiveCard({
    required this.sample,
    required this.teamOnlineCount,
    required this.recommendation,
  });

  final HeartRateSample? sample;
  final int teamOnlineCount;
  final String recommendation;

  @override
  Widget build(BuildContext context) {
    final ageSec = sample == null
        ? null
        : DateTime.now().difference(sample!.measuredAt).inSeconds;
    final fresh = sample != null && (ageSec ?? 999) <= 20;
    final bpmText =
        sample == null ? '—' : '${sample!.bpm} bpm${fresh ? '' : '*'}';
    final zoneText = sample == null
        ? 'нет Polar'
        : sample!.bpm < 120
            ? 'Z1'
            : sample!.bpm < 145
                ? 'Z2'
                : sample!.bpm < 165
                    ? 'Z3'
                    : sample!.bpm < 180
                        ? 'Z4'
                        : 'Z5';
    final battery =
        sample?.batteryPercent == null ? '—' : '${sample!.batteryPercent}%';

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(6),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 30,
                height: 30,
                decoration: BoxDecoration(
                    color: _OF.greenSoft,
                    borderRadius: BorderRadius.circular(6)),
                child: const Icon(Icons.monitor_heart_rounded,
                    color: _OF.green, size: 17),
              ),
              const SizedBox(width: 9),
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Polar H10 online',
                        style: TextStyle(
                            color: _OF.text,
                            fontSize: AppTypography.bodySize,
                            fontWeight: FontWeight.w700)),
                    SizedBox(height: 2),
                    Text('пульс игрока + командный контроль',
                        style: TextStyle(
                            color: _OF.muted,
                            fontSize: AppTypography.secondarySize,
                            fontWeight: FontWeight.w700)),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                decoration: BoxDecoration(
                    color: _OF.greenSoft,
                    borderRadius: BorderRadius.circular(99),
                    border: Border.all(color: _OF.greenBorder)),
                child: Text('online $teamOnlineCount',
                    style: const TextStyle(
                        color: _OF.green,
                        fontSize: AppTypography.captionSize,
                        fontWeight: FontWeight.w700)),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                  child: _SmallEventCounter(label: 'ПУЛЬС', value: bpmText)),
              const SizedBox(width: 8),
              Expanded(
                  child: _SmallEventCounter(label: 'ЗОНА', value: zoneText)),
              const SizedBox(width: 8),
              Expanded(
                  child: _SmallEventCounter(label: 'БАТ.', value: battery)),
            ],
          ),
          const SizedBox(height: 9),
          Text(
            recommendation,
            maxLines: 3,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
                color: _OF.text,
                fontSize: AppTypography.secondarySize,
                fontWeight: FontWeight.w600,
                height: 1.25),
          ),
        ],
      ),
