class _SpeedSparklinePainter extends CustomPainter {
  const _SpeedSparklinePainter({required this.points});
  final List<_RuntimePoint> points;

  @override
  void paint(Canvas canvas, Size size) {
    final grid = Paint()
      ..color = _C.divider.withOpacity(.65)
      ..strokeWidth = 1;
    for (var i = 1; i < 4; i++) {
      final y = size.height * i / 4;
      canvas.drawLine(Offset(0, y), Offset(size.width, y), grid);
    }

    if (points.length < 2) return;
    final src =
        points.length > 45 ? points.sublist(points.length - 45) : points;
    final maxSpeed = math.max(
        8.0,
        src
            .map((p) => p.speedKmh)
            .fold<double>(0, (m, v) => math.max(m, v).toDouble()));
    final path = Path();

    for (var i = 0; i < src.length; i++) {
      final x = src.length == 1 ? 0.0 : size.width * i / (src.length - 1);
      final y = size.height -
          (src[i].speedKmh / maxSpeed).clamp(0.0, 1.0) * size.height;
      if (i == 0)
        path.moveTo(x, y);
      else
        path.lineTo(x, y);
    }

    canvas.drawPath(
      path,
      Paint()
        ..color = _C.green
        ..strokeWidth = 2.4
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round,
    );
  }

  @override
  bool shouldRepaint(covariant _SpeedSparklinePainter oldDelegate) => true;
}

class _LivePeriod {
  const _LivePeriod({
    required this.title,
    required this.startRatio,
    required this.endRatio,
    required this.color,
    this.startTime,
    this.endTime,
    this.id,
  });

  final int? id;
  final String title;
  final double startRatio;
  final double endRatio;
  final Color color;
  final DateTime? startTime;
  final DateTime? endTime;

  _LivePeriod copyWith({
    int? id,
    String? title,
    double? startRatio,
    double? endRatio,
    Color? color,
    DateTime? startTime,
    DateTime? endTime,
  }) {
    return _LivePeriod(
      id: id ?? this.id,
      title: title ?? this.title,
      startRatio: startRatio ?? this.startRatio,
      endRatio: endRatio ?? this.endRatio,
      color: color ?? this.color,
      startTime: startTime ?? this.startTime,
      endTime: endTime ?? this.endTime,
    );
  }

  factory _LivePeriod.fromJson(Map<String, dynamic> json) {
    double toDouble(dynamic v, double fallback) {
      if (v is num) return v.toDouble();
      return double.tryParse('$v') ?? fallback;
    }

    DateTime? toDate(dynamic v) {
      final s = '$v'.trim();
      if (s.isEmpty || s == 'null') return null;
      return _trackerMoscowDateTime(s);
    }

    final colorValue =
        int.tryParse('${json['color_value'] ?? json['color'] ?? ''}');
    return _LivePeriod(
      id: int.tryParse('${json['id'] ?? ''}'),
      title: '${json['title'] ?? json['name'] ?? 'ПЕРИОД'}',
      startRatio: toDouble(json['start_ratio'], .05),
      endRatio: toDouble(json['end_ratio'], .18),
      color: colorValue == null ? _OF.cyan : Color(colorValue),
      startTime: toDate(json['started_at'] ?? json['start_time']),
      endTime: toDate(json['ended_at'] ?? json['end_time']),
    );
  }

  Map<String, dynamic> toJson() {
    String? dt(DateTime? value) => value?.toIso8601String();
    return {
      'id': id,
      'title': title,
      'start_ratio': startRatio,
      'end_ratio': endRatio,
      'color_value': color.value,
      'started_at': dt(startTime),
      'ended_at': dt(endTime),
    };
  }
}

class _OpenFieldTimelinePainter extends CustomPainter {
  const _OpenFieldTimelinePainter(
      {required this.points,
      required this.running,
      required this.progressRatio});
  final List<_RuntimePoint> points;
  final bool running;
  final double progressRatio;

  @override
  void paint(Canvas canvas, Size size) {
    final baselineY = size.height / 2;
    final linePaint = Paint()
      ..color = _OF.lineStrong
      ..strokeWidth = 2
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(
        Offset(4, baselineY), Offset(size.width - 4, baselineY), linePaint);

    final src =
        points.length > 160 ? points.sublist(points.length - 160) : points;
    if (src.length >= 2) {
      final start = src.first.timeMs;
      final span = math.max(1, src.last.timeMs - start);
      for (var i = 1; i < src.length; i++) {
        final p = src[i];
        final prev = src[i - 1];
        final ratio = ((p.timeMs - start) / span).clamp(0.0, 1.0).toDouble();
        final x = 4 + (size.width - 8) * ratio;
        final dt = math.max(0.2, (p.timeMs - prev.timeMs) / 1000.0);
        final accel = ((p.speedKmh - prev.speedKmh) / 3.6) / dt;
        Color? color;
        double radius = 2.0;
        if (p.speedKmh >= 18.0) {
          color = _OF.red;
          radius = 3.4;
        } else if (p.speedKmh >= 14.0) {
          color = _OF.cyan;
          radius = 3.0;
        } else if (p.speedKmh >= 11.5) {
          color = _OF.orange;
          radius = 2.7;
        } else if (accel >= 2.0) {
          color = _OF.green;
          radius = 2.4;
        } else if (accel <= -2.0) {
          color = _OF.blue;
          radius = 2.4;
        }
        if (color != null) {
          canvas.drawCircle(Offset(x, baselineY), radius + 2,
              Paint()..color = color.withOpacity(.06));
          canvas.drawCircle(
              Offset(x, baselineY), radius, Paint()..color = color);
        }
      }
    }

    if (running) {
      final x = 4 + (size.width - 8) * progressRatio.clamp(0.0, 1.0);
      canvas.drawLine(
          Offset(x, baselineY - 9),
          Offset(x, baselineY + 9),
          Paint()
            ..color = _OF.green
            ..strokeWidth = 2);
      canvas.drawCircle(Offset(x, baselineY), 4, Paint()..color = Colors.white);
      canvas.drawCircle(Offset(x, baselineY), 3, Paint()..color = _OF.green);
    }
  }

  @override
  bool shouldRepaint(covariant _OpenFieldTimelinePainter oldDelegate) => true;
}

