class _ProblemBox extends StatelessWidget {
  const _ProblemBox({required this.text});
  final String text;

  @override
  Widget build(BuildContext context) {
    final isBad = text.toLowerCase().contains('ошибка') ||
        text.toLowerCase().contains('нет ');
    final color = isBad ? _C.red : _C.green;
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: isBad ? _C.redSoft : Colors.white,
        borderRadius: BorderRadius.circular(6),
        border: Border.all(color: isBad ? _C.red.withOpacity(.08) : _C.divider),
      ),
      child: Row(
        children: [
          Container(
            width: 30,
            height: 30,
            decoration: BoxDecoration(
              color: isBad ? _C.redSoft : _C.greenSoft,
              borderRadius: BorderRadius.circular(6),
              border: Border.all(color: color.withOpacity(.06)),
            ),
            child: Icon(
                isBad ? Icons.warning_amber_rounded : Icons.check_rounded,
                color: color,
                size: 18),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              text,
              maxLines: 3,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                  color: isBad ? _C.red : _C.text,
                  fontSize: AppTypography.secondarySize,
                  fontWeight: FontWeight.w500,
                  height: 1.25),
            ),
          ),
        ],
      ),
    );
  }
}

